def _city_movement_frame(memory: BattlePolicyMemory, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """One actual Scene/battle state, with no synthesized D high words or A7."""
    if type(memory) is not BattlePolicyMemory or type(frame) is not FirstDeploymentFrame:
        raise ValueError('same-state movement memory and real deployment frame required')
    frame.validate(memory.state, frame.stack_cursor is not None)
    for value in (frame.target_x, frame.target_y, frame.unit, frame.count,
                  frame.distance, frame.offset_x, frame.offset_y, frame.choice):
        uint(value, 32)
    return frame

def _city_movement_bit(frame: FirstDeploymentFrame, bit, enabled: bool) -> FirstDeploymentFrame:
    """Actual D2 BTST/BSET: only Z changes, not C/N/V/X or a high WORD."""
    if type(enabled) is not bool or bit not in (0, 1):
        raise ValueError('actual movement sign bit required')
    was_set = bool(frame.unit & (1 << bit))
    status = None if frame.status is None else ((frame.status & 27) | (0 if was_set else 4))
    return first_replace(frame, unit=u32(frame.unit | (1 << bit)) if enabled else frame.unit, status=status)

def _city_movement_long_shift(frame: FirstDeploymentFrame, name) -> FirstDeploymentFrame:
    """The original fixed seven-bit LONG LSL, including X/C and wrapping."""
    original = frame.carrier(name)
    value = u32(original << 7)
    carried = bool(original & (1 << 25))
    status = (17 if carried else 0) | (8 if value & 2147483648 else 0) | (4 if value == 0 else 0)
    return first_replace(frame, **{name: value}, status=status)

def _city_movement_divide(frame: FirstDeploymentFrame, name, divisor, original_target) -> FirstDeploymentFrame:
    """Original packed DIVU; exceptions and undefined overflow flags stay boundaries."""
    uint(divisor, 16)
    original = frame.carrier(name)
    if divisor == 0:
        raise Boundary('original unsigned divide by zero')
    quotient, remainder = divmod(original, divisor)
    if quotient > 65535:
        raise FirstDeploymentArithmeticBoundary(original_target, first_replace(frame, status=None), original)
    status = (frame.status & 16) | (8 if quotient & 32768 else 0) | (4 if quotient == 0 else 0)
    return first_replace(frame, **{name: u32(remainder << 16 | quotient)}, status=status)

def _city_movement_radial(memory: BattlePolicyMemory, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1DCF8's six-byte JSR, actual1DCFE token and full3080E returned carriers."""
    if frame.stack_cursor is None:
        return rounded_deployment_radial_distance_fields(memory, frame)
    stack = frame.stack_cursor.advance(-4)
    stack.set_long(0, 0x1DCFE)
    returned = rounded_deployment_radial_distance_fields(memory, first_replace(frame, stack_cursor=stack))
    returned.validate(memory.state, True)
    target = returned.stack_cursor.long()
    if target != 0x1DCFE:
        raise FirstDeploymentReturnBoundary(target, returned, 0x1DCFE)
    return first_replace(returned, stack_cursor=returned.stack_cursor.advance(4))

def city_calculate_live_quotient_10_fields(memory: BattlePolicyMemory, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1DCAA sole movement-velocity setup, including the1DCBA shared tail."""
    frame = _city_movement_frame(memory, frame)
    frame = _first_word(frame, 'target_y', low16(frame.choice))
    frame = _first_shift_word(frame, 'target_y', low16(frame.target_y), 2)
    targets = memory.state.table(0xFFFFA150).cursor()
    frame = first_replace(frame, candidates=targets)
    frame = _first_word(frame, 'offset_x', targets.word(low16(frame.target_y)))
    frame = _first_word(frame, 'offset_y', targets.word(low16(frame.target_y), 2))
    return city_calculate_live_quotient_10_alternate_fields(memory, frame)

def city_calculate_live_quotient_10_alternate_fields(memory: BattlePolicyMemory, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Sole1DCBA..1DD80 tail; A5 is the zero-distance latch, not A2."""
    frame = _city_movement_frame(memory, frame)
    frame = _first_word(frame, 'unit', 0)
    positions = memory.state.table(0x00FF2C00).cursor()
    frame = first_replace(frame, roster=positions)
    frame = _first_word(frame, 'count', positions.word(low16(frame.target_y)))
    frame = _first_shift_word(frame, 'count', low16(frame.count), 7)
    left, right = low16(frame.count), low16(frame.offset_x)
    frame = _first_sub_word(frame, 'count', left, right)
    if left < right:
        frame = _first_sub_word(frame, 'count', 0, low16(frame.count))
        frame = _city_movement_bit(frame, 0, True)
    frame = _first_add_word(frame, 'count', low16(frame.count), 64)
    frame = _first_right_word(frame, 'count', low16(frame.count), 7)
    frame = _first_word(frame, 'distance', positions.word(low16(frame.target_y), 2))
    frame = _first_shift_word(frame, 'distance', low16(frame.distance), 7)
    left, right = low16(frame.distance), low16(frame.offset_y)
    frame = _first_sub_word(frame, 'distance', left, right)
    if left < right:
        frame = _first_sub_word(frame, 'distance', 0, low16(frame.distance))
        frame = _city_movement_bit(frame, 1, True)
    frame = _first_add_word(frame, 'distance', low16(frame.distance), 64)
    frame = _first_right_word(frame, 'distance', low16(frame.distance), 7)
    frame = _first_word(frame, 'target_x', low16(frame.count))
    frame = _first_long(frame, 'target_x', low16(frame.target_x) * low16(frame.target_x))
    frame = _first_word(frame, 'target_y', low16(frame.distance))
    frame = _first_long(frame, 'target_y', low16(frame.target_y) * low16(frame.target_y))
    left, right = frame.target_x, frame.target_y
    total = u32(left + right)
    overflow = bool((~(left ^ right) & (left ^ total)) & 2147483648)
    status = (17 if left + right > 4294967295 else 0) | (2 if overflow else 0) | (8 if total & 2147483648 else 0) | (4 if total == 0 else 0)
    frame = first_replace(frame, target_x=total, status=status)
    frame = _city_movement_radial(memory, frame)
    frame = _first_long(frame, 'target_x', frame.target_x & 65535)
    if frame.target_x == 0:
        frame = _first_word(frame, 'count', 0)
        frame = _first_word(frame, 'distance', 0)
        latch = memory.state.table(0xFFFFAE28).cursor()
        frame = first_replace(frame, scratch=latch)
        latch.byte(low16(frame.choice))
        latch.set_byte(low16(frame.choice), 0)
        frame = first_replace(frame, status=(frame.status & 16) | 4)
    else:
        frame = _city_movement_long_shift(frame, 'target_x')
        speeds = memory.state.table(0xFFFFC400).cursor()
        frame = first_replace(frame, roster=speeds)
        frame = _first_word(frame, 'target_y', 0)
        frame = _first_byte(frame, 'target_y', speeds.byte(low16(frame.choice)))
        frame = _city_movement_divide(frame, 'target_x', low16(frame.target_y), 0x1DD14)
        frame = _first_long(frame, 'count', frame.count & 65535)
        frame = _city_movement_long_shift(frame, 'count')
        if frame.count != 0:
            frame = _city_movement_divide(frame, 'count', low16(frame.target_x), 0x1DD22)
            frame = _city_movement_bit(frame, 0, False)
            if not frame.status & 4:
                frame = _first_sub_word(frame, 'count', 0, low16(frame.count))
        frame = _first_long(frame, 'distance', frame.distance & 65535)
        frame = _city_movement_long_shift(frame, 'distance')
        if frame.distance != 0:
            frame = _city_movement_divide(frame, 'distance', low16(frame.target_x), 0x1DD3A)
            frame = _city_movement_bit(frame, 1, False)
            if not frame.status & 4:
                frame = _first_sub_word(frame, 'distance', 0, low16(frame.distance))
    velocities = memory.state.table(0xFFFFA960).cursor()
    frame = first_replace(frame, roster=velocities)
    frame = _first_shift_word(frame, 'choice', low16(frame.choice), 2)
    frame = _first_word(frame, 'offset_x', memory.state.read(0xFFFFF70A, 2))
    frame = _first_word(frame, 'offset_x', low16(frame.offset_x) & 3)
    speed = low16(frame.offset_x)
    if speed != 0:
        # Original variable ASL.W and following ASR.W3 wrap BEFORE sign shift.
        # Their intermediate flags are overwritten by the immediately following
        # ADD.W, which supplies the eventual X used by both memory MOVEs.
        frame = _first_word(frame, 'offset_y', low16(frame.count))
        adjustment = u16(s16(u16(low16(frame.offset_y) << speed)) >> 3)
        frame = _first_word(frame, 'offset_y', adjustment)
        frame = _first_add_word(frame, 'count', low16(frame.count), low16(frame.offset_y))
        frame = _first_word(frame, 'offset_y', low16(frame.distance))
        adjustment = u16(s16(u16(low16(frame.offset_y) << speed)) >> 3)
        frame = _first_word(frame, 'offset_y', adjustment)
        frame = _first_add_word(frame, 'distance', low16(frame.distance), low16(frame.offset_y))
    velocities.set_word(low16(frame.choice), low16(frame.count))
    frame = _first_memory_word(frame, low16(frame.count))
    velocities.set_word(low16(frame.choice), low16(frame.distance), 2)
    frame = _first_memory_word(frame, low16(frame.distance))
    return frame.validate(memory.state, frame.stack_cursor is not None)

def _city_movement_legacy_frame(inputs, source) -> FirstDeploymentFrame:
    """Old8LONG/A1/A5 observations only; A2 and entry SP remain unobserved."""
    return first_replace(FirstDeploymentFrame.unobserved(),
        target_x=inputs.value, target_y=inputs.field, unit=inputs.tile,
        count=inputs.row, distance=inputs.offset, offset_x=inputs.limit,
        offset_y=inputs.member, choice=inputs.remaining,
        candidates=source, scratch=inputs.roster)

def city_resolve_readonly_state_4_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A7F4 sole resource debit, including the actual live LONG pointer table."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('sole actual presentation fields required')
    frame.validate(state, frame.stack_cursor is not None)
    selector = state.read(0xFFFFF6D6, 2)
    frame = _first_word(frame, 'target_x', selector)
    frame = _first_shift_word(frame, 'target_x', selector, 2)
    pointer = state.read(u32(0x1A808 + s16(u16(selector << 2))), 4)
    resource = state.table(pointer).cursor()
    frame = first_replace(frame, roster=resource)
    available = resource.long()
    frame = _first_long(frame, 'target_x', available)
    required = state.read(0xFFFFF39E, 4)
    frame = _presentation_sub_long_fields(frame, 'target_x', available, required)
    resource.set_long(0, frame.target_x)
    frame = _first_long(frame, 'target_x', frame.target_x)
    state.sr = (state.sr & 65504) | frame.status
    return frame.validate(state, frame.stack_cursor is not None)

def city_coordinate_live_state_76_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A47A live table dispatch; recovered normal and status targets are admitted.

    The table WORD and signed displacement are genuine ordered DATA. Unknown
    targets stop after the original internal 1A490 LONG slot, not success.
    """
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('sole actual presentation fields required')
    frame.validate(state, frame.stack_cursor is not None)
    state.write(0x00FF7026, 2, 65535)
    frame = _first_memory_word(frame, 65535)
    mode = state.read(0xFFFFF6D4, 2)
    frame = _first_word(frame, 'target_x', mode)
    frame = _first_shift_word(frame, 'target_x', mode, 1)
    offset = state.read(u32(0x1A492 + s16(u16(mode << 1))), 2)
    frame = _first_word(frame, 'target_x', offset)
    target = u32(0x1A49E + s16(offset))
    if frame.stack_cursor is not None:
        stack = frame.stack_cursor.advance(-4)
        stack.set_long(0, 0x1A490)
        frame = first_replace(frame, stack_cursor=stack)
    if frame.status is not None:
        state.sr = (state.sr & 65504) | frame.status
    if target == 0x1A49E:
        from .business_city import city_calculate_live_quotient_2_fields
        returned = city_calculate_live_quotient_2_fields(state, frame)
    elif target == 0x1A818:
        returned = city_calculate_live_quotient_3_fields(state, frame)
    elif target == 0x1A9B0:
        returned = city_calculate_live_quotient_4_fields(state, frame)
    elif target == 0x1AC26:
        returned = city_calculate_live_quotient_6_fields(state, frame)
    else:
        raise Boundary('original dynamic presentation target is not field-closed: ' + str(target))
    if type(returned) is not FirstDeploymentFrame:
        raise Boundary('presentation child must return genuine current full fields')
    returned.validate(state, frame.stack_cursor is not None)
    if returned.stack_cursor is not None:
        actual = returned.stack_cursor.long()
        if actual != 0x1A490:
            raise Boundary('original internal presentation return slot changed to ' + str(actual))
        returned = first_replace(returned, stack_cursor=returned.stack_cursor.advance(4))
    if returned.status is not None:
        state.sr = (state.sr & 65504) | returned.status
    return returned.validate(state, frame.stack_cursor is not None)


# Sole normal special-action fields; named aliases reuse current cores.
from .services import (_movement_frame, _movement_test, _movement_move, _movement_compare, _movement_shift_word, _movement_add_byte, _movement_fixed_shift_word, _movement_add_word, _movement_move_long, _movement_binary_flags, _movement_arithmetic_long, _movement_test_long, _movement_multiply_word, _movement_divu_word, sample_battle_action_random_fields, _battle_action_map_fields, _deployment_terrain_lookup, MovementContinuationBoundary, BattlePresentationMemory, sample_battle_special_status_factor_fields, compute_battle_damage_potential_fields)
def _special_action_frame(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Require passed CPU fields; never complete an old draft using zeros."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('actual special-action field frame required')
    frame.validate(state)
    if any(value is None for value in (
            frame.target_x, frame.target_y, frame.unit, frame.count,
            frame.distance, frame.offset_x, frame.offset_y, frame.choice,
            frame.roster, frame.candidates, frame.controller, frame.scan,
            frame.opponent, frame.scratch, frame.auxiliary,
            frame.stack_cursor, frame.status)):
        raise MovementContinuationBoundary(0x1A49E, frame,
            'historical special-action projection lacks actual complete entry fields')
    return _movement_frame(state, frame)

def _special_action_call(state: SceneState, frame: FirstDeploymentFrame, target, continuation) -> FirstDeploymentFrame:
    """Only this actual BSR/JSR return LONG belongs to this caller."""
    uint(target, 32)
    uint(continuation, 32)
    stack = frame.stack_cursor.advance(-4)
    stack.set_long(0, continuation)
    entered = first_replace(frame, stack_cursor=stack)
    state.sr = (state.sr & 65504) | entered.status
    if target == 0x1A7F4:
        result = city_resolve_readonly_state_4_fields(state, entered)
    elif target == 0x1A706:
        result = sample_battle_special_status_factor_fields(BattlePresentationMemory(state), entered)
    elif target == 0x1A7A2:
        result = compute_battle_damage_potential_fields(BattlePresentationMemory(state), entered, entered.target_x)
    elif target == 0x1A99C:
        result = city_update_live_fields_10_fields(state, entered)
    elif target == 0x1A438:
        result = _battle_action_map_fields(BattlePolicyMemory(state), entered)
    elif target == 0x1ABCC:
        result = city_calculate_live_quotient_5_fields(state, entered)
    elif target == 0x1AC04:
        result = city_update_live_fields_11_fields(state, entered)
    elif target == 0x1AF5C:
        result = city_resolve_readonly_state_5_fields(state, entered)
    elif target == 0x1AD46:
        result = city_scale_live_record_value_1_fields(state, entered)
    elif target == 0x1AE1C:
        result = city_scale_live_record_value_2_fields(state, entered)
    elif target == 0x1AEA0:
        result = city_coordinate_live_state_77_fields(state, entered)
    elif target == 0x1AEC6:
        result = city_coordinate_live_state_78_fields(state, entered)
    elif target == 0x208CE:
        result = apply_returning_officer_loyalty_fields(BattlePresentationMemory(state), entered)
    else:
        result = state.service_at(target, entered)
    result = _special_action_frame(state, result)
    state.sr = (state.sr & 65504) | result.status
    returned = result.stack_cursor.long()
    result = first_replace(result, stack_cursor=result.stack_cursor.advance(4))
    if returned != continuation:
        raise FirstDeploymentReturnBoundary(returned, result, continuation)
    return result

def _special_action_shift_long(state: SceneState, frame: FirstDeploymentFrame, carrier: str, amount: int) -> FirstDeploymentFrame:
    """Closed original #1/#2/#4 LSL.L forms, not a general instruction engine."""
    if amount not in (1, 2, 4):
        raise ValueError('actual special-action LONG shift required')
    original = frame.carrier(carrier)
    value = u32(original << amount)
    carry = bool(original & (1 << (32 - amount)))
    status = (17 if carry else 0) | (8 if value & 2147483648 else 0) | (4 if value == 0 else 0)
    state.sr = (state.sr & 65504) | status
    return first_replace(frame, **{carrier: value}, status=status)

def _special_action_swap(state: SceneState, frame: FirstDeploymentFrame, carrier: str) -> FirstDeploymentFrame:
    return _movement_move_long(state, frame, carrier, swap_words(frame.carrier(carrier)))

def _special_action_sub_word(state: SceneState, frame: FirstDeploymentFrame, carrier: str, source) -> FirstDeploymentFrame:
    frame, value = _movement_binary_flags(state, frame, low16(frame.carrier(carrier)), uint(source, 16), 16, True)
    return first_replace(frame, **{carrier: replace_word(frame.carrier(carrier), value)})

def _special_action_store_word(state: SceneState, frame: FirstDeploymentFrame, destination, index, carrier: str) -> FirstDeploymentFrame:
    value = low16(frame.carrier(carrier))
    destination.set_word(index, value)
    return _movement_test(state, frame, value, 16)

def _special_action_seed_step(state: SceneState, frame: FirstDeploymentFrame, carrier: str, scratch: str) -> FirstDeploymentFrame:
    """Fresh F61C read after RNG, followed by the original fivefold scaling."""
    frame = _movement_move_long(state, frame, carrier, 0)
    frame = _movement_move(state, frame, carrier, state.read(0xFFFFF61C, 2), 16)
    frame = _movement_move_long(state, frame, scratch, frame.carrier(carrier))
    frame = _special_action_shift_long(state, frame, carrier, 2)
    frame = _movement_arithmetic_long(state, frame, carrier, frame.carrier(scratch))
    frame = _special_action_swap(state, frame, carrier)
    return _movement_add_word(state, frame, carrier, 1)

def _special_action_decrease_status(state: SceneState, frame: FirstDeploymentFrame, amount: str) -> FirstDeploymentFrame:
    """Original SUB.B saturation retains both the write and CLR's fresh read."""
    statuses = frame.roster
    index = low16(frame.target_x)
    original = statuses.byte(index)
    frame, value = _movement_binary_flags(state, frame, original, low8(frame.carrier(amount)), 8, True)
    statuses.set_byte(index, value)
    if frame.status & 1:
        statuses.byte(index)
        statuses.set_byte(index, 0)
        frame = _movement_test(state, frame, 0, 8)
    return frame

def _special_action_damage_loss(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A4B0..1A514: troop and attribute debit, original D2 store retained."""
    frame = _movement_move_long(state, frame, 'choice', frame.choice & 65535)
    frame = _movement_divu_word(state, frame, 'choice', 100, 0x1A4B6)
    frame = first_replace(frame, roster=state.table_at(0xFFFFC800).cursor())
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 2)
    frame = _movement_move_long(state, frame, 'unit', frame.roster.long(low16(frame.target_y)))
    frame = _movement_move_long(state, frame, 'offset_y', frame.unit)
    frame = _movement_multiply_word(state, frame, 'offset_y', low16(frame.target_x))
    frame = _movement_divu_word(state, frame, 'offset_y', 1000, 0x1A4CC)
    frame = _movement_move_long(state, frame, 'offset_y', frame.offset_y & 65535)
    frame = _movement_arithmetic_long(state, frame, 'unit', frame.offset_y, True)
    frame.roster.set_long(low16(frame.target_y), frame.unit)
    frame = _movement_test_long(state, frame, frame.unit)
    state.write(0xFFFFF3C8, 4, frame.offset_y)
    frame = _movement_test_long(state, frame, frame.offset_y)
    frame = _movement_compare(state, frame, low16(frame.choice), 5, 16)
    if not frame.status & 5:
        frame = _movement_move(state, frame, 'target_x', 10, 16)
        frame = _special_action_sub_word(state, frame, 'target_x', low16(frame.choice))
        frame = _movement_compare(state, frame, low16(frame.target_x), 5, 16)
        if not frame.status & 5:
            frame = _movement_move(state, frame, 'target_x', 5, 16)
        frame = first_replace(frame, roster=state.table_at(0xFFFFB200).cursor())
        frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A6, 2), 16)
        frame = _movement_shift_word(state, frame, 'target_y')
        frame = _movement_move(state, frame, 'unit', frame.roster.word(low16(frame.target_y)), 16)
        frame = _movement_move(state, frame, 'count', low16(frame.unit), 16)
        frame = _movement_multiply_word(state, frame, 'unit', low16(frame.target_x))
        frame = _movement_divu_word(state, frame, 'unit', 10, 0x1A50A)
        frame = _special_action_sub_word(state, frame, 'count', low16(frame.unit))
        # confirmed1A510 writes the computed fraction D2, not residual D3.
        frame = _special_action_store_word(state, frame, frame.roster, low16(frame.target_y), 'unit')
    return frame

def _special_action_positive_status(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A514..1A56A: actor status loss, target status gain capped at99."""
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1A51A)
    frame = _special_action_seed_step(state, frame, 'target_y', 'unit')
    frame = first_replace(frame, roster=state.table_at(0xFFFFC500).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = _special_action_decrease_status(state, frame, 'target_y')
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1A542)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 1)
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)
    frame = _movement_add_byte(state, frame, 'unit', low8(frame.target_x))
    frame = _movement_compare(state, frame, low8(frame.unit), 99, 8)
    if not frame.status & 5:
        frame = _movement_move(state, frame, 'unit', 99, 8)
    frame.roster.set_byte(low16(frame.target_y), low8(frame.unit))
    return _movement_test(state, frame, low8(frame.unit), 8)

def _special_action_add_capped_word(state: SceneState, frame: FirstDeploymentFrame, destination, index, carrier: str, increment) -> FirstDeploymentFrame:
    """Live WORD read/add/cap/store retains overflow wrap before the cap."""
    frame = _movement_move(state, frame, carrier, destination.word(index), 16)
    frame = _movement_add_word(state, frame, carrier, uint(increment, 16))
    frame = _movement_compare(state, frame, low16(frame.carrier(carrier)), 999, 16)
    if not frame.status & 5:
        frame = _movement_move(state, frame, carrier, 999, 16)
    return _special_action_store_word(state, frame, destination, index, carrier)

def _special_action_positive_rewards(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A56A..1A5E8: actor/target reward words use their real live pointers."""
    frame = first_replace(frame, roster=state.table_at(0xFFFFC000).cursor(),
        candidates=state.table_at(0xFFFFBE00).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    frame = _movement_move(state, frame, 'target_y', low16(frame.choice), 16)
    frame = _special_action_add_capped_word(state, frame, frame.roster, low16(frame.target_x), 'unit', low16(frame.target_y))
    frame = _movement_shift_word(state, frame, 'target_y')
    frame = _special_action_add_capped_word(state, frame, frame.candidates, low16(frame.target_x), 'unit', low16(frame.target_y))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    frame = _movement_move_long(state, frame, 'offset_y', frame.offset_y & 65535)
    frame = _movement_divu_word(state, frame, 'offset_y', 200, 0x1A5B2)
    frame = _special_action_add_capped_word(state, frame, frame.candidates, low16(frame.target_x), 'unit', low16(frame.offset_y))
    frame = _movement_multiply_word(state, frame, 'offset_y', 3)
    frame = _movement_divu_word(state, frame, 'offset_y', 10, 0x1A5CE)
    return _special_action_add_capped_word(state, frame, frame.roster, low16(frame.target_x), 'unit', low16(frame.offset_y))

def _special_action_message_category(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A5E8..1A636: sole map/terrain ABIs, then real full-SR carry clear."""
    state.write(0x00FF7026, 2, 32)
    frame = _movement_test(state, frame, 32, 16)
    frame = _movement_test(state, frame, state.read(0xFFFFF6D4, 2), 16)
    if frame.status & 4:
        state.write(0x00FF7026, 2, 30)
        frame = _movement_test(state, frame, 30, 16)
        frame = _special_action_call(state, frame, 0x1A438, 0x1A604)
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)
        frame = first_replace(frame, candidates=state.table_at(0xFFFFA150).cursor())
        frame = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)
        frame = _first_right_word(frame, 'target_y', low16(frame.target_y), 7)
        state.sr = (state.sr & 65504) | frame.status
        frame = _movement_move(state, frame, 'unit', frame.candidates.word(low16(frame.target_x), 2), 16)
        frame = _first_right_word(frame, 'unit', low16(frame.unit), 7)
        state.sr = (state.sr & 65504) | frame.status
        frame, terrain = _deployment_terrain_lookup(BattlePolicyMemory(state), frame,
            low16(frame.target_y), low16(frame.unit), 0x1A61E)
        frame = _movement_compare(state, frame, low8(frame.target_x), 1, 8)
        if frame.status & 4:
            state.write(0x00FF7026, 2, 31)
            frame = _movement_test(state, frame, 31, 16)
    # ANDI.W #FFFE,SR is a full-SR write, not a carry-only fake return.
    state.set_status_word(state.read_status_word() & 65534)
    return first_replace(frame, status=state.sr & 31)

def _special_action_zero_damage(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A636..1A704: failed-action status/rewards and full-SR carry set."""
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1A63C)
    frame = _special_action_seed_step(state, frame, 'unit', 'count')
    frame = first_replace(frame, roster=state.table_at(0xFFFFC500).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3F2, 2), 16)
    frame = _special_action_decrease_status(state, frame, 'unit')
    frame = first_replace(frame, roster=state.table_at(0xFFFFB600).cursor(),
        candidates=state.table_at(0xFFFFC000).cursor(),
        controller=state.table_at(0xFFFFBE00).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    frame = _movement_move(state, frame, 'unit', frame.roster.word(low16(frame.target_x)), 16)
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_y')
    frame = _special_action_sub_word(state, frame, 'unit', frame.roster.word(low16(frame.target_y)))
    if not frame.status & 1:
        frame = _movement_move_long(state, frame, 'unit', frame.unit & 65535)
        frame = _movement_divu_word(state, frame, 'unit', 10, 0x1A688)
        frame = _special_action_add_capped_word(state, frame, frame.controller, low16(frame.target_y), 'count', low16(frame.unit))
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1A6A6)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _special_action_shift_long(state, frame, 'target_x', 4)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 5)
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_shift_word(state, frame, 'unit')
    frame = _special_action_add_capped_word(state, frame, frame.candidates, low16(frame.unit), 'count', low16(frame.target_x))
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1A6D4)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 10)
    frame = _special_action_add_capped_word(state, frame, frame.controller, low16(frame.unit), 'count', low16(frame.target_x))
    state.set_status_word(state.read_status_word() | 1)
    return first_replace(frame, status=state.sr & 31)

def city_calculate_live_quotient_2_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Confirmed1A49E..1A706 normal special-action body, one complete Scene core.

    D0..D7 and A0..A7 are current passed fields on shared RAM. The caller owns
    the outer return slot. This body owns only its listed nested tokens and
    does not turn an unknown map, RNG, child or interrupt into fake success.
    """
    frame = _special_action_frame(state, frame)
    frame = _special_action_call(state, frame, 0x1A7F4, 0x1A4A2)
    frame = _special_action_call(state, frame, 0x1A706, 0x1A4A6)
    frame = _special_action_call(state, frame, 0x1A7A2, 0x1A4AA)
    frame = _movement_test(state, frame, low16(frame.choice), 16)
    if frame.status & 4:
        frame = _special_action_zero_damage(state, frame)
    else:
        frame = _special_action_damage_loss(state, frame)
        frame = _special_action_positive_status(state, frame)
        frame = _special_action_positive_rewards(state, frame)
        frame = _special_action_message_category(state, frame)
    return _special_action_frame(state, frame)

def _status_action_frame(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A818 requires real full entry fields; no legacy zeros or fake A7."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('sole current status-action fields required')
    frame.validate(state, frame.stack_cursor is not None)
    if any(value is None for value in (
            frame.target_x, frame.target_y, frame.unit, frame.count,
            frame.distance, frame.offset_x, frame.offset_y, frame.choice,
            frame.roster, frame.candidates, frame.controller, frame.scan,
            frame.opponent, frame.scratch, frame.auxiliary,
            frame.stack_cursor, frame.status)):
        raise MovementContinuationBoundary(0x1A818, frame,
            'historical status-action projection lacks actual complete entry fields')
    return _movement_frame(state, frame)

def city_update_live_fields_10_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A99C sole target-action clear; retain CLR's real BYTE read/write."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('sole current target-action-clear fields required')
    frame.validate(state, frame.stack_cursor is not None)
    target = state.read(0xFFFFF3A6, 2)
    frame = _first_word(frame, 'target_x', target)
    actions = state.table_at(0xFFFFAE28).cursor()
    frame = first_replace(frame, roster=actions)
    actions.byte(target)
    actions.set_byte(target, 0)
    frame = _first_memory_word(frame, 0)
    if frame.status is None:
        # Only NZVC are returned by the historical facade; its X is unobserved.
        state.sr = (state.sr & 65520) | 4
    else:
        state.sr = (state.sr & 65504) | frame.status
    return frame.validate(state, frame.stack_cursor is not None)

def _status_action_success(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A828..1A8F4: action severity plus actor/target capped progress words."""
    frame = _movement_move_long(state, frame, 'choice', frame.choice & 65535)
    frame = _movement_divu_word(state, frame, 'choice', 100, 0x1A82E)
    frame = _movement_move(state, frame, 'target_y', low16(frame.choice), 16)
    frame = _movement_compare(state, frame, low16(frame.target_y), 5, 16)
    if not frame.status & 5:
        frame = _movement_move(state, frame, 'target_y', 5, 16)
    frame = _movement_shift_word(state, frame, 'target_y')
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFA654).cursor())
    frame.roster.set_byte(low16(frame.target_x), low8(frame.target_y))
    frame = _movement_test(state, frame, low8(frame.target_y), 8)
    frame = _special_action_call(state, frame, 0x1A99C, 0x1A850)
    frame = first_replace(frame, roster=state.table_at(0xFFFFBE00).cursor(),
        candidates=state.table_at(0xFFFFC000).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    frame = _movement_move(state, frame, 'target_y', low16(frame.choice), 16)
    frame = _movement_shift_word(state, frame, 'target_y')
    frame = _movement_add_word(state, frame, 'target_y', low16(frame.choice))
    frame = _special_action_add_capped_word(state, frame, frame.roster,
        low16(frame.target_x), 'unit', low16(frame.target_y))
    frame = _movement_multiply_word(state, frame, 'target_y', 3)
    frame = _movement_divu_word(state, frame, 'target_y', 10, 0x1A87C)
    frame = _special_action_add_capped_word(state, frame, frame.candidates,
        low16(frame.target_x), 'unit', low16(frame.target_y))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    frame = _special_action_add_capped_word(state, frame, frame.roster,
        low16(frame.target_x), 'unit', low16(frame.choice))
    frame = _movement_move(state, frame, 'target_y', low16(frame.choice), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 1, True)
    frame = _special_action_add_capped_word(state, frame, frame.candidates,
        low16(frame.target_x), 'unit', low16(frame.target_y))
    mode = state.read(0xFFFFF6D4, 2)
    frame = _movement_compare(state, frame, mode, 5, 16)
    message = 34 if frame.status & 4 else 33
    state.write(0x00FF7026, 2, message)
    frame = _movement_test(state, frame, message, 16)
    state.set_status_word(state.read_status_word() & 65534)
    return first_replace(frame, status=state.sr & 31)

def _status_action_failure(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A8F4..1A99C: real failed-action rewards, both final stores use A1.

    The original 1A980/1A992 addressing is C000 via A1, not BE00 via A2;
    no inferred correction is substituted for those two physical operands.
    """
    frame = first_replace(frame, roster=state.table_at(0xFFFFB600).cursor(),
        candidates=state.table_at(0xFFFFC000).cursor(),
        controller=state.table_at(0xFFFFBE00).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    frame = _movement_move(state, frame, 'unit', frame.roster.word(low16(frame.target_x)), 16)
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_y')
    frame = _special_action_sub_word(state, frame, 'unit', frame.roster.word(low16(frame.target_y)))
    if not frame.status & 1:
        frame = _movement_move_long(state, frame, 'unit', frame.unit & 65535)
        frame = _movement_divu_word(state, frame, 'unit', 10, 0x1A91E)
        frame = _special_action_add_capped_word(state, frame, frame.controller,
            low16(frame.target_x), 'count', low16(frame.unit))
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1A93C)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _special_action_shift_long(state, frame, 'target_x', 4)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 5)
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_shift_word(state, frame, 'unit')
    frame = _special_action_add_capped_word(state, frame, frame.candidates,
        low16(frame.unit), 'count', low16(frame.target_x))
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1A96A)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 10)
    frame = _special_action_add_capped_word(state, frame, frame.candidates,
        low16(frame.unit), 'count', low16(frame.target_x))
    state.set_status_word(state.read_status_word() | 1)
    return first_replace(frame, status=state.sr & 31)

def city_calculate_live_quotient_3_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A818 sole complete status action; live table chooses this address."""
    frame = _status_action_frame(state, frame)
    frame = _special_action_call(state, frame, 0x1A7F4, 0x1A81A)
    frame = _special_action_call(state, frame, 0x1A706, 0x1A81E)
    frame = _special_action_call(state, frame, 0x1A7A2, 0x1A820)
    frame = _movement_compare(state, frame, low16(frame.choice), 100, 16)
    if frame.status & 1:
        frame = _status_action_failure(state, frame)
    else:
        frame = _status_action_success(state, frame)
    return _status_action_frame(state, frame)

def city_resolve_readonly_state_5_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AF5C: count the selected live roster, consuming its negative terminator.

    The original WORD count wraps; no artificial list bound or sentinel value
    is substituted. Untouched incoming carriers and upper D0 remain intact.
    """
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('actual roster-count fields required')
    frame.validate(state, frame.stack_cursor is not None)
    if frame.target_x is None:
        raise MovementContinuationBoundary(0x1AF5C, frame, 'incoming D0 upper bits were not observed')
    selection = state.read(0xFFFFF6D6, 2)
    frame = _first_word(frame, 'target_x', selection)
    selection &= 2
    frame = _first_word(frame, 'target_x', selection)
    frame = _first_shift_word(frame, 'target_x', selection, 1)
    pointer = state.read(0x1AF78 + selection * 2, 4)
    frame = first_replace(frame, roster=state.table_at(pointer).cursor())
    frame = _first_word(frame, 'target_x', 0)
    while True:
        member = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _first_memory_word(frame, member)
        if member & 32768:
            break
        frame = _first_add_word(frame, 'target_x', low16(frame.target_x), 1)
    state.sr = (state.sr & 65504) | frame.status
    return frame.validate(state, frame.stack_cursor is not None)

def _resource_cost_frame(state: SceneState, frame: FirstDeploymentFrame, target: int) -> FirstDeploymentFrame:
    """Require actual entry fields at this resource-call address, never zeros."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('actual resource-cost fields required')
    frame.validate(state, frame.stack_cursor is not None)
    if any(value is None for value in (
            frame.target_x, frame.target_y, frame.unit, frame.count,
            frame.distance, frame.offset_x, frame.offset_y, frame.choice,
            frame.roster, frame.candidates, frame.controller, frame.scan,
            frame.opponent, frame.scratch, frame.auxiliary,
            frame.stack_cursor, frame.status)):
        raise MovementContinuationBoundary(target, frame,
            'historical resource interface did not observe full fields or entry SP')
    return _movement_frame(state, frame)

def _sample_battle_resource_cost_fields(state: SceneState, frame: FirstDeploymentFrame,
        base_divisor: int, random_return: int, divide_instruction: int) -> FirstDeploymentFrame:
    """One cost algorithm for the three original divisor-base variants.

    Cost uses the incoming target's troop LONG and a random divisor in
    [base, base+10]. Preserve both LONG random scaling and WORD index shifts.
    DIVU overflow leaves D2 unchanged; its undefined NZV are immediately
    overwritten by ANDI.L, without any intervening observation or branch.
    """
    if base_divisor not in (20, 30, 40):
        raise ValueError('original resource divisor base required')
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, random_return)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', base_divisor)
    frame = first_replace(frame, roster=state.table_at(0xFFFFC800).cursor())
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 2)
    frame = _movement_move_long(state, frame, 'unit', frame.roster.long(low16(frame.target_y)))
    divisor = low16(frame.target_x)
    if divisor == 0:
        raise MovementContinuationBoundary(divide_instruction, frame, 'original DIVU requires its real exception fields')
    if frame.unit // divisor <= 65535:
        frame = _movement_divu_word(state, frame, 'unit', divisor, divide_instruction)
    # Overflow has no D2 write. ANDI now defines NZVC, preserving original X.
    frame = _movement_move_long(state, frame, 'unit', frame.unit & 65535)
    state.write(0xFFFFF39E, 4, frame.unit)
    return _movement_test_long(state, frame, frame.unit)

def city_calculate_live_quotient_7_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AFBC..1AFF4: sole troop-derived resource cost, base divisor20."""
    frame = _resource_cost_frame(state, frame, 0x1AFBC)
    return _sample_battle_resource_cost_fields(state, frame, 20, 0x1AFC2, 0x1AFE6)

def city_calculate_live_quotient_8_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AFF4..1B02C: shared troop-derived resource cost, base divisor30."""
    frame = _resource_cost_frame(state, frame, 0x1AFF4)
    return _sample_battle_resource_cost_fields(state, frame, 30, 0x1AFFA, 0x1B01E)

def city_calculate_live_quotient_9_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1B02C..1B064: shared troop-derived resource cost, base divisor40."""
    frame = _resource_cost_frame(state, frame, 0x1B02C)
    return _sample_battle_resource_cost_fields(state, frame, 40, 0x1B032, 0x1B056)

def city_coordinate_live_state_79_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AF80: actual live cost dispatch followed by resource affordability.

    This function owns internal return1AF8E, not its caller's outer slot.
    Unknown selected addresses keep that real slot and remain boundaries.
    """
    frame = _resource_cost_frame(state, frame, 0x1AF80)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF6D4, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    displacement = state.read(u32(0x1AFA0 + s16(low16(frame.target_x))), 2)
    frame = _movement_move(state, frame, 'target_x', displacement, 16)
    target = u32(0x1AFBC + s16(displacement))
    stack = frame.stack_cursor.advance(-4)
    stack.set_long(0, 0x1AF8E)
    entered = first_replace(frame, stack_cursor=stack)
    if target == 0x1AFBC:
        frame = city_calculate_live_quotient_7_fields(state, entered)
    elif target == 0x1AFF4:
        frame = city_calculate_live_quotient_8_fields(state, entered)
    elif target == 0x1B02C:
        frame = city_calculate_live_quotient_9_fields(state, entered)
    elif target == 0x1B064:
        frame = city_scale_live_record_value_3_fields(state, entered)
    else:
        raise MovementContinuationBoundary(target, entered, 'selected resource cost is not yet field-closed')
    returned = frame.stack_cursor.long()
    if returned != 0x1AF8E:
        raise FirstDeploymentReturnBoundary(returned, frame, 0x1AF8E)
    frame = first_replace(frame, stack_cursor=frame.stack_cursor.advance(4))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF6D6, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)
    pointer = state.read(u32(0x1AFAC + s16(low16(frame.target_x))), 4)
    frame = first_replace(frame, roster=state.table_at(pointer).cursor())
    frame = _movement_move_long(state, frame, 'target_x', frame.roster.long())
    preserved_x = frame.status & 16
    frame, difference = _movement_binary_flags(state, frame,
        frame.target_x, state.read(0xFFFFF39E, 4), 32, True)
    # CMP does not write D0 or X. All other subtraction conditions are genuine.
    frame = first_replace(frame, status=(frame.status & 15) | preserved_x)
    state.sr = (state.sr & 65504) | frame.status
    return _resource_cost_frame(state, frame, 0x1AF80)


def _restorative_action_sixfold_draw_fields(state: SceneState, frame: FirstDeploymentFrame,
        continuation, fresh_seed: bool) -> FirstDeploymentFrame:
    """Original status draw: sixfold high-WORD; success reads F61C afresh."""
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, continuation)
    if fresh_seed:
        frame = _movement_move_long(state, frame, 'target_x', 0)
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF61C, 2), 16)
    else:
        frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _special_action_swap(state, frame, 'target_x')
    if fresh_seed:
        frame = _movement_add_word(state, frame, 'target_x', 5)
    return frame


def _restorative_action_positive_status_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A9D0..1AA3C: both status gains retain the original unequal widths."""
    frame = _restorative_action_sixfold_draw_fields(state, frame, 0x1A9D6, True)
    frame = first_replace(frame, roster=state.table_at(0xFFFFC500).cursor())
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)
    frame = _movement_add_byte(state, frame, 'unit', low8(frame.target_x))
    # Confirmed original: first BYTE sum is compared as a WORD, not BYTE.
    frame = _movement_compare(state, frame, low16(frame.unit), 99, 16)
    if not frame.status & 5:
        frame = _movement_move(state, frame, 'unit', 99, 8)
    frame.roster.set_byte(low16(frame.target_y), low8(frame.unit))
    frame = _movement_test(state, frame, low8(frame.unit), 8)
    frame = _restorative_action_sixfold_draw_fields(state, frame, 0x1AA0E, True)
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)
    frame = _movement_add_word(state, frame, 'unit', low16(frame.target_x))
    frame = _movement_compare(state, frame, low8(frame.unit), 99, 8)
    if not frame.status & 5:
        frame = _movement_move(state, frame, 'unit', 99, 8)
    frame.roster.set_byte(low16(frame.target_y), low8(frame.unit))
    return _movement_test(state, frame, low8(frame.unit), 8)


def _restorative_action_positive_rewards_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AA3C..1AAC2: live target/actor rewards, original wrapped caps at999."""
    frame = first_replace(frame, roster=state.table_at(0xFFFFBE00).cursor(),
        candidates=state.table_at(0xFFFFC000).cursor())
    frame = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', low16(frame.choice))
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_y')
    frame = _special_action_add_capped_word(state, frame, frame.roster,
        low16(frame.target_y), 'unit', low16(frame.target_x))
    frame = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', low16(frame.unit))
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_divu_word(state, frame, 'target_x', 10, 0x1AA72)
    frame = _special_action_add_capped_word(state, frame, frame.candidates,
        low16(frame.target_y), 'unit', low16(frame.target_x))
    frame = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_y')
    frame = _special_action_add_capped_word(state, frame, frame.roster,
        low16(frame.target_y), 'unit', low16(frame.target_x))
    frame = _first_right_word(frame, 'target_x', low16(frame.target_x), 1)
    state.sr = (state.sr & 65504) | frame.status
    return _special_action_add_capped_word(state, frame, frame.candidates,
        low16(frame.target_y), 'unit', low16(frame.target_x))


def _restorative_action_failed_status_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AAD2..1AB26: BYTE loss saturates the register before each store."""
    frame = _restorative_action_sixfold_draw_fields(state, frame, 0x1AAD8, False)
    frame = first_replace(frame, roster=state.table_at(0xFFFFC500).cursor())
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)
    frame, value = _movement_binary_flags(state, frame, low8(frame.unit), low8(frame.target_x), 8, True)
    frame = first_replace(frame, unit=replace_byte(frame.unit, value))
    if frame.status & 1:
        frame = _movement_move(state, frame, 'unit', 0, 8)
    frame.roster.set_byte(low16(frame.target_y), low8(frame.unit))
    frame = _movement_test(state, frame, low8(frame.unit), 8)
    frame = _restorative_action_sixfold_draw_fields(state, frame, 0x1AB04, False)
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)
    frame, value = _movement_binary_flags(state, frame, low8(frame.unit), low8(frame.target_x), 8, True)
    frame = first_replace(frame, unit=replace_byte(frame.unit, value))
    if frame.status & 1:
        frame = _movement_move(state, frame, 'unit', 0, 8)
    frame.roster.set_byte(low16(frame.target_y), low8(frame.unit))
    return _movement_test(state, frame, low8(frame.unit), 8)


def _restorative_action_failed_rewards_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AB26..1ABC6: failed-action relative and random attribute rewards."""
    frame = first_replace(frame, candidates=state.table_at(0xFFFFBE00).cursor(),
        controller=state.table_at(0xFFFFC000).cursor(),
        roster=state.table_at(0xFFFFB600).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    frame = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.target_x)), 16)
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_shift_word(state, frame, 'unit')
    frame = _special_action_sub_word(state, frame, 'target_y', frame.roster.word(low16(frame.unit)))
    if not frame.status & 1:
        # ANDI.W #FFFF retains D1's actual upper WORD before full-LONG DIVU.
        frame = _movement_move(state, frame, 'target_y', low16(frame.target_y), 16)
        frame = _movement_divu_word(state, frame, 'target_y', 10, 0x1AB4E)
        frame = _special_action_add_capped_word(state, frame, frame.candidates,
            low16(frame.unit), 'count', low16(frame.target_y))
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1AB6E)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    # Confirmed original WORD shift, followed by SWAP; do not replace by LONG.
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 4)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 5)
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_shift_word(state, frame, 'unit')
    frame = _special_action_add_capped_word(state, frame, frame.controller,
        low16(frame.unit), 'distance', low16(frame.target_x))
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1AB9E)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_swap(state, frame, 'target_x')
    return _special_action_add_capped_word(state, frame, frame.candidates,
        low16(frame.unit), 'distance', low16(frame.target_x))


def city_calculate_live_quotient_4_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """confirmed 1A9B0..1ABCC: unique restorative special-action policy.

    Debit, potential, terrain factor and RNG share their existing cores.
    Separate successful and failed effects preserve the original read/write
    order, widths, pointer registers, nested slots and full-SR return writes.
    """
    frame = _special_action_frame(state, frame)
    frame = _special_action_call(state, frame, 0x1A7F4, 0x1A9B4)
    frame = _special_action_call(state, frame, 0x1ABCC, 0x1A9B8)
    frame = _special_action_call(state, frame, 0x1A7A2, 0x1A9BC)
    frame = _movement_test(state, frame, low16(frame.choice), 16)
    if frame.status & 4:
        frame = _restorative_action_failed_status_fields(state, frame)
        frame = _restorative_action_failed_rewards_fields(state, frame)
        state.set_status_word(state.read_status_word() | 1)
    else:
        frame = _movement_move_long(state, frame, 'choice', frame.choice & 65535)
        frame = _movement_divu_word(state, frame, 'choice', 100, 0x1A9C8)
        frame = _special_action_call(state, frame, 0x1AC04, 0x1A9D0)
        frame = _restorative_action_positive_status_fields(state, frame)
        frame = _restorative_action_positive_rewards_fields(state, frame)
        state.write(0x00FF7026, 2, 28)
        frame = _movement_test(state, frame, 28, 16)
        state.set_status_word(state.read_status_word() & 65534)
    frame = first_replace(frame, status=state.sr & 31)
    return _special_action_frame(state, frame)


def city_calculate_live_quotient_5_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """confirmed 1ABCC..1AC04: factor draw and original terrain-6 multiplier."""
    frame = _special_action_frame(state, frame)
    frame = _special_action_call(state, frame, 0x1A706, 0x1ABD0)
    # Original ADDQ is immediately overwritten but its X survives MOVE.W.
    frame = _movement_add_word(state, frame, 'distance', 5)
    frame = _movement_move(state, frame, 'distance', low16(frame.target_x), 16)
    frame = _special_action_call(state, frame, 0x1A438, 0x1ABD8)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFA150).cursor())
    frame = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)
    frame = _first_right_word(frame, 'target_y', low16(frame.target_y), 7)
    state.sr = (state.sr & 65504) | frame.status
    frame = _movement_move(state, frame, 'unit', frame.candidates.word(low16(frame.target_x), 2), 16)
    frame = _first_right_word(frame, 'unit', low16(frame.unit), 7)
    state.sr = (state.sr & 65504) | frame.status
    frame, terrain = _deployment_terrain_lookup(BattlePolicyMemory(state), frame,
        low16(frame.target_y), low16(frame.unit), 0x1ABF2)
    frame = _movement_compare(state, frame, low16(frame.target_x), 6, 16)
    if frame.status & 4:
        frame = _movement_multiply_word(state, frame, 'distance', 12)
        frame = _movement_divu_word(state, frame, 'distance', 10, 0x1ABFC)
    frame = _movement_move(state, frame, 'target_x', low16(frame.distance), 16)
    return _special_action_frame(state, frame)


def city_update_live_fields_11_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """confirmed 1AC04..1AC1E: target status82 and actor BYTE link."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('actual target-status frame required')
    frame.validate(state, frame.stack_cursor is not None)
    frame = _first_word(frame, 'target_x', state.read(0xFFFFF3A6, 2))
    frame = first_replace(frame, roster=state.table_at(0xFFFFA654).cursor())
    frame.roster.set_byte(low16(frame.target_x), 130)
    state.sr = (state.sr & 65520) | 8
    frame = first_replace(frame, status=None if frame.status is None else (frame.status & 16) | 8)
    frame = first_replace(frame, roster=state.table_at(0xFFFFA854).cursor())
    actor = state.read(0xFFFFF3F3, 1)
    frame.roster.set_byte(low16(frame.target_x), actor)
    conditions = (8 if actor & 128 else 0) | (4 if actor == 0 else 0)
    state.sr = (state.sr & 65520) | conditions
    frame = first_replace(frame, status=None if frame.status is None else (frame.status & 16) | conditions)
    return frame.validate(state, frame.stack_cursor is not None)

def _recruitment_frame(state: SceneState, frame: FirstDeploymentFrame, entry, complete: bool = True) -> FirstDeploymentFrame:
    """Closed recruitment owners use existing fields, not inferred registers."""
    checked_state(state)
    uint(entry, 32)
    if entry not in (0x1AC26, 0x1AD46, 0x1AE1C, 0x1AEA0, 0x1AEC6):
        raise ValueError('actual recruitment-family entry required')
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('sole actual recruitment fields required')
    frame.validate(state, False)
    if complete:
        if any(value is None for value in (
                frame.target_x, frame.target_y, frame.unit, frame.count,
                frame.distance, frame.offset_x, frame.offset_y, frame.choice,
                frame.roster, frame.candidates, frame.controller, frame.scan,
                frame.opponent, frame.scratch, frame.auxiliary,
                frame.stack_cursor, frame.status)):
            raise MovementContinuationBoundary(entry, frame,
                'historical recruitment facade lacks actual complete entry fields')
        return _movement_frame(state, frame)
    return frame

def _recruitment_carry(state: SceneState, frame: FirstDeploymentFrame, carry: bool) -> FirstDeploymentFrame:
    if type(carry) is not bool:
        raise ValueError('actual original carry arm required')
    state.set_status_word((state.read_status_word() & 65534) | int(carry))
    return first_replace(frame, status=state.sr & 31)

def _recruitment_right_long(state: SceneState, frame: FirstDeploymentFrame, name: str, amount: int) -> FirstDeploymentFrame:
    """The two actual score LSR.L forms preserve full value and final X/C."""
    if amount not in (1, 3, 4):
        raise ValueError('original recruitment score shift required')
    original = frame.carrier(name)
    uint(original, 32)
    value = original >> amount
    carry = bool(original & (1 << (amount - 1)))
    status = (17 if carry else 0) | (4 if value == 0 else 0)
    state.sr = (state.sr & 65504) | status
    return first_replace(frame, **{name: value}, status=status)

def _recruitment_stitched_score_product(state: SceneState, frame: FirstDeploymentFrame, factor) -> FirstDeploymentFrame:
    """Original low/high WORD products leave D0 scratch and D2 full sum."""
    uint(factor, 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.unit), 16)
    frame = _movement_multiply_word(state, frame, 'target_x', factor)
    frame = _special_action_swap(state, frame, 'unit')
    frame = _movement_multiply_word(state, frame, 'unit', factor)
    frame = _special_action_swap(state, frame, 'unit')
    return _movement_arithmetic_long(state, frame, 'unit', frame.target_x)

def _recruitment_save_actor_word(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """The original saved F3F2 is a real WORD below the caller return LONG."""
    value = state.read(0xFFFFF3F2, 2)
    stack = frame.stack_cursor.advance(-2)
    stack.set_word(0, value)
    frame = first_replace(frame, stack_cursor=stack)
    return _movement_test(state, frame, value, 16)

def _recruitment_restore_actor_word(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Read the live saved WORD after RTS; never restore a host snapshot."""
    value = frame.stack_cursor.word()
    frame = first_replace(frame, stack_cursor=frame.stack_cursor.advance(2))
    state.write(0xFFFFF3F2, 2, value)
    return _movement_test(state, frame, value, 16)

def city_scale_live_record_value_2_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AE1C sole status-matrix draw; table BYTE pair and seed WORD are live."""
    frame = _recruitment_frame(state, frame, 0x1AE1C, frame.stack_cursor is not None)
    uint(frame.count, 32)
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1AE22)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_move(state, frame, 'target_y', 4, 16)
    statuses = state.table_at(0xFFFFC700).cursor()
    frame = first_replace(frame, roster=statuses)
    frame = _movement_move(state, frame, 'target_x', statuses.byte(low16(frame.target_x)), 8)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 7, 16)
    frame = _special_action_sub_word(state, frame, 'target_y', low16(frame.target_x))
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)
    frame = _movement_add_word(state, frame, 'target_x', low16(frame.target_y))
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_move(state, frame, 'count', 4, 16)
    frame = _movement_move(state, frame, 'target_y', statuses.byte(low16(frame.target_y)), 8)
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 7, 16)
    frame = _special_action_sub_word(state, frame, 'count', low16(frame.target_y))
    frame = _movement_add_word(state, frame, 'target_x', low16(frame.count))
    frame = _movement_shift_word(state, frame, 'target_x')
    parameters = state.table_at(0x1AE6E).cursor()
    frame = first_replace(frame, candidates=parameters)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'target_y', parameters.byte(low16(frame.target_x)), 8)
    frame = _movement_multiply_word(state, frame, 'target_y', state.read(0xFFFFF61C, 2))
    frame = _special_action_swap(state, frame, 'target_y')
    frame = _movement_move(state, frame, 'count', 0, 16)
    frame = _movement_move(state, frame, 'count', parameters.byte(low16(frame.target_x), 1), 8)
    frame = _movement_add_word(state, frame, 'target_y', low16(frame.count))
    return frame.validate(state, frame.stack_cursor is not None)

def city_scale_live_record_value_1_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AD46 sole comparison score; retain each original low-WORD product."""
    frame = _recruitment_frame(state, frame, 0x1AD46, frame.stack_cursor is not None)
    for name in ('target_x', 'target_y', 'unit', 'count', 'distance'):
        uint(frame.carrier(name), 32)
    target = state.read(0xFFFFF3A6, 2)
    frame = _first_word(frame, 'target_x', target)
    loyalty = state.table_at(0xFFFFC300).cursor()
    frame = first_replace(frame, roster=loyalty)
    frame = _first_word(frame, 'target_y', 0)
    value = loyalty.byte(target)
    frame = _first_byte(frame, 'target_y', value)
    frame = _first_word(frame, 'unit', 100)
    frame = _first_sub_word(frame, 'unit', 100, low16(frame.target_y))
    state.sr = (state.sr & 65504) | frame.status
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3F2, 2), 16)
    assignments = state.table_at(0xFFFFCC00).cursor()
    frame = first_replace(frame, roster=assignments)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'target_y', assignments.byte(low16(frame.target_x)), 8)
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 63, 16)
    owners = state.table_at(0xFFFFF427).cursor()
    frame = first_replace(frame, roster=owners)
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_x', owners.byte(low16(frame.target_y)), 8)
    frame = _movement_shift_word(state, frame, 'target_x')
    heads = state.table_at(0xFFFFE640).cursor()
    frame = first_replace(frame, roster=heads)
    frame = _movement_move(state, frame, 'target_x', heads.word(low16(frame.target_x)), 16)
    attributes = state.table_at(0xFFFFC200).cursor()
    frame = first_replace(frame, roster=attributes)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'target_y', attributes.byte(low16(frame.target_x)), 8)
    frame = _movement_multiply_word(state, frame, 'unit', low16(frame.target_y))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'target_y', attributes.byte(low16(frame.target_x)), 8)
    frame = _movement_multiply_word(state, frame, 'unit', low16(frame.target_y))
    frame = _movement_shift_word(state, frame, 'target_x')
    strengths = state.table_at(0xFFFFB600).cursor()
    frame = first_replace(frame, roster=strengths)
    frame = _movement_move(state, frame, 'target_y', strengths.word(low16(frame.target_x)), 16)
    frame = _recruitment_stitched_score_product(state, frame, low16(frame.target_y))
    if frame.stack_cursor is None:
        frame = city_scale_live_record_value_2_fields(state, frame)
    else:
        frame = _special_action_call(state, frame, 0x1AE1C, 0x1ADB2)
    frame = _recruitment_stitched_score_product(state, frame, low16(frame.target_y))
    frame = _recruitment_right_long(state, frame, 'unit', 4)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    attributes = state.table_at(0xFFFFC200).cursor()
    frame = first_replace(frame, roster=attributes)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'target_y', attributes.byte(low16(frame.target_x)), 8)
    frame = _movement_add_word(state, frame, 'target_y', 1)
    assignments = state.table_at(0xFFFFCC00).cursor()
    frame = first_replace(frame, candidates=assignments)
    frame = _movement_move(state, frame, 'count', assignments.byte(low16(frame.target_x)), 8)
    frame = _movement_move(state, frame, 'count', low16(frame.count) & 63, 16)
    owners = state.table_at(0xFFFFF427).cursor()
    frame = first_replace(frame, candidates=owners)
    frame = _movement_move(state, frame, 'distance', 0, 16)
    frame = _movement_move(state, frame, 'distance', owners.byte(low16(frame.count)), 8)
    frame = _movement_shift_word(state, frame, 'distance')
    heads = state.table_at(0xFFFFE640).cursor()
    frame = first_replace(frame, candidates=heads)
    frame = _movement_move(state, frame, 'distance', heads.word(low16(frame.distance)), 16)
    frame = _movement_move(state, frame, 'count', 0, 16)
    frame = _movement_move(state, frame, 'count', attributes.byte(low16(frame.distance)), 8)
    frame = _movement_add_word(state, frame, 'count', 1)
    frame = _movement_multiply_word(state, frame, 'target_y', low16(frame.count))
    frame = _movement_shift_word(state, frame, 'target_x')
    strengths = state.table_at(0xFFFFB600).cursor()
    frame = first_replace(frame, roster=strengths)
    frame = _movement_move(state, frame, 'target_x', strengths.word(low16(frame.target_x)), 16)
    frame = _movement_add_word(state, frame, 'target_x', 1)
    frame = _movement_multiply_word(state, frame, 'target_y', low16(frame.target_x))
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)
    frame = _movement_multiply_word(state, frame, 'target_x', 125)
    frame = _special_action_swap(state, frame, 'target_y')
    frame = _movement_multiply_word(state, frame, 'target_y', 125)
    frame = _special_action_swap(state, frame, 'target_y')
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _recruitment_right_long(state, frame, 'target_x', 1)
    return frame.validate(state, frame.stack_cursor is not None)

def city_coordinate_live_state_78_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AEC6 sole roster transfer; live compact/read/pointer/count ordering."""
    frame = _recruitment_frame(state, frame, 0x1AEC6)
    while True:
        member = frame.roster.next_word()
        frame = _movement_move(state, frame, 'target_y', member, 16)
        if frame.status & 8:
            return _recruitment_carry(state, frame, False)
        frame = _movement_compare(state, frame, low8(frame.target_y), low8(frame.target_x), 8)
        if frame.status & 4:
            break
    destination = frame.roster.advance(-2)
    frame = first_replace(frame, candidates=destination)
    while True:
        value = frame.roster.next_word()
        frame.candidates.append_word(value)
        frame = _movement_test(state, frame, value, 16)
        if frame.status & 8:
            break
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF6D6, 2), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 2, 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    pointer = state.read(u32(0x1AF4C + s16(low16(frame.target_x))), 4)
    frame = first_replace(frame, roster=state.table_at(pointer).cursor())
    frame = _movement_move(state, frame, 'target_y', frame.roster.word(), 16)
    pointer = state.read(u32(0x1AF54 + s16(low16(frame.target_x))), 4)
    frame = first_replace(frame, candidates=state.table_at(pointer).cursor())
    value = frame.candidates.word()
    frame, value = _movement_binary_flags(state, frame, value, 1, 16)
    frame.candidates.set_word(0, value)
    while True:
        value = frame.roster.next_word()
        frame = _movement_test(state, frame, value, 16)
        if frame.status & 8:
            break
    value = state.read(0xFFFFF3A6, 2)
    frame.roster.set_word(0, value, -2)
    frame = _movement_test(state, frame, value, 16)
    frame.roster.put_word(65535)
    frame = _movement_test(state, frame, 65535, 16)
    assignments = state.table_at(0xFFFFCC00).cursor()
    frame = first_replace(frame, roster=assignments)
    frame = _movement_move(state, frame, 'target_y', assignments.byte(low16(frame.target_y)), 8)
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF3A6, 2), 16)
    assignments.set_byte(low16(frame.unit), low8(frame.target_y))
    frame = _movement_test(state, frame, low8(frame.target_y), 8)
    frame = _recruitment_save_actor_word(state, frame)
    owners = state.table_at(0xFFFFF427).cursor()
    frame = first_replace(frame, roster=owners)
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 63, 16)
    frame = _movement_move(state, frame, 'target_y', owners.byte(low16(frame.target_y)), 8)
    frame = _movement_shift_word(state, frame, 'target_y')
    heads = state.table_at(0xFFFFE640).cursor()
    frame = first_replace(frame, roster=heads)
    value = heads.word(low16(frame.target_y))
    state.write(0xFFFFF3F2, 2, value)
    frame = _movement_test(state, frame, value, 16)
    # The caller owns genuine 1AF2E LONG below saved WORD; loyalty owns its MOVEM.
    frame = _special_action_call(state, frame, 0x208CE, 0x1AF2E)
    frame = _recruitment_restore_actor_word(state, frame)
    frame = first_replace(frame, roster=state.table_at(0xFFFFAE28).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame.roster.byte(low16(frame.target_x))
    frame.roster.set_byte(low16(frame.target_x), 0)
    frame = _movement_test(state, frame, 0, 8)
    return _recruitment_carry(state, frame, True)

def city_coordinate_live_state_77_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AEA0 sole two-roster transfer; second count decrement is unconditional."""
    frame = _recruitment_frame(state, frame, 0x1AEA0)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFA550).cursor())
    frame = _special_action_call(state, frame, 0x1AEC6, 0x1AEAC)
    if frame.status & 1:
        address = 0xFFFFF6A6
    else:
        frame = first_replace(frame, roster=state.table_at(0xFFFFA5A4).cursor())
        frame = _special_action_call(state, frame, 0x1AEC6, 0x1AEC0)
        address = 0xFFFFF6A8
    value = state.read(address, 2)
    frame, value = _movement_binary_flags(state, frame, value, 1, 16, True)
    state.write(address, 2, value)
    return _recruitment_frame(state, frame, 0x1AEA0)

def _recruitment_failed_attempt(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1ACD2..1AD44 failed attempt preserves the original wrapped arithmetic."""
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1ACD8)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 1)
    frame = first_replace(frame, roster=state.table_at(0xFFFFBE00).cursor())
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_y')
    frame = _special_action_add_capped_word(state, frame, frame.roster,
        low16(frame.target_y), 'unit', low16(frame.target_x))
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1AD0E)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = first_replace(frame, roster=state.table_at(0xFFFFC200).cursor())
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    frame = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)
    frame = _movement_multiply_word(state, frame, 'unit', low16(frame.target_x))
    frame = _movement_divu_word(state, frame, 'unit', 100, 0x1AD30)
    original = frame.roster.byte(low16(frame.target_y))
    frame, value = _movement_binary_flags(state, frame, original, low8(frame.unit), 8, True)
    frame.roster.set_byte(low16(frame.target_y), value)
    if frame.status & 1:
        frame.roster.byte(low16(frame.target_y))
        frame.roster.set_byte(low16(frame.target_y), 0)
        frame = _movement_test(state, frame, 0, 8)
    return _recruitment_carry(state, frame, True)

def _recruitment_commit_attempt(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AC52..1ACD2 successful structure, including real saved actor WORD."""
    frame = _special_action_call(state, frame, 0x1AEA0, 0x1AC56)
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1AC5C)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 15)
    frame = first_replace(frame, roster=state.table_at(0xFFFFBE00).cursor())
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_y')
    frame = _special_action_add_capped_word(state, frame, frame.roster,
        low16(frame.target_y), 'unit', low16(frame.target_x))
    frame = _special_action_call(state, frame, 0x1A7F4, 0x1AC94)
    frame = _recruitment_carry(state, frame, False)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF68C, 2), 16)
    side_flag = state.read(0xFFFFAE29, 1)
    frame = first_replace(frame, status=(frame.status & 27) | (0 if side_flag & 2 else 4))
    state.sr = (state.sr & 65504) | frame.status
    if not frame.status & 4:
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF68E, 2), 16)
    frame = _recruitment_save_actor_word(state, frame)
    value = low16(frame.target_x)
    state.write(0xFFFFF3F2, 2, value)
    frame = _movement_test(state, frame, value, 16)
    frame = _special_action_call(state, frame, 0x208CE, 0x1ACB8)
    frame = _recruitment_restore_actor_word(state, frame)
    state.write(0x00FF7026, 2, 27)
    frame = _movement_test(state, frame, 27, 16)
    value = state.read(0xFFFFF3A6, 2)
    state.write(0xFFFFF3D2, 2, value)
    frame = _movement_test(state, frame, value, 16)
    return _recruitment_carry(state, frame, False)

def city_calculate_live_quotient_6_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1AC26 sole recruitment attempt: capacity, heads, score then commit/fail."""
    frame = _recruitment_frame(state, frame, 0x1AC26)
    frame = _special_action_call(state, frame, 0x1AF5C, 0x1AC2A)
    frame = _movement_compare(state, frame, low16(frame.target_x), 10, 16)
    rejected = not bool(frame.status & 1)
    if not rejected:
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
        heads = state.table_at(0xFFFFE640).cursor()
        frame = first_replace(frame, roster=heads)
        frame = _movement_move(state, frame, 'target_y', 15, 16)
        while True:
            value = heads.next_word()
            frame = _movement_compare(state, frame, low16(frame.target_x), value, 16)
            if frame.status & 4:
                rejected = True
                break
            counter = u16(low16(frame.target_y) - 1)
            frame = first_replace(frame, target_y=replace_word(frame.target_y, counter))
            if counter == 65535:
                break
    if not rejected:
        frame = _special_action_call(state, frame, 0x1AD46, 0x1AC4C)
        frame = _first_compare_long(frame, frame.unit, frame.target_x)
        state.sr = (state.sr & 65504) | frame.status
        rejected = bool(frame.status & 1)
    if rejected:
        frame = _recruitment_failed_attempt(state, frame)
    else:
        frame = _recruitment_commit_attempt(state, frame)
    return _recruitment_frame(state, frame, 0x1AC26)


def city_scale_live_record_value_3_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """confirmed 1B064..1B098: wrapped attribute sum times original draw8..12."""
    frame = _resource_cost_frame(state, frame, 0x1B064)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_shift_word(state, frame, 'target_x')
    frame = first_replace(frame, roster=state.table_at(0xFFFFB400).cursor())
    frame = _movement_move(state, frame, 'unit', frame.roster.word(low16(frame.target_x)), 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFB600).cursor())
    frame = _movement_add_word(state, frame, 'unit', frame.roster.word(low16(frame.target_x)))
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, 0x1B080)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 8)
    frame = _movement_multiply_word(state, frame, 'unit', low16(frame.target_x))
    state.write(0xFFFFF39E, 4, frame.unit)
    return _movement_test_long(state, frame, frame.unit)


def _battle_command_call_fields(state: SceneState, frame: FirstDeploymentFrame,
        target, continuation) -> FirstDeploymentFrame:
    """Only four direct command/list callees and their real caller-owned LONG."""
    if target not in (0x1B0B2, 0x1B104, 0x1B138, 0xAC08):
        raise ValueError('closed original command/list child required')
    frame = _resource_cost_frame(state, frame, target)
    stack = frame.stack_cursor.advance(-4)
    stack.set_long(0, uint(continuation, 32))
    entered = first_replace(frame, stack_cursor=stack)
    state.sr = (state.sr & 65504) | entered.status
    if target == 0x1B0B2:
        result = city_select_live_state_19_fields(state, entered)
    elif target == 0x1B104:
        result = city_coordinate_live_state_82_fields(state, entered)
    elif target == 0x1B138:
        result = city_coordinate_live_state_83_fields(state, entered)
    else:
        from .services import SpritePacketMemory, append_live_command_sprite_fields
        result = append_live_command_sprite_fields(SpritePacketMemory(state), entered)
    result = _resource_cost_frame(state, result, target)
    actual = result.stack_cursor.long()
    if actual != continuation:
        raise FirstDeploymentReturnBoundary(actual, result, continuation)
    returned = first_replace(result, stack_cursor=result.stack_cursor.advance(4))
    state.sr = (state.sr & 65504) | returned.status
    return returned


def city_select_live_state_19_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """confirmed 1B0B2..1B0C2: sentinel list scene-label write, same live views."""
    from .business_highbank import _position_strategy_status
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('actual roster-tag fields required')
    frame.validate(state, frame.stack_cursor is not None)
    if frame.roster is None or frame.candidates is None or frame.target_x is None or frame.target_y is None:
        raise MovementContinuationBoundary(0x1B0B2, frame, 'actual tag/source views and D0/D1 required')
    while True:
        member = frame.candidates.next_word()
        frame = _first_word(frame, 'target_y', member)
        frame = _position_strategy_status(state, frame, member, 16)
        if member & 32768:
            return frame
        member &= 255
        frame = _first_word(frame, 'target_y', member)
        frame = _position_strategy_status(state, frame, member, 16)
        label = low8(frame.target_x)
        frame.roster.set_byte(member, label)
        frame = _position_strategy_status(state, frame, label, 8)


def city_coordinate_live_state_80_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """confirmed 1B098..1B0B2: apply current scene BYTE to both real lists."""
    frame = _resource_cost_frame(state, frame, 0x1B098)
    frame = first_replace(frame, roster=state.table_at(0xFFFFA050).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF68A, 2), 16)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFA550).cursor())
    frame = _battle_command_call_fields(state, frame, 0x1B0B2, 0x1B0A8)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFA5A4).cursor())
    return _battle_command_call_fields(state, frame, 0x1B0B2, 0x1B0B0)


def city_coordinate_live_state_81_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """confirmed 1B0C2..1B0EA: command-bit2 gate and its three real child calls."""
    frame = _resource_cost_frame(state, frame, 0x1B0C2)
    selected = bool(state.read(0xFFFFF3A5, 1) & 4)
    frame = first_replace(frame, status=(frame.status & 27) | (0 if selected else 4))
    state.sr = (state.sr & 65504) | frame.status
    if not selected:
        return frame
    frame = _battle_command_call_fields(state, frame, 0x1B104, 0x1B0D0)
    frame = _battle_command_call_fields(state, frame, 0x1B138, 0x1B0D4)
    frame = first_replace(frame, roster=state.table_at(0x1B0EA).cursor())
    frame = _movement_move(state, frame, 'target_x', 48, 16)
    frame = _movement_move(state, frame, 'target_y', 232, 16)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    return _battle_command_call_fields(state, frame, 0xAC08, 0x1B0E8)


def city_coordinate_live_state_82_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """confirmed 1B104..1B128: original button-mask graphic choice."""
    frame = _resource_cost_frame(state, frame, 0x1B104)
    frame = first_replace(frame, roster=state.table_at(0x1B128).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF320, 2), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 248, 16)
    if frame.status & 4:
        frame = first_replace(frame, roster=frame.roster.advance(8))
    frame = _movement_move(state, frame, 'target_x', 72, 16)
    frame = _movement_move(state, frame, 'target_y', 240, 16)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    return _battle_command_call_fields(state, frame, 0xAC08, 0x1B126)


def city_coordinate_live_state_83_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """confirmed 1B138..1B18C: live option icon, then original confirm toggle.

    The renderer is a genuine child boundary unless it supplies its complete
    current frame. Do not skip its return before the option/confirm reads.
    """
    frame = _resource_cost_frame(state, frame, 0x1B138)
    frame = first_replace(frame, roster=state.table_at(0x1B18C).cursor())
    frame = _movement_test(state, frame, state.read(0xFFFFF778, 2), 16)
    if not frame.status & 4:
        selected = bool(state.read(0xFFFFF321, 1) & 8)
        frame = first_replace(frame, status=(frame.status & 27) | (0 if selected else 4))
        state.sr = (state.sr & 65504) | frame.status
        if selected:
            frame = first_replace(frame, roster=frame.roster.advance(8))
    frame = _movement_move(state, frame, 'target_x', 88, 16)
    frame = _movement_move(state, frame, 'target_y', 248, 16)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    frame = _battle_command_call_fields(state, frame, 0xAC08, 0x1B160)
    frame = _movement_test(state, frame, state.read(0xFFFFF778, 2), 16)
    if not frame.status & 4:
        frame = _movement_compare(state, frame, state.read(0xFFFFF77C, 2), 16442, 16)
        if frame.status & 4:
            # Original memory CLR.W includes a fresh prior read.
            state.read(0xFFFFF778, 2)
            state.write(0xFFFFF778, 2, 0)
            frame = _movement_test(state, frame, 0, 16)
    else:
        frame = _movement_compare(state, frame, state.read(0xFFFFF77C, 2), 16441, 16)
        if frame.status & 4:
            state.write(0xFFFFF778, 2, 1)
            frame = _movement_test(state, frame, 1, 16)
    return frame

from .services import (_movement_adjust_word, _movement_load_packed_resource, _movement_store_packed_resource, signed_divmod_fields)


def _deployment_menu_bit(state: SceneState, frame: FirstDeploymentFrame, value, bit: int) -> FirstDeploymentFrame:
    """Dn bit14 is LONG despite cached '.b'; memory bit1 is a BYTE test."""
    if bit not in (1, 4, 6, 14):
        raise ValueError('closed deployment flag bits required')
    uint(value, 32)
    status = (frame.status & 27) | (0 if value & (1 << bit) else 4)
    state.sr = (state.sr & 65504) | status
    return first_replace(frame, status=status)


def assemble_defender_city_roster_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """18F18: defender head first, then reverse membership scan excluding head."""
    from .services import _movement_fixed_shift_word
    frame = _resource_cost_frame(state, frame, 0x18F18)
    frame = first_replace(frame, roster=state.table_at(0xFFFFCD00).cursor(),
        candidates=state.table_at(0xFFFFA5A4).cursor(), controller=state.table_at(0xFFFFF427))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF68A, 2), 16)
    frame = _movement_move(state, frame, 'distance', 0, 16)
    frame = _movement_move(state, frame, 'distance', frame.controller.byte(low16(frame.target_x)), 8)
    frame = _group_route_store_fields(state, frame, 0xFFFFF68E, low16(frame.distance))
    frame = first_replace(frame, controller=state.table_at(0xFFFFF45E))
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _movement_move(state, frame, 'distance', frame.controller.word(low16(frame.target_x)), 16)
    frame.candidates.set_word(0, low16(frame.distance))
    frame = first_replace(frame, candidates=frame.candidates.advance(2))
    frame = _movement_test(state, frame, low16(frame.distance), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1, True)
    frame = _movement_move(state, frame, 'target_y', 255, 16)
    frame = _movement_move(state, frame, 'count', 0, 16)
    while True:
        frame = first_replace(frame, roster=frame.roster.advance(-1))
        frame = _movement_move(state, frame, 'unit', frame.roster.byte(), 8)
        frame = _movement_compare(state, frame, low8(frame.unit), low8(frame.target_x), 8)
        if frame.status & 4:
            frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.distance), 16)
            if not frame.status & 4:
                frame.candidates.set_word(0, low16(frame.target_y))
                frame = first_replace(frame, candidates=frame.candidates.advance(2))
                frame = _movement_test(state, frame, low16(frame.target_y), 16)
                frame = _group_route_register_delta_fields(state, frame, 'count', 1)
        frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(low16(frame.target_y) - 1)))
        if low16(frame.target_y) == 65535:
            break
    frame.candidates.set_word(0, 65535)
    frame = _movement_test(state, frame, 65535, 16)
    return _group_route_store_fields(state, frame, 0xFFFFF6A8, low16(frame.count))


