def confirm_city_order_marker_view_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1EB30: reuse cursor/marker cores, actual commit child slot, or original cancel phase5."""
    frame = _resource_cost_frame(state, frame, 0x1EB30)
