def finish_city_side_order_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """19F1A..19F66: mark side complete, clear tagged roster high BYTEs and refresh palette."""
    frame = _resource_cost_frame(state, frame, 0x19F1A)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF6D6, 2), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)
    frame = _city_action_mark_side_fields(state, frame)
    # Same logical reset phase, not a new original BSR or return LONG.
    frame = reset_city_selection_menu_fields(state, frame)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF6D6, 2), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 2, 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    pointer = state.read(u32(0x19F66 + s16(low16(frame.target_x))), 4)
    frame = first_replace(frame, roster=state.table_at(pointer).cursor())
    while True:
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(), 16)
        if frame.status & 8:
            break
        frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)
        frame = _settlement_store_word_fields(state, frame, frame.roster, 0, low16(frame.target_x))
        frame = first_replace(frame, roster=frame.roster.advance(2))
    frame = _duel_menu_write_word_fields(state, frame, 0xFFFFA5F8, 0xFFFF)
    return _deployment_menu_call_fields(state, frame, 0xA3DA, 0x19F64)


