def dismiss_city_notice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """19FD8..1A006: timeout or button5 restores saved menu; stage itself is not cleared."""
    frame = _resource_cost_frame(state, frame, 0x19FD8)
