def test_city_order_foreign_owner_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A00E..1A0A2: active force BYTE ownership, descendant owner and carry-only result."""
    frame = _resource_cost_frame(state, frame, 0x1A00E)
    frame = _movement_test(state, frame, state.read(0xFFFFF6C4, 2), 16)
    if not frame.status & 4:
        return _recruitment_carry(state, frame, False)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF68A, 2), 16)
    frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_x)), 8)
    for address in (0xFFFFF67B, 0xFFFFF67D, 0xFFFFF67F):
        frame = _movement_compare(state, frame, low8(frame.target_y), state.read(address, 1), 8)
        if frame.status & 4:
            return _recruitment_carry(state, frame, False)
    frame = _city_action_find_city_owner_fields(state, frame)
    frame = first_replace(frame, roster=state.table_at(0xFFFFCC00).cursor())
    frame = _movement_move(state, frame, 'unit', 0, 16)
    frame = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.target_y)), 8)
    frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 63, 16)
    frame = _movement_compare(state, frame, low16(frame.unit), 40, 16)
    if not frame.status & 5:
        frame = _duel_commit_sub_word_fields(state, frame, 'unit', 41)
        frame = _movement_move(state, frame, 'target_y', low16(frame.unit), 16)
    else:
        frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor())
        frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.unit)), 8)
    for address in (0xFFFFF67B, 0xFFFFF67D, 0xFFFFF67F):
        frame = _movement_compare(state, frame, low8(frame.target_y), state.read(address, 1), 8)
        if frame.status & 4:
            return _recruitment_carry(state, frame, False)
    frame = _duel_menu_write_word_fields(state, frame, 0xFFFFF600, 0xD4)
    return _recruitment_carry(state, frame, True)


def prepare_city_order_owner_pair_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A0A2..1A16E: exact BYTE-to-WORD owner compares and side-specific actor preparation."""
    frame = _resource_cost_frame(state, frame, 0x1A0A2)
    for address in (0xFFFFF6C4, 0xFFFFF352):
        frame = _movement_test(state, frame, state.read(address, 2), 16)
        if not frame.status & 4:
            return _recruitment_carry(state, frame, False)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF68A, 2), 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor())
    frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_x)), 8)
    frame = _movement_compare(state, frame, low16(frame.target_y), state.read(0xFFFFF67C, 2), 16)
    if not frame.status & 4:
        frame = _movement_compare(state, frame, low16(frame.target_y), state.read(0xFFFFF67E, 2), 16)
        if not frame.status & 4:
            return _recruitment_carry(state, frame, False)
    frame = _city_action_find_city_owner_fields(state, frame)
    frame = first_replace(frame, roster=state.table_at(0xFFFFCC00).cursor())
    frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_y)), 8)
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 63, 16)
    frame = _movement_compare(state, frame, low16(frame.target_y), 40, 16)
    if not frame.status & 5:
        frame = _duel_commit_sub_word_fields(state, frame, 'target_y', 41)
    else:
        frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor())
        frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_y)), 8)
    frame = _movement_compare(state, frame, low16(frame.target_y), state.read(0xFFFFF67C, 2), 16)
    if not frame.status & 4:
        frame = _movement_compare(state, frame, low16(frame.target_y), state.read(0xFFFFF67E, 2), 16)
        if not frame.status & 4:
            return _recruitment_carry(state, frame, False)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF67E, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
    frame = _duel_menu_write_word_fields(state, frame, 0xFFFFF3D0, frame.roster.word(low16(frame.target_x)))
    frame = _duel_menu_write_word_fields(state, frame, 0xFFFFF362, 2)
    frame = _movement_move(state, frame, 'target_x', 0xC0, 16)
    frame = _deployment_menu_call_fields(state, frame, 0x676F2, 0x1A136)
    frame = _duel_menu_write_word_fields(state, frame, 0xFFFFF6D6, 0, clear=True)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF68A, 2), 16)
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_x)), 8)
    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(0xFFFFF67E, 2), 16)
    if frame.status & 4:
        frame = _duel_menu_write_word_fields(state, frame, 0xFFFFF6D6, 2)
        frame = _duel_menu_write_word_fields(state, frame, 0xFFFFF68E, low16(frame.target_x))
    else:
        frame = _duel_menu_write_word_fields(state, frame, 0xFFFFF68C, low16(frame.target_x))
    return _recruitment_carry(state, frame, True)


def draw_city_order_map_marker_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A200..1A244: state1 marker at the live ABDA8 coordinates, original WORD shifts."""
    frame = _resource_cost_frame(state, frame, 0x1A200)
    frame = _movement_compare(state, frame, state.read(0xFFFFF6C4, 2), 1, 16)
    if not frame.status & 4:
        return frame
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF68A, 2), 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFF9FFF).cursor())
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.unit)), 8)
    if frame.status & 4:
        return frame
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 1)
    frame = _first_shift_word(frame, 'unit', low16(frame.unit), 5)
    state.sr = (state.sr & 65504) | frame.status
    frame = _movement_add_word(state, frame, 'unit', low16(frame.target_y))
    frame = first_replace(frame, candidates=state.table_at(0xABDA8).cursor())
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_x', frame.candidates.byte(low16(frame.unit)), 8)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 3)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'target_y', frame.candidates.byte(low16(frame.unit), 1), 8)
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 3)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    frame = first_replace(frame, roster=state.table_at(0x1A244).cursor())
    return _deployment_menu_call_fields(state, frame, 0xAC08, 0x1A242)


def draw_city_side_troop_rosters_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A2B8..1A2D6: two real roster calls retain A4 absolute00FF3BC2 and D4 side WORD."""
    frame = _resource_cost_frame(state, frame, 0x1A2B8)
    frame = first_replace(frame, opponent=state.table_at(0x00FF3BC2),
        candidates=state.table_at(0xFFFFA550).cursor())
    frame = _movement_move(state, frame, 'distance', 0, 16)
    frame = _deployment_menu_call_fields(state, frame, 0x1A2D6, 0x1A2C8)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFA5A4).cursor())
    frame = _movement_move(state, frame, 'distance', 2, 16)
    return _deployment_menu_call_fields(state, frame, 0x1A2D6, 0x1A2D4)


def draw_city_troop_roster_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A2D6..1A320: each live member passes source/selection gates before numeric packet and renderer."""
    frame = _resource_cost_frame(state, frame, 0x1A2D6)
    while True:
        member = frame.candidates.word()
        frame = first_replace(frame, candidates=frame.candidates.advance(2))
        frame = _movement_move(state, frame, 'count', member, 16)
        if frame.status & 8:
            return frame
        frame = _movement_move(state, frame, 'count', low16(frame.count) & 255, 16)
        frame = _movement_move(state, frame, 'offset_x', low16(frame.count), 16)
        frame = _movement_fixed_shift_word(state, frame, 'count', 2)
        frame = first_replace(frame, controller=state.table_at(0xFFFFA150).cursor())
        frame = _movement_move(state, frame, 'target_x', frame.controller.word(low16(frame.count)), 16)
        if frame.status & 4:
            continue
        frame = _duel_commit_shift_fields(state, frame, 'target_x', 7, True)
        frame = _movement_move(state, frame, 'target_y', frame.controller.word(low16(frame.count), 2), 16)
        frame = _duel_commit_shift_fields(state, frame, 'target_y', 7, True)
        frame = _deployment_menu_call_fields(state, frame, 0x1A3CC, 0x1A2FA)
        if frame.status & 1:
            continue
        frame = _deployment_menu_call_fields(state, frame, 0x1A3B2, 0x1A300)
        if frame.status & 1:
            frame = _duel_menu_byte_bit_fields(state, frame, 0xFFFFF321, 3)
            if not frame.status & 4:
                continue
        frame = _deployment_menu_call_fields(state, frame, 0x1A320, 0x1A310)
        frame = first_replace(frame, roster=state.table_at(0xFFFFD400).cursor())
        frame = _movement_move(state, frame, 'unit', 0, 16)
        frame = _deployment_menu_call_fields(state, frame, 0xAC08, 0x1A31C)


def build_city_troop_number_packet_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A320..1A3AA: the original low-WORD troop thresholds and LONG DIVU glyph packet."""
    frame = _resource_cost_frame(state, frame, 0x1A320)
    frame = first_replace(frame, controller=state.table_at(0x1A3AA).cursor(),
        scan=state.table_at(0xFFFFD400).cursor())
    frame = _settlement_store_word_fields(state, frame, frame.scan, 0, 0xFFF8)
    frame = first_replace(frame, scan=frame.scan.advance(2))
    frame = _settlement_store_word_fields(state, frame, frame.scan, 0, frame.controller.word(low16(frame.distance)))
    frame = first_replace(frame, scan=frame.scan.advance(2))
    frame = _settlement_store_word_fields(state, frame, frame.scan, 0, 0x4FF8)
    frame = first_replace(frame, scan=frame.scan.advance(2), controller=state.table_at(0xFFFFC800).cursor())
    frame = _movement_move_long(state, frame, 'offset_x', frame.controller.long(low16(frame.count)))
    frame = _movement_compare(state, frame, low16(frame.offset_x), 1000, 16)
    if not frame.status & 1:
        frame = _movement_move(state, frame, 'offset_y', 0, 16)
        while True:
            frame = _duel_commit_sub_word_fields(state, frame, 'offset_x', 10000)
            if frame.status & 1:
                break
            frame = _movement_adjust_word(state, frame, 'offset_y', 1)
        frame = _movement_add_word(state, frame, 'offset_x', 10000)
        frame = _movement_test(state, frame, low16(frame.offset_y), 16)
        if frame.status & 4:
            frame = _movement_move(state, frame, 'offset_y', 0x4401, 16)
        else:
            frame = _movement_add_word(state, frame, 'offset_y', 0x4386)
        for value in (0, low16(frame.offset_y), 0x0FF8):
            frame = _settlement_store_word_fields(state, frame, frame.scan, 0, value)
            frame = first_replace(frame, scan=frame.scan.advance(2))
        # DIVU overflow retains D5; the immediately following ADDI.W defines every flag.
        if frame.offset_x // 1000 <= 65535:
            frame = _movement_divu_word(state, frame, 'offset_x', 1000, 0x1A370)
        frame = _movement_add_word(state, frame, 'offset_x', 0x4386)
    else:
        for value in (0, 0x4385, 0x0FF8):
            frame = _settlement_store_word_fields(state, frame, frame.scan, 0, value)
            frame = first_replace(frame, scan=frame.scan.advance(2))
        if frame.offset_x // 100 <= 65535:
            frame = _movement_divu_word(state, frame, 'offset_x', 100, 0x1A392)
        frame = _movement_add_word(state, frame, 'offset_x', 0x4386)
    for value in (0, low16(frame.offset_x), 0):
        frame = _settlement_store_word_fields(state, frame, frame.scan, 0, value)
        frame = first_replace(frame, scan=frame.scan.advance(2))
    return _settlement_store_word_fields(state, frame, frame.scan, 0, 0x8000)


def test_city_troop_selected_member_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1A3B2..1A3CC: actual A3/D6 sentinel search and carry-only membership result."""
    frame = _resource_cost_frame(state, frame, 0x1A3B2)
    frame = first_replace(frame, scan=state.table_at(0xFFFFA5F8).cursor())
