def _group_route_push_word_fields(state: SceneState, frame: FirstDeploymentFrame,
        value: int) -> FirstDeploymentFrame:
    stack=frame.stack_cursor.advance(-2)
    stack.set_word(0,uint(value,16))
    return _movement_test(state,first_replace(frame,stack_cursor=stack),value,16)


def _group_route_pop_word_fields(state: SceneState, frame: FirstDeploymentFrame,
        carrier: str) -> FirstDeploymentFrame:
    value=frame.stack_cursor.word()
    frame=first_replace(frame,stack_cursor=frame.stack_cursor.advance(2))
    return _movement_move(state,frame,carrier,value,16)


def _group_route_date_increment_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_group_route_memory_delta_fields(state,frame,0xFFFFF375,1,1)
    frame=_movement_compare(state,frame,state.read(0xFFFFF375,1),12,8)
    if not frame.status&1:
        frame=_group_route_memory_delta_fields(state,frame,0xFFFFF374,1,1)
        frame=_group_route_store_fields(state,frame,0xFFFFF375,0,1,True)
    return frame


def compute_group_neighbor_block_mask_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """149E4..14B6C: packed groups plus the terrain's eight ordered mask bits.

    Original BYTE neighbors wrap independently. The live terrain category
    lookup stays ROM-backed; all-bits-blocked carry is tested from D0 BYTE.
    """
    frame=_resource_cost_frame(state,frame,0x149E4)
    frame=_movement_move(state,frame,'target_x',0,16)
    frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
    frame=_movement_move(state,frame,'target_y',0,16)
    frame=_movement_move(state,frame,'target_y',frame.roster.byte(0,1),8)
    frame=_movement_move(state,frame,'distance',0,16)
    frame=_movement_move(state,frame,'distance',frame.roster.byte(0,2),8)
    frame=_movement_move(state,frame,'unit',low8(frame.target_y),8)
    frame=_movement_move(state,frame,'count',low8(frame.target_y),8)
    frame=_group_route_register_delta_fields(state,frame,'unit',-1,8)
    frame=_group_route_register_delta_fields(state,frame,'count',1,8)
    frame=_movement_move(state,frame,'offset_x',low8(frame.distance),8)
    frame=_movement_move(state,frame,'offset_y',low8(frame.distance),8)
    frame=_group_route_register_delta_fields(state,frame,'offset_x',-1,8)
    frame=_group_route_register_delta_fields(state,frame,'offset_y',1,8)
    frame=first_replace(frame,roster=state.table_at(0xFFFF9000).cursor())
    while True:
        frame=_movement_move(state,frame,'choice',frame.roster.byte(),8)
        frame=_movement_move(state,frame,'choice',low16(frame.choice)&15,16)
        if frame.status&4:
            break
        frame=_movement_compare(state,frame,low8(frame.target_y),frame.roster.byte(0,1),8)
        if frame.status&4:
            frame=_movement_compare(state,frame,low8(frame.offset_x),frame.roster.byte(0,2),8)
            if frame.status&4:
                frame=_group_route_set_mask_bit_fields(state,frame,3)
            else:
                frame=_movement_compare(state,frame,low8(frame.offset_y),frame.roster.byte(0,2),8)
                if frame.status&4:
                    frame=_group_route_set_mask_bit_fields(state,frame,1)
        else:
            frame=_movement_compare(state,frame,low8(frame.unit),frame.roster.byte(0,1),8)
            if frame.status&4:
                frame=_movement_compare(state,frame,low8(frame.distance),frame.roster.byte(0,2),8)
                if frame.status&4:
                    frame=_group_route_set_mask_bit_fields(state,frame,0)
                else:
                    frame=_movement_compare(state,frame,low8(frame.offset_x),frame.roster.byte(0,2),8)
                    if frame.status&4:
                        frame=_group_route_set_mask_bit_fields(state,frame,7)
                    else:
                        frame=_movement_compare(state,frame,low8(frame.offset_y),frame.roster.byte(0,2),8)
                        if frame.status&4:
                            frame=_group_route_set_mask_bit_fields(state,frame,4)
            else:
                frame=_movement_compare(state,frame,low8(frame.count),frame.roster.byte(0,1),8)
                if frame.status&4:
                    frame=_movement_compare(state,frame,low8(frame.distance),frame.roster.byte(0,2),8)
                    if frame.status&4:
                        frame=_group_route_set_mask_bit_fields(state,frame,2)
                    else:
                        frame=_movement_compare(state,frame,low8(frame.offset_x),frame.roster.byte(0,2),8)
                        if frame.status&4:
                            frame=_group_route_set_mask_bit_fields(state,frame,6)
                        else:
                            frame=_movement_compare(state,frame,low8(frame.offset_y),frame.roster.byte(0,2),8)
                            if frame.status&4:
                                frame=_group_route_set_mask_bit_fields(state,frame,5)
        frame=first_replace(frame,roster=frame.roster.advance(13+s16(low16(frame.choice))))
    frame=_movement_compare(state,frame,low8(frame.target_x),255,8)
    if not frame.status&4:
        frame=_movement_move(state,frame,'unit',low16(frame.target_y),16)
        frame=_movement_move(state,frame,'count',low16(frame.unit),16)
        frame=_movement_fixed_shift_word(state,frame,'count',3)
        frame=_movement_add_word(state,frame,'unit',low16(frame.count))
        frame=_movement_fixed_shift_word(state,frame,'unit',3)
        frame=_movement_add_word(state,frame,'unit',low16(frame.distance))
        frame=first_replace(frame,controller=state.table_at(u32(0xEE5F0+s16(low16(frame.unit)))),
            candidates=state.table_at(0x670A).cursor())
        frame=_movement_move(state,frame,'choice',0,16)
        frame=_movement_test(state,frame,low8(frame.target_y),8)
        if frame.status&4:
            frame=_movement_move(state,frame,'target_x',low8(frame.target_x)|0x91,8)
        else:
            for displacement,bit in ((-73,7),(-72,0),(-71,4)):
                frame=_movement_move(state,frame,'choice',frame.controller.byte(0,displacement),8)
                frame=_movement_test(state,frame,frame.candidates.byte(low16(frame.choice)),8)
                if frame.status&8:
                    frame=_group_route_set_mask_bit_fields(state,frame,bit)
        for displacement,bit in ((-1,3),(1,1)):
            frame=_movement_move(state,frame,'choice',frame.controller.byte(0,displacement),8)
            frame=_movement_test(state,frame,frame.candidates.byte(low16(frame.choice)),8)
            if frame.status&8:
                frame=_group_route_set_mask_bit_fields(state,frame,bit)
        frame=_movement_compare(state,frame,low8(frame.target_y),71,8)
        if not frame.status&1:
            frame=_movement_move(state,frame,'target_x',low8(frame.target_x)|0x64,8)
        else:
            for displacement,bit in ((71,6),(72,2),(73,5)):
                frame=_movement_move(state,frame,'choice',frame.controller.byte(0,displacement),8)
                frame=_movement_test(state,frame,frame.candidates.byte(low16(frame.choice)),8)
                if frame.status&8:
                    frame=_group_route_set_mask_bit_fields(state,frame,bit)
        frame=_movement_test(state,frame,low8(frame.distance),8)
        if frame.status&4:
            frame=_movement_move(state,frame,'target_x',low16(frame.target_x)|0xC8,16)
        else:
            frame=_movement_compare(state,frame,low8(frame.distance),71,8)
            if not frame.status&1:
                frame=_movement_move(state,frame,'target_x',low8(frame.target_x)|0x32,8)
        frame=_group_route_store_fields(state,frame,0xFFFFF678,low16(frame.target_x))
        frame=_movement_compare(state,frame,low8(frame.target_x),255,8)
    return _group_route_carry_fields(state,frame,bool(frame.status&4))


def scroll_camera_toward_group_waypoint_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """14D64: horizontal speed3, vertical speed4, real saved words around map strips."""
    frame=_resource_cost_frame(state,frame,0x14D64)
    frame=_movement_move(state,frame,'distance',0,16)
    frame=_movement_move(state,frame,'count',state.read(0xFFFFF314,2),16)
    frame=_movement_compare(state,frame,low16(frame.count),low16(frame.target_y),16)
    if not frame.status&4:
        increasing=not bool(frame.status&1)
        if not increasing:
            frame=_movement_compare(state,frame,low16(frame.count),928,16)
            if not frame.status&4:
                frame=_group_route_register_delta_fields(state,frame,'count',3)
                frame=_movement_compare(state,frame,low16(frame.count),low16(frame.target_y),16)
                if not frame.status&1 and not frame.status&4:
                    frame=_movement_move(state,frame,'count',low16(frame.target_y),16)
                frame=_movement_compare(state,frame,low16(frame.count),928,16)
                if not frame.status&1 and not frame.status&4:
                    frame=_movement_move(state,frame,'count',928,16)
                frame=_group_route_store_fields(state,frame,0xFFFFF314,low16(frame.count))
                frame=_movement_add_word(state,frame,'distance',1)
                frame=_movement_add_word(state,frame,'count',224)
                frame=first_replace(frame,scratch=state.table_at(u32(s16(low16(frame.count)))))
                frame=_group_route_push_word_fields(state,frame,low16(frame.distance))
                frame=_group_route_push_word_fields(state,frame,low16(frame.unit))
                frame=_group_route_call_fields(state,frame,0xA0CC,0x14DA0)
                frame=_group_route_pop_word_fields(state,frame,'unit')
                frame=_group_route_pop_word_fields(state,frame,'distance')
        else:
            frame=_group_route_register_delta_fields(state,frame,'count',-3)
            if not frame.status&1:
                frame=_movement_compare(state,frame,low16(frame.count),low16(frame.target_y),16)
            if frame.status&1:
                frame=_movement_move(state,frame,'count',low16(frame.target_y),16)
            frame=_group_route_store_fields(state,frame,0xFFFFF314,low16(frame.count))
            frame=_movement_add_word(state,frame,'distance',1)
            frame=first_replace(frame,scratch=state.table_at(u32(s16(low16(frame.count)))))
            frame=_group_route_push_word_fields(state,frame,low16(frame.distance))
            frame=_group_route_push_word_fields(state,frame,low16(frame.unit))
            frame=_group_route_call_fields(state,frame,0xA0CC,0x14DC2)
            frame=_group_route_pop_word_fields(state,frame,'unit')
            frame=_group_route_pop_word_fields(state,frame,'distance')
    frame=_movement_move(state,frame,'count',state.read(0xFFFFF318,2),16)
    frame=_movement_compare(state,frame,low16(frame.count),low16(frame.unit),16)
    if frame.status&4:
        return frame
    if frame.status&1:
        frame=_movement_compare(state,frame,low16(frame.count),832,16)
        if frame.status&4:
            return frame
        frame=_group_route_register_delta_fields(state,frame,'count',4)
        frame=_movement_compare(state,frame,low16(frame.count),low16(frame.unit),16)
        if not frame.status&1 and not frame.status&4:
            frame=_movement_move(state,frame,'count',low16(frame.unit),16)
        frame=_movement_compare(state,frame,low16(frame.count),832,16)
        if not frame.status&1 and not frame.status&4:
            frame=_movement_move(state,frame,'count',832,16)
        frame=_group_route_store_fields(state,frame,0xFFFFF318,low16(frame.count))
        frame=_movement_add_word(state,frame,'distance',1)
        frame=_movement_add_word(state,frame,'count',320)
        frame=first_replace(frame,scratch=state.table_at(u32(s16(low16(frame.count)))))
        frame=_group_route_push_word_fields(state,frame,low16(frame.distance))
        frame=_group_route_call_fields(state,frame,0xA10C,0x14DFC)
    else:
        frame=_group_route_register_delta_fields(state,frame,'count',-4)
        if not frame.status&1:
            frame=_movement_compare(state,frame,low16(frame.count),low16(frame.unit),16)
        if frame.status&1:
            frame=_movement_move(state,frame,'count',low16(frame.unit),16)
        frame=_group_route_store_fields(state,frame,0xFFFFF318,low16(frame.count))
        frame=_movement_add_word(state,frame,'distance',1)
        frame=first_replace(frame,scratch=state.table_at(u32(s16(low16(frame.count)))))
        frame=_group_route_push_word_fields(state,frame,low16(frame.distance))
        frame=_group_route_call_fields(state,frame,0xA10C,0x14E1C)
    return _group_route_pop_word_fields(state,frame,'distance')


"""Group route selection and command state transitions, one Scene-field algorithm."""

def step_packed_group_command_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """14050: route-button entry, explicit live command screens and pending route."""
    frame=_resource_cost_frame(state,frame,0x14050)
    frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF3A4,1),6)
    if not frame.status&4:
        frame=_group_route_call_fields(state,frame,0xA158,0x1405E)
        frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF603,1),5)
        if not frame.status&4:
            frame=_group_route_store_fields(state,frame,0xFFFFF3C2,state.read(0xFFFFF612,2))
            frame=_group_route_store_fields(state,frame,0xFFFFF3C4,state.read(0xFFFFF362,2))
            frame=_group_route_store_fields(state,frame,0xFFFFF612,520)
            frame=_group_route_store_fields(state,frame,0xFFFFF362,19)
            return _group_route_store_fields(state,frame,0xFFFFF36A,0,2,True)
        frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF603,1),4)
        if not frame.status&4:
            for address,value in ((0xFFFFF612,520),(0xFFFFF362,2),(0xFFFFF36A,18)):
                frame=_group_route_store_fields(state,frame,address,value)
        return frame
    frame=_group_route_call_fields(state,frame,0x1264,0x140AA)
    frame=_group_route_call_fields(state,frame,0x14120,0x140AE)
    frame=_group_route_call_fields(state,frame,0x1416A,0x140B2)
    frame=_group_route_call_fields(state,frame,0x14364,0x140B6)
    frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF603,1),4)
    if not frame.status&4:
        return _group_route_call_fields(state,frame,0x142D0,0x140C2)
    frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF603,1),5)
    if frame.status&4:
        return frame
    frame=_movement_test(state,frame,state.read(0xFF3820,2),16)
    if frame.status&4:
        return frame
    frame=_group_route_store_fields(state,frame,0xFFFFF612,520)
    frame=_group_route_store_fields(state,frame,0xFFFFF362,4)
    frame=first_replace(frame,roster=state.table_at(0xFF3800).cursor())
    frame=_movement_move(state,frame,'target_x',state.read(0xFF3820,2),16)
    address=frame.roster.address(low16(frame.target_x))
    frame=_group_route_store_fields(state,frame,address,0,1,True)
    frame=_group_route_store_fields(state,frame,0xFFFFF35E,state.read(0xFF3822,2))
    frame=_group_route_store_fields(state,frame,0xFFFFF360,state.read(0xFF3824,2))
    return _group_route_call_fields(state,frame,0x14106,0x14104)


def consume_group_route_step_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """142D0: remove one pending direction and execute the live signed offset table."""
    frame=_resource_cost_frame(state,frame,0x142D0)
    frame=_movement_test(state,frame,state.read(0xFF3820,2),16)
    if not frame.status&4:
        frame=_movement_move(state,frame,'target_x',state.read(0xFF3822,2),16)
        frame=_movement_move(state,frame,'target_y',state.read(0xFF3824,2),16)
        frame=_group_route_call_fields(state,frame,0x14294,0x142E6)
        frame,result=_movement_binary_flags(state,frame,state.read(0xFFFFF674,2),low16(frame.count),16)
        state.write(0xFFFFF674,2,result)
        frame=first_replace(frame,roster=state.table_at(0xFF3800).cursor())
        frame=_group_route_memory_delta_fields(state,frame,0xFF3820,-1)
        frame=_movement_move(state,frame,'target_x',state.read(0xFF3820,2),16)
        frame=_movement_move(state,frame,'target_y',0,16)
        frame=_movement_move(state,frame,'target_y',frame.roster.byte(low16(frame.target_x)),8)
        frame=_movement_fixed_shift_word(state,frame,'target_y',1)
        frame=_movement_move(state,frame,'target_y',state.read(u32(0x14332+s16(low16(frame.target_y))),2),16)
        target=u32(0x1433C+s16(low16(frame.target_y)))
        return _group_route_call_fields(state,frame,target,0x1430C)
    for address,value in ((0xFFFFF612,520),(0xFFFFF362,2),(0xFFFFF36A,18)):
        frame=_group_route_store_fields(state,frame,address,value)
    frame=_movement_test(state,frame,state.read(0xFFFFF65A,2),16)
    if frame.status&4:
        frame=_group_route_call_fields(state,frame,0x5694,0x1432C)
        frame=_group_route_call_fields(state,frame,0x5ABC,0x14332)
    return frame


def shift_group_route_east_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    return _group_route_memory_delta_fields(state,_resource_cost_frame(state,frame,0x1433C),0xFF3822,16)


def shift_group_route_north_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    return _group_route_memory_delta_fields(state,_resource_cost_frame(state,frame,0x14346),0xFF3824,-16)


def shift_group_route_west_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    return _group_route_memory_delta_fields(state,_resource_cost_frame(state,frame,0x14350),0xFF3822,-16)


def shift_group_route_south_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    return _group_route_memory_delta_fields(state,_resource_cost_frame(state,frame,0x1435A),0xFF3824,16)


def follow_group_route_camera_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """14364: ordered two-axis camera thresholds; each strip is the unique map core."""
    frame=_resource_cost_frame(state,frame,0x14364)
    frame=_movement_move(state,frame,'target_x',state.read(0xFF3822,2),16)
    frame=_group_route_register_delta_fields(state,frame,'target_x',-state.read(0xFFFFF314,2))
    lower=bool(frame.status&1)
    if not lower:
        frame=_movement_compare(state,frame,low16(frame.target_x),96,16)
        lower=bool(frame.status&1)
    if lower:
        frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF314,2),16)
        if not frame.status&4:
            frame=_group_route_register_delta_fields(state,frame,'target_x',-1)
            if frame.status&1:
                frame=_movement_move(state,frame,'target_x',0,16)
            frame=_group_route_store_fields(state,frame,0xFFFFF314,low16(frame.target_x))
            frame=first_replace(frame,scratch=state.table_at(u32(s16(low16(frame.target_x)))))
            frame=_group_route_call_fields(state,frame,0xA0CC,0x1438E)
    else:
        frame=_movement_compare(state,frame,low16(frame.target_x),128,16)
        if not frame.status&1:
            frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF314,2),16)
            frame=_movement_add_word(state,frame,'target_x',1)
            frame=_movement_compare(state,frame,low16(frame.target_x),928,16)
            if not frame.status&1 and not frame.status&4:
                frame=_movement_move(state,frame,'target_x',928,16)
            frame=_group_route_store_fields(state,frame,0xFFFFF314,low16(frame.target_x))
            frame=_movement_add_word(state,frame,'target_x',224)
            frame=first_replace(frame,scratch=state.table_at(u32(s16(low16(frame.target_x)))))
            frame=_group_route_call_fields(state,frame,0xA0CC,0x143B8)
    frame=_movement_move(state,frame,'target_x',state.read(0xFF3824,2),16)
    frame=_group_route_register_delta_fields(state,frame,'target_x',-state.read(0xFFFFF318,2))
    lower=bool(frame.status&1)
    if not lower:
        frame=_movement_compare(state,frame,low16(frame.target_x),96,16)
        lower=bool(frame.status&1 or frame.status&4)
    if lower:
        frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF318,2),16)
        frame=_group_route_register_delta_fields(state,frame,'target_x',-1)
        if frame.status&1:
            frame=_movement_move(state,frame,'target_x',0,16)
        frame=_group_route_store_fields(state,frame,0xFFFFF318,low16(frame.target_x))
        frame=first_replace(frame,scratch=state.table_at(u32(s16(low16(frame.target_x)))))
        return _group_route_call_fields(state,frame,0xA10C,0x143E0)
    frame=_movement_compare(state,frame,low16(frame.target_x),224,16)
    if not frame.status&1:
        frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF318,2),16)
        frame=_movement_add_word(state,frame,'target_x',1)
        frame=_movement_compare(state,frame,low16(frame.target_x),832,16)
        if not frame.status&1 and not frame.status&4:
            frame=_movement_move(state,frame,'target_x',832,16)
        frame=_group_route_store_fields(state,frame,0xFFFFF318,low16(frame.target_x))
        frame=_movement_add_word(state,frame,'target_x',320)
        frame=first_replace(frame,scratch=state.table_at(u32(s16(low16(frame.target_x)))))
        frame=_group_route_call_fields(state,frame,0xA10C,0x1440C)
    return frame


def activate_group_route_selection_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x1440E)
    frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF3A4,1),3)
    if frame.status&4:
        frame=_group_route_call_fields(state,frame,0x1626C,0x1441A)
        frame=_movement_compare(state,frame,state.read(0xFFFFF36C,2),2,16)
        if frame.status&4:
            frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
            frame=_movement_move(state,frame,'target_x',frame.roster.byte(0,4),8)
            frame=_movement_compare(state,frame,low8(frame.target_x),state.read(0xFFFFF377,1),8)
            if frame.status&4:
                frame=_movement_move(state,frame,'target_x',frame.roster.byte(),8)
                frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&127,16)
                frame=_movement_compare(state,frame,low16(frame.target_x),16,16)
                if frame.status&1:
                    frame=_group_route_call_fields(state,frame,0x14494,0x14448)
    else:
        frame=_group_route_memory_delta_fields(state,frame,0xFFFFF362,1)
        frame=_group_route_store_fields(state,frame,0xFFFFCFD2,8)
        frame=_movement_compare(state,frame,state.read(0xFFFFF36C,2),2,16)
        if frame.status&4:
            frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
            frame=_movement_move(state,frame,'target_x',frame.roster.byte(0,4),8)
            frame=_movement_compare(state,frame,low8(frame.target_x),state.read(0xFFFFF377,1),8)
            if frame.status&4:
                frame=_movement_move(state,frame,'target_x',frame.roster.byte(),8)
                frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&127,16)
                frame=_movement_compare(state,frame,low16(frame.target_x),16,16)
                if frame.status&1:
                    frame=_group_route_call_fields(state,frame,0x14574,0x14482)
                    frame=_movement_move(state,frame,'target_x',3,16)
                    frame=_group_route_call_fields(state,frame,0x676F2,0x1448C)
    return _group_route_call_fields(state,frame,0xA158,0x14492)


def confirm_group_action_option_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1478A: current own group option, debounce, selection, cancel and cursor."""
    frame=_resource_cost_frame(state,frame,0x1478A)
    frame=_movement_compare(state,frame,state.read(0xFFFFF36C,2),2,16)
    if frame.status&4:
        frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
        frame=_movement_move(state,frame,'target_x',frame.roster.byte(0,4),8)
        frame=_movement_compare(state,frame,low8(frame.target_x),state.read(0xFFFFF377,1),8)
        if frame.status&4:
            frame=_movement_move(state,frame,'target_x',frame.roster.byte(),8)
            frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&127,16)
            frame=_movement_compare(state,frame,low16(frame.target_x),16,16)
            if frame.status&1:
                frame=_group_route_call_fields(state,frame,0x148A4,0x147B8)
                frame=_group_route_call_fields(state,frame,0x14914,0x147BC)
                frame=_movement_test(state,frame,state.read(0xFFFFCFD2,2),16)
                if not frame.status&4:
                    frame=_group_route_memory_delta_fields(state,frame,0xFFFFCFD2,-1)
                    frame=_movement_compare(state,frame,state.read(0xFFFFCFD2,2),8,16)
                    if not frame.status&1 and not frame.status&4:
                        frame=_group_route_store_fields(state,frame,0xFFFFCFD2,8)
                    return _group_route_call_fields(state,frame,0xA158,0x148A2)
                frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF603,1),5)
                if not frame.status&4:
                    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF676,2),16)
                    frame=first_replace(frame,roster=state.table_at(0xFF3930).cursor())
                    frame=_movement_move(state,frame,'target_y',0,16)
                    frame=_movement_move(state,frame,'target_y',frame.roster.byte(low16(frame.target_x)),8)
                    frame=_group_route_store_fields(state,frame,0xFFFFF386,low16(frame.target_y))
                    frame=_group_route_store_fields(state,frame,0xFFFFF388,0,2,True)
                    frame=_group_route_store_fields(state,frame,0xFFFFF384,0,2,True)
                    frame=_movement_add_word(state,frame,'target_y',1)
                    frame=_group_route_store_fields(state,frame,0xFFFFF65A,low16(frame.target_y))
                    frame=_movement_compare(state,frame,low16(frame.target_y),2,16)
                    if frame.status&4:
                        frame=_group_route_call_fields(state,frame,0x149E4,0x14810)
                        if frame.status&1:
                            return _group_route_call_fields(state,frame,0xA158,0x148A2)
                    frame=_group_route_call_fields(state,frame,0xC0B6,0x14818)
                    for address,value in ((0xFFFFF612,520),(0xFFFFF362,3),(0xFFFFF36A,18)):
                        frame=_group_route_store_fields(state,frame,address,value)
                    frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
                    for displacement,address in ((1,0xFF3822),(2,0xFF3824)):
                        frame=_movement_move(state,frame,'target_x',0,16)
                        frame=_movement_move(state,frame,'target_x',frame.roster.byte(0,displacement),8)
                        frame=_movement_fixed_shift_word(state,frame,'target_x',4)
                        frame=_group_route_store_fields(state,frame,address,low16(frame.target_x))
                    frame=_movement_move(state,frame,'target_x',0,16)
                    frame=_movement_move(state,frame,'target_x',frame.roster.byte(0,3),8)
                    frame=_group_route_store_fields(state,frame,0xFFFFF672,low16(frame.target_x))
                    frame=_group_route_store_fields(state,frame,0xFFFFF600,116)
                    return _group_route_call_fields(state,frame,0xA158,0x148A2)
    frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF603,1),4)
    if not frame.status&4:
        frame=_movement_compare(state,frame,state.read(0xFFFFF36C,2),2,16)
        if frame.status&4:
            for address,value in ((0xFFFFF612,520),(0xFFFFF362,2),(0xFFFFF36A,18)):
                frame=_group_route_store_fields(state,frame,address,value)
            frame=_group_route_store_fields(state,frame,0xFFFFF65A,0,2,True)
        else:
            for address,value in ((0xFFFFF612,518),(0xFFFFF362,7),(0xFFFFF36A,13)):
                frame=_group_route_store_fields(state,frame,address,value)
    return _group_route_call_fields(state,frame,0xA158,0x148A2)


"""Complete ongoing group route and queued movement state machines."""

def advance_packed_group_routes_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """14B6C..14C7C: step the live queue, or enter the original next-month state.

    The sentinel search remains unbounded if its reference is missing. No
    artificial scan cap or repaired record is introduced.
    """
    frame=_resource_cost_frame(state,frame,0x14B6C)
    frame=_movement_test(state,frame,state.read(0xFFFFCFCC,2),16)
    if frame.status&4:
        frame=_group_route_call_fields(state,frame,0x662E4,0x14B7A)
        if frame.status&1:
            frame=_group_route_store_fields(state,frame,0xFFFFF362,11)
            frame=_movement_move(state,frame,'target_x',156,16)
            return _group_route_call_fields(state,frame,0x676F2,0x14C6E)
    return _advance_group_routes_after_growth_fields(state,frame)


def _advance_group_routes_after_growth_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Actual same-owner restart at14B7E; no synthetic call or growth re-run."""
    # Same phase is the original queue loop, not an additional assembly entry.
    # This source helper executes the continuation directly with unchanged SP.
    while True:
        frame=_group_route_call_fields(state,frame,0x11EE,0x14B84)
        if frame.status&1:
            frame=_group_route_store_fields(state,frame,0xFFFFF612,524)
            return _group_route_store_fields(state,frame,0xFFFFF362,0,2,True)
        frame=first_replace(frame,roster=state.table_at(u32(0xFF39B2+s16(state.read(0xFF3BB2,2)))).cursor())
        frame=_movement_test(state,frame,frame.roster.byte(),8)
        if not frame.status&4:
            frame=_group_route_call_fields(state,frame,0x1264,0x14BA0)
        frame=first_replace(frame,roster=state.table_at(u32(0xFF39B2+s16(state.read(0xFF3BB2,2)))).cursor())
        frame=_movement_test(state,frame,frame.roster.byte(),8)
        if frame.status&4:
            frame=_group_route_store_fields(state,frame,0xFF3000,255,1)
            frame=_group_route_store_fields(state,frame,0xFFFFF612,513)
            frame=_group_route_store_fields(state,frame,0xFF3826,0,2,True)
            frame=_group_route_store_fields(state,frame,0xFFFFF36C,0,2,True)
            frame=_group_route_store_fields(state,frame,0xFFFFF376,65535)
            frame=_group_route_date_increment_fields(state,frame)
            frame=_group_route_store_fields(state,frame,0xFFFFF600,128)
            frame=_group_route_call_fields(state,frame,0x14C7C,0x14C54)
            return _group_route_store_fields(state,frame,0xFFFFF376,65535)
        frame=_movement_move(state,frame,'target_x',0,16)
        frame=_movement_move(state,frame,'target_x',frame.roster.byte(0,1),8)
        frame=_group_route_store_fields(state,frame,0xFF3BB4,low16(frame.target_x))
        frame=_group_route_call_fields(state,frame,0x14CA4,0x14BC2)
        frame=_group_route_call_fields(state,frame,0x14E20,0x14BC6)
        if frame.status&1:
            continue
        return _finish_group_route_queue_selection_fields(state,frame)


def _finish_group_route_queue_selection_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Shared same-owner selection tail; no physical BSR is invented."""
    frame=_group_route_call_fields(state,frame,0x14D64,0x14BCC)
    frame=_movement_test(state,frame,low16(frame.distance),16)
    if not frame.status&4:
        return frame
    frame=first_replace(frame,roster=state.table_at(0xFF3000).cursor())
    frame=_movement_move(state,frame,'target_x',0,16)
    while True:
        frame=first_replace(frame,roster=frame.roster.advance(1))
        frame=_movement_add_word(state,frame,'target_x',3)
        value=frame.roster.byte()
        frame=first_replace(frame,roster=frame.roster.advance(1))
        frame=_movement_move(state,frame,'target_y',value,8)
        frame=_movement_compare(state,frame,low8(frame.target_y),state.read(0xFF3BB5,1),8)
        if frame.status&4:
            break
        frame=first_replace(frame,roster=frame.roster.advance(1))
        while True:
            frame=_movement_add_word(state,frame,'target_x',1)
            value=frame.roster.byte()
            frame=first_replace(frame,roster=frame.roster.advance(1))
            frame=_movement_test(state,frame,value,8)
            if frame.status&4:
                break
    frame=_group_route_store_fields(state,frame,0xFF3826,low16(frame.target_x))
    frame=_group_route_memory_delta_fields(state,frame,0xFFFFF362,1)
    frame=_movement_test_long(state,frame,state.read(0xFF382C,4))
    if not frame.status&4:
        frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
        frame=_group_route_change_memory_bit_fields(state,frame,frame.roster.address(),5,False)
        frame=_group_route_change_memory_bit_fields(state,frame,frame.roster.address(),4,True)
    return frame


def _moving_group_apply_cell_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
    for address,displacement in ((0xFF3BB6,1),(0xFF3BB8,2)):
        frame=_movement_move(state,frame,'target_x',state.read(address,2),16)
        frame=_movement_fixed_shift_word(state,frame,'target_x',4,True)
        frame=_group_route_store_fields(state,frame,frame.roster.address(0,displacement),low8(frame.target_x),1)
    return frame


def _moving_group_scroll_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_movement_move(state,frame,'target_y',state.read(0xFF3BB6,2),16)
    frame=_group_route_register_delta_fields(state,frame,'target_y',-104)
    if frame.status&1:
        frame=_movement_move(state,frame,'target_y',0,16)
    frame=_movement_move(state,frame,'unit',state.read(0xFF3BB8,2),16)
    frame=_group_route_register_delta_fields(state,frame,'unit',-152)
    if frame.status&1:
        frame=_movement_move(state,frame,'unit',0,16)
    return _group_route_call_fields(state,frame,0x14D64,0x14F4A)


def _moving_group_end_route_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_moving_group_apply_cell_fields(state,frame)
    frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
    frame=_group_route_change_memory_bit_fields(state,frame,frame.roster.address(),6,False)
    frame=_group_route_call_fields(state,frame,0x1512E,0x14F82)
    frame=_group_route_memory_delta_fields(state,frame,0xFF3BB2,2)
    frame=_movement_move(state,frame,'target_y',0,16)
    frame=_movement_move(state,frame,'target_y',frame.roster.byte(0,4),8)
    frame=_group_route_store_fields(state,frame,0xFFFFF376,low16(frame.target_y))
    frame=_group_route_call_fields(state,frame,0x13DC,0x14F98)
    if not frame.status&1:
        frame=_group_route_store_fields(state,frame,0xFFFFF376,65535)
        frame=_group_route_call_fields(state,frame,0x1CEA0,0x14FA8)
        frame=_movement_test(state,frame,low16(frame.target_x),16)
        if not frame.status&4:
            for address,value in ((0xFFFFF65A,20),(0xFFFFF38C,185),(0xFFFFF612,520),(0xFFFFF362,4)):
                frame=_group_route_store_fields(state,frame,address,value)
            return _group_route_store_fields(state,frame,0xFFFFF576,0,2,True)
    frame=_group_route_call_fields(state,frame,0x15572,0x14FD2)
    if frame.status&1:
        return frame
    frame=_group_route_memory_delta_fields(state,frame,0xFFFFF362,-1)
    frame=_movement_test_long(state,frame,state.read(0xFF382C,4))
    if frame.status&4:
        return frame
    frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
    frame=_movement_move(state,frame,'target_y',0,16)
    frame=_movement_move(state,frame,'target_y',frame.roster.byte(0,4),8)
    frame=_group_route_store_fields(state,frame,0xFFFFF376,low16(frame.target_y))
    frame=_group_route_call_fields(state,frame,0x13DC,0x14FFA)
    if frame.status&1:
        frame=_group_route_store_fields(state,frame,0xFFFFF600,180)
    return frame


def step_moving_packed_group_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """14E58..150DE: apply tile arrivals, move pixels, scan events and battle gates."""
    frame=_resource_cost_frame(state,frame,0x14E58)
    frame=_group_route_store_fields(state,frame,0xFFFFCFCC,0,2,True)
    frame=_movement_test(state,frame,state.read(0xFFFFF68A,2),16)
    if not frame.status&8:
        return _moving_group_enter_encounter_fields(state,frame)
    frame=_movement_move(state,frame,'target_x',state.read(0xFF3BB6,2),16)
    frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&15,16)
    aligned=bool(frame.status&4)
    if aligned:
        frame=_movement_move(state,frame,'target_x',state.read(0xFF3BB8,2),16)
        frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&15,16)
        aligned=bool(frame.status&4)
    if aligned:
        frame=_moving_group_apply_cell_fields(state,frame)
        frame=first_replace(frame,roster=state.table_at(u32(0xFF3000+s16(state.read(0xFF3826,2)))).cursor())
        frame=_movement_move(state,frame,'target_x',frame.roster.byte(),8)
        if frame.status&4:
            return _moving_group_end_route_fields(state,frame)
        frame=_group_route_call_fields(state,frame,0x150DE,0x14EB0)
        frame=_group_route_call_fields(state,frame,0x152BE,0x14EB4)
        if frame.status&1:
            return _moving_group_end_route_fields(state,frame)
        frame=_group_route_memory_delta_fields(state,frame,0xFF3826,1)
        frame=_group_route_call_fields(state,frame,0x159EA,0x14EC2)
        frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
        frame=_movement_move(state,frame,'target_x',0,16)
        frame=_movement_move(state,frame,'target_x',frame.roster.byte(0,1),8)
        frame=_movement_move(state,frame,'target_y',0,16)
        frame=_movement_move(state,frame,'target_y',frame.roster.byte(0,2),8)
        frame=_group_route_call_fields(state,frame,0x142A2,0x14ED8)
        frame=_movement_compare(state,frame,low8(frame.unit),4,8)
        if not frame.status&4:
            frame=_movement_move(state,frame,'target_x',164,16)
            frame=_group_route_call_fields(state,frame,0x808A,0x14EEA)
    frame=_movement_move(state,frame,'target_x',state.read(0xFF3BB6,2),16)
    frame=_movement_compare(state,frame,low16(frame.target_x),state.read(0xFF3BBA,2),16)
    if not frame.status&4:
        frame=_group_route_memory_delta_fields(state,frame,0xFF3BB6,-1 if not frame.status&1 else 1)
    frame=_movement_move(state,frame,'target_x',state.read(0xFF3BB8,2),16)
    frame=_movement_compare(state,frame,low16(frame.target_x),state.read(0xFF3BBC,2),16)
    if not frame.status&4:
        frame=_group_route_memory_delta_fields(state,frame,0xFF3BB8,-1 if not frame.status&1 else 1)
    frame=_moving_group_scroll_fields(state,frame)
    frame=_group_route_call_fields(state,frame,0x15384,0x14F4E)
    if frame.status&1:
        return _moving_group_end_route_fields(state,frame)
    return frame


def _moving_group_enter_encounter_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Same original14E58 owner encounter arm, including the complete palette copy."""
    frame=_movement_compare(state,frame,state.read(0xFFFFF68A,2),50,16)
    if frame.status&4:
        frame=_group_route_call_fields(state,frame,0x1CEA0,0x150B8)
        frame=_movement_test(state,frame,low16(frame.target_x),16)
        if frame.status&4:
            return _moving_group_end_route_fields(state,frame)
        for address,value in ((0xFFFFF65A,19),(0xFFFFF38C,180),(0xFFFFF612,520),(0xFFFFF362,4)):
            frame=_group_route_store_fields(state,frame,address,value)
        return _group_route_memory_delta_fields(state,frame,0xFF3BB2,2)
    frame=_group_route_store_fields(state,frame,0xFFFFA5F8,65535)
    frame=_group_route_store_fields(state,frame,0xFFFFF612,1024)
    frame=_group_route_store_fields(state,frame,0xFFFFF362,0,2,True)
    frame=_group_route_store_fields(state,frame,0xFFFFF352,0,2,True)
    frame=_movement_move(state,frame,'target_x',31,16)
    frame=first_replace(frame,roster=state.table_at(0xFFFFFB00).cursor(),candidates=state.table_at(0xFFFFFB80).cursor())
    while True:
        value=frame.roster.word()
        frame=first_replace(frame,roster=frame.roster.advance(2))
        frame=_group_route_store_fields(state,frame,frame.candidates.address(),value)
        frame=first_replace(frame,candidates=frame.candidates.advance(2))
        count=u16(low16(frame.target_x)-1)
        frame=first_replace(frame,target_x=replace_word(frame.target_x,count))
        if count==65535:
            break
    for address,value,clear in ((0xFFFFA550,65535,False),(0xFFFFA5A4,65535,False),(0xFFFFF36A,0,True)):
        frame=_group_route_store_fields(state,frame,address,value,2,clear)
    frame=_group_route_memory_delta_fields(state,frame,0xFF3BB2,2)
    frame=_group_route_call_fields(state,frame,0x1B098,0x15058)
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF68A,2),16)
    frame=first_replace(frame,roster=state.table_at(0xFFFFF427).cursor())
    frame=_movement_move(state,frame,'target_x',frame.roster.byte(low16(frame.target_x)),8)
    matched=False
    for address in (0xFFFFF67B,0xFFFFF67D,0xFFFFF67F):
        frame=_movement_compare(state,frame,low8(frame.target_x),state.read(address,1),8)
        if frame.status&4:
            matched=True
            break
    if not matched:
        return frame
    frame=_group_route_store_fields(state,frame,0xFFFFF612,521)
    frame=_group_route_store_fields(state,frame,0xFFFFF362,14)
    frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&15,16)
    frame=_group_route_store_fields(state,frame,0xFFFFF376,low16(frame.target_x))
    frame=_movement_move(state,frame,'target_y',state.read(0xFFFFF68A,2),16)
    frame=_group_route_store_fields(state,frame,0xFFFFF646,low16(frame.target_y))
    frame=_movement_move(state,frame,'target_x',148,16)
    frame=first_replace(frame,roster=state.table_at(0xFFFF9FFF).cursor())
    frame=_movement_test(state,frame,frame.roster.byte(low16(frame.target_y)),8)
    if frame.status&4:
        frame=_group_route_call_fields(state,frame,0x676F2,0x150AE)
    return frame


"""Packed group roster, action-choice, fade and ally-confirmation rules."""

def increase_group_members_training_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """159EA: original low-nibble DBRA count, including65536 zero-count reads."""
    frame=_resource_cost_frame(state,frame,0x159EA)
    frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
    frame=_movement_move(state,frame,'target_x',frame.roster.byte(),8)
    frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&15,16)
    frame=_group_route_register_delta_fields(state,frame,'target_x',-1)
    frame=first_replace(frame,candidates=state.table_at(0xFFFFC000).cursor(),roster=frame.roster.advance(13))
    frame=_movement_move(state,frame,'target_y',0,16)
    while True:
        value=frame.roster.byte()
        frame=first_replace(frame,roster=frame.roster.advance(1))
        frame=_movement_move(state,frame,'target_y',value,8)
        frame=_movement_fixed_shift_word(state,frame,'target_y',1)
        address=frame.candidates.address(low16(frame.target_y))
        frame=_movement_compare(state,frame,state.read(address,2),999,16)
        if frame.status&1:
            frame=_group_route_memory_delta_fields(state,frame,address,1)
        count=u16(low16(frame.target_x)-1)
        frame=first_replace(frame,target_x=replace_word(frame.target_x,count))
        if count==65535:
            return frame


def _group_members_to_word_roster_fields(state: SceneState, frame: FirstDeploymentFrame,
        entry: int) -> FirstDeploymentFrame:
    """One packed member expansion, preserving each original CLR placement."""
    if entry not in (0x15A1A,0x15C7E,0x165AC):
        raise ValueError('closed packed roster entry role required')
    frame=_resource_cost_frame(state,frame,entry)
    frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
    if entry==0x165AC:
        frame=_movement_move(state,frame,'target_x',0,16)
    frame=_movement_move(state,frame,'target_x',frame.roster.byte(),8)
    frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&15,16)
    frame=_group_route_store_fields(state,frame,0xFFFFF636,low16(frame.target_x))
    if entry!=0x165AC:
        frame=_group_route_register_delta_fields(state,frame,'target_x',-1)
        frame=first_replace(frame,roster=frame.roster.advance(13))
        frame=first_replace(frame,candidates=state.table_at(0xFFFFF500).cursor())
    else:
        frame=first_replace(frame,candidates=state.table_at(0xFFFFF500).cursor())
        frame=_movement_move(state,frame,'target_y',0,16)
        frame=_group_route_register_delta_fields(state,frame,'target_x',-1)
        frame=first_replace(frame,roster=frame.roster.advance(13))
    while True:
        if entry!=0x165AC:
            frame=_movement_move(state,frame,'target_y',0,16)
        value=frame.roster.byte()
        frame=first_replace(frame,roster=frame.roster.advance(1))
        frame=_movement_move(state,frame,'target_y',value,8)
        frame=_group_route_store_fields(state,frame,frame.candidates.address(),low16(frame.target_y))
        frame=first_replace(frame,candidates=frame.candidates.advance(2))
        count=u16(low16(frame.target_x)-1)
        frame=first_replace(frame,target_x=replace_word(frame.target_x,count))
        if count==65535:
            break
    frame=_group_route_store_fields(state,frame,frame.candidates.address(),65535)
    if entry==0x165AC:
        return frame
    frame=_group_route_store_fields(state,frame,0xFFFFF65A,16 if entry==0x15A1A else 18)
    frame=_group_route_store_fields(state,frame,0xFFFFF684,0,2,True)
    frame=_group_route_store_fields(state,frame,0xFFFFF38C,160 if entry==0x15A1A else 176)
    frame=_group_route_store_fields(state,frame,0xFFFFF612,520)
    return _group_route_store_fields(state,frame,0xFFFFF362,4)


def prepare_group_split_roster_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    return _group_members_to_word_roster_fields(state,frame,0x15A1A)


def prepare_group_detach_roster_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    return _group_members_to_word_roster_fields(state,frame,0x15C7E)


def copy_group_members_to_action_roster_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    return _group_members_to_word_roster_fields(state,frame,0x165AC)


def update_group_action_choice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x15ACC)
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF603,1),8)
    frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&3,16)
    if frame.status&4:
        return frame
    frame=_group_route_bit_fields(state,frame,frame.target_x,1)
    return _group_route_store_fields(state,frame,0xFFFFF386,0 if frame.status&4 else 1,2,bool(frame.status&4))


def _render_group_action_cursor_fields(state: SceneState, frame: FirstDeploymentFrame,
        skip_gate: bool) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x15B08 if skip_gate else 0x15AEA)
    if not skip_gate:
        frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF603,1),5)
        if not frame.status&4:
            return frame
        frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF602,1),8)
        frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&3,16)
        if frame.status&4:
            frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF321,1),3)
            if not frame.status&4:
                return frame
    frame=first_replace(frame,roster=state.table_at(0x15B2C).cursor())
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF386,2),16)
    frame=_movement_fixed_shift_word(state,frame,'target_x',1)
    frame=_movement_add_word(state,frame,'target_x',state.read(0xFFFFF386,2))
    frame=_movement_fixed_shift_word(state,frame,'target_x',3)
    frame=_movement_add_word(state,frame,'target_x',64)
    frame=_movement_move(state,frame,'target_y',136,16)
    frame=_movement_move(state,frame,'unit',0,16)
    return _group_route_call_fields(state,frame,0xAC08,0x15B2A)


def render_group_action_cursor_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    return _render_group_action_cursor_fields(state,frame,False)


def render_group_action_cursor_alternate_1_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    return _render_group_action_cursor_fields(state,frame,True)


def refresh_group_detach_cursor_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x15B76)
    frame=_group_route_call_fields(state,frame,0x12102,0x15B7A)
    return _group_route_call_fields(state,frame,0x15B08,0x15B7C)


def confirm_group_split_action_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x15B7E)
    frame=_group_route_call_fields(state,frame,0x12418,0x15B84)
    frame=_group_route_call_fields(state,frame,0x125AC,0x15B8A)
    frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF603,1),5)
    if not frame.status&4:
        frame=_group_route_store_fields(state,frame,0xFFFFF386,0,2,True)
        frame=_group_route_call_fields(state,frame,0xC0B6,0x15B9C)
        for address,value in ((0xFFFFF612,520),(0xFFFFF362,3),(0xFFFFF36A,18)):
            frame=_group_route_store_fields(state,frame,address,value)
        frame=_group_route_call_fields(state,frame,0x15BD0,0x15BB2)
    frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF603,1),4)
    if not frame.status&4:
        for address,value in ((0xFFFFF612,520),(0xFFFFF362,2),(0xFFFFF36A,18)):
            frame=_group_route_store_fields(state,frame,address,value)
        frame=_group_route_call_fields(state,frame,0x12292,0x15BD0)
    return frame


def prepare_group_detach_overlay_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x15C1A)
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF3D0,2),16)
    frame=first_replace(frame,roster=state.table_at(0xFFFFCC00).cursor())
    frame=_movement_move(state,frame,'target_y',0,16)
    frame=_movement_move(state,frame,'target_y',frame.roster.byte(low16(frame.target_x)),8)
    frame=first_replace(frame,roster=state.table_at(0xFFFFF428).cursor())
    frame=_movement_move(state,frame,'target_y',frame.roster.byte(low16(frame.target_y)),8)
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF602,2),16)
    frame=_group_route_bit_fields(state,frame,frame.target_x,5)
    if not frame.status&4:
        frame=_movement_move_long(state,frame,'target_x',0xC0000026)
        frame=_movement_move(state,frame,'target_y',7,16)
        frame=_movement_move(state,frame,'unit',0xCA02,16)
        frame=first_replace(frame,roster=state.table_at(0x15C62).cursor())
        frame=_group_route_call_fields(state,frame,0x26BFA,0x15C54)
        frame=_group_route_change_memory_bit_fields(state,frame,0xFFFFF3A4,6,False)
        frame=_group_route_store_fields(state,frame,0xFFFFF362,5)
    return frame


def fade_group_order_into_battle_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x15CC4)
    frame=_group_route_call_fields(state,frame,0x15D14,0x15CC8)
    if frame.status&1:
        return frame
    frame=_movement_compare(state,frame,state.read(0xFFFFF352,2),16,16)
    if frame.status&1:
        frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF352,2),16)
        frame=_movement_move(state,frame,'target_y',64,16)
        frame=first_replace(frame,roster=state.table_at(0xFFFFFB80).cursor())
        frame=_group_route_call_fields(state,frame,0xDEA6,0x15CE8)
        frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF320,2),16)
        frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&1,16)
        if frame.status&4:
            frame=_group_route_memory_delta_fields(state,frame,0xFFFFF352,1)
        return frame
    frame=_group_route_store_fields(state,frame,0xFFFFF356,state.read(0xFFFFF314,2))
    frame=_group_route_store_fields(state,frame,0xFFFFF354,state.read(0xFFFFF318,2))
    frame=_group_route_store_fields(state,frame,0xFFFFF612,0,2,True)
    return _group_route_store_fields(state,frame,0xFFFFF600,196)


def test_group_order_ally_confirmation_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x15D14)
    frame=_movement_test(state,frame,state.read(0xFFFFF352,2),16)
    if not frame.status&4:
        return _group_route_carry_fields(state,frame,False)
    frame=first_replace(frame,roster=state.table_at(state.read(0xFF382C,4)).cursor())
    frame=_movement_move(state,frame,'target_x',0,16)
    frame=_movement_move(state,frame,'target_x',frame.roster.byte(0,4),8)
    frame=_movement_compare(state,frame,low16(frame.target_x),state.read(0xFFFFF67C,2),16)
    if not frame.status&4:
        frame=_movement_compare(state,frame,low16(frame.target_x),state.read(0xFFFFF67E,2),16)
    if not frame.status&4:
        return _group_route_carry_fields(state,frame,False)
    frame=first_replace(frame,roster=state.table_at(u32(0xFFFFEFBE+s16(state.read(0xFFFFEFC6,2)))).cursor())
    frame=_movement_move(state,frame,'target_x',frame.roster.word(),16)
    frame=first_replace(frame,roster=state.table_at(0xFFFF9000).cursor())
    frame=_movement_move(state,frame,'target_y',0,16)
    frame=_movement_move(state,frame,'target_y',frame.roster.byte(low16(frame.target_x),4),8)
    frame=_movement_compare(state,frame,low16(frame.target_y),state.read(0xFFFFF67C,2),16)
    if not frame.status&4:
        frame=_movement_compare(state,frame,low16(frame.target_y),state.read(0xFFFFF67E,2),16)
    if not frame.status&4:
        return _group_route_carry_fields(state,frame,False)
    frame=_group_route_store_fields(state,frame,0xFFFFF362,15)
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF67E,2),16)
    frame=_movement_fixed_shift_word(state,frame,'target_x',1)
    frame=first_replace(frame,roster=state.table_at(0xFFFFE640).cursor())
    frame=_group_route_store_fields(state,frame,0xFFFFF3D0,frame.roster.word(low16(frame.target_x)))
    frame=_movement_move(state,frame,'target_x',192,16)
    frame=_group_route_call_fields(state,frame,0x676F2,0x15D7C)
    frame=_group_route_store_fields(state,frame,0xFFFFF376,65534)
    return _group_route_carry_fields(state,frame,True)


def accept_group_order_confirmation_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x15D90)
    frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF603,1),5)
    if not frame.status&4:
        frame=_group_route_store_fields(state,frame,0xFFFFF612,1024)
        frame=_group_route_store_fields(state,frame,0xFFFFF362,0,2,True)
    return frame


def show_group_order_ally_notice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x15DA6)
    frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF603,1),5)
    if frame.status&4:
        return frame
    frame=_group_route_memory_delta_fields(state,frame,0xFFFFF362,1)
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFF67C,2),16)
    frame=_movement_fixed_shift_word(state,frame,'target_x',1)
    frame=first_replace(frame,roster=state.table_at(0xFFFFE640).cursor())
    frame=_group_route_store_fields(state,frame,0xFFFFF3D0,frame.roster.word(low16(frame.target_x)))
    frame=_movement_move(state,frame,'target_x',193,16)
    return _group_route_call_fields(state,frame,0x676F2,0x15DCE)


def dismiss_group_order_ally_notice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x15DD0)
    frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF605,1),5)
    if not frame.status&4:
        frame=_group_route_store_fields(state,frame,0xFFFFF362,13)
        frame=_group_route_memory_delta_fields(state,frame,0xFFFFF352,1)
    return frame


def initialize_group_route_text_row_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """16152: six ordered glyph rows, fourteen blanks and the exact row stride."""
    frame=_resource_cost_frame(state,frame,0x16152)
    frame=first_replace(frame,roster=state.table_at(u32(0xFFFFD100+s16(state.read(0xFFFFF31A,2)))).cursor())
    for displacement in (160,128,96,64,32,0):
        frame=_group_route_store_fields(state,frame,frame.roster.address(0,displacement),14)
    frame=first_replace(frame,roster=frame.roster.advance(2))
    for displacement,value in ((160,0xC71E),(128,0xC69E),(96,0xC61E),(64,0xC59E),(32,0xC51E),(0,0xC49E)):
        frame=_group_route_store_fields(state,frame,frame.roster.address(0,displacement),value)
    frame=first_replace(frame,roster=frame.roster.advance(2))
    frame=_movement_move(state,frame,'target_x',13,16)
    while True:
        for displacement in (160,128,96,64,32,0):
            frame=_group_route_store_fields(state,frame,frame.roster.address(0,displacement),32768)
        frame=first_replace(frame,roster=frame.roster.advance(2))
        count=u16(low16(frame.target_x)-1)
        frame=first_replace(frame,target_x=replace_word(frame.target_x,count))
        if count==65535:
            break
    frame=_group_route_store_fields(state,frame,frame.roster.address(0,160),0,2,True)
    return _group_route_memory_delta_fields(state,frame,0xFFFFF31A,192)


"""Group option feasibility, queued object motion and cursor confirmation."""

def step_group_action_choice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Update countdown, then preserve the original shared secondary-button read."""
    frame = _resource_cost_frame(state, frame, 0x15A60)
    frame = _group_route_call_fields(state, frame, 0x15ACC, 0x15A64)
    frame = _group_route_call_fields(state, frame, 0x15AEA, 0x15A68)
    frame = _movement_test(state, frame, state.read(0xFFFFCFD2, 2), 16)
    check_secondary_button = True
    if not frame.status & 4:
        frame = _group_route_memory_delta_fields(state, frame, 0xFFFFCFD2, -1)
        frame = _movement_compare(state, frame, state.read(0xFFFFCFD2, 2), 8, 16)
        if not frame.status & 1 and not frame.status & 4:
            frame = _group_route_store_fields(state, frame, 0xFFFFCFD2, 8)
    else:
        frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF603, 1), 5)
        if not frame.status & 4:
            frame = _group_route_call_fields(state, frame, 0xC0B6, 0x15A96)
            for address, value in ((0xFFFFF612, 520), (0xFFFFF362, 3), (0xFFFFF36A, 18)):
                frame = _group_route_store_fields(state, frame, address, value)
            check_secondary_button = False
    if check_secondary_button:
        frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF603, 1), 4)
        if not frame.status & 4:
            for address, value in ((0xFFFFF612, 520), (0xFFFFF362, 2), (0xFFFFF36A, 18)):
                frame = _group_route_store_fields(state, frame, address, value)
    return _group_route_call_fields(state, frame, 0xA158, 0x15ACA)


def build_group_available_actions_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """163E0: split, foreign contact, allied city and terrain-five options."""
    frame=_resource_cost_frame(state,frame,0x163E0)
    frame=first_replace(frame,roster=state.table_at(0xFF3930).cursor())
    frame=_group_route_store_fields(state,frame,frame.roster.address(),0,1,True)
    frame=first_replace(frame,roster=frame.roster.advance(1),
        candidates=state.table_at(state.read(0xFF382C,4)).cursor())
    frame=_movement_compare(state,frame,state.read(0xFFFFF380,2),148,16)
    if frame.status&4:
        frame=first_replace(frame,candidates=state.table_at(state.read(0xFF3ECE,4)).cursor())
    frame=_movement_move(state,frame,'target_x',frame.candidates.byte(),8)
    frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&15,16)
    frame=_movement_compare(state,frame,low16(frame.target_x),2,16)
    if not frame.status&1:
        frame=_group_route_store_fields(state,frame,frame.roster.address(),1,1)
        frame=first_replace(frame,roster=frame.roster.advance(1))
    for target,token,option in ((0x16432,0x16412,2),(0x1649C,0x1641C,3),(0x16588,0x16426,4)):
        frame=_group_route_call_fields(state,frame,target,token)
        if frame.status&1:
            frame=_group_route_store_fields(state,frame,frame.roster.address(),option,1)
            frame=first_replace(frame,roster=frame.roster.advance(1))
    return _group_route_store_fields(state,frame,frame.roster.address(),255,1)


def test_group_adjacent_foreign_contact_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """16432: packed-coordinate four-neighbor contact scan and actual owner BYTE."""
    frame=_resource_cost_frame(state,frame,0x16432)
    frame=_movement_move(state,frame,'target_x',frame.candidates.byte(0,1),8)
    frame=_movement_fixed_shift_word(state,frame,'target_x',8)
    frame=_movement_move(state,frame,'target_x',frame.candidates.byte(0,2),8)
    frame=_movement_move(state,frame,'target_y',low16(frame.target_x),16)
    frame=_movement_move(state,frame,'unit',low16(frame.target_x),16)
    frame=_movement_move(state,frame,'count',low16(frame.target_x),16)
    frame=_group_route_register_delta_fields(state,frame,'target_x',-256)
    frame=_movement_add_word(state,frame,'target_y',1)
    frame=_movement_add_word(state,frame,'unit',256)
    frame=_group_route_register_delta_fields(state,frame,'count',-1)
    frame=_movement_move(state,frame,'distance',frame.candidates.byte(0,4),8)
    frame=first_replace(frame,controller=state.table_at(0xFFFF9000))
    while True:
        frame=_movement_test(state,frame,frame.controller.byte(),8)
        if frame.status&4:
            return _group_route_carry_fields(state,frame,False)
        frame=_first_compare_long(frame,frame.controller.base,frame.candidates.base)
        state.sr=(state.sr&65504)|frame.status
        if not frame.status&4:
            frame=_movement_move(state,frame,'offset_x',frame.controller.byte(0,1),8)
            frame=_movement_fixed_shift_word(state,frame,'offset_x',8)
            frame=_movement_move(state,frame,'offset_x',frame.controller.byte(0,2),8)
            matched=False
            for carrier in ('target_x','target_y','unit','count'):
                frame=_movement_compare(state,frame,low16(frame.carrier(carrier)),low16(frame.offset_x),16)
                if frame.status&4:
                    matched=True
                    break
            if matched:
                frame=_movement_compare(state,frame,low8(frame.distance),frame.controller.byte(0,4),8)
                if not frame.status&4:
                    return _group_route_carry_fields(state,frame,True)
        frame=_movement_move(state,frame,'offset_x',0,16)
        frame=_movement_move(state,frame,'offset_x',frame.controller.byte(),8)
        frame=_movement_move(state,frame,'offset_x',low16(frame.offset_x)&15,16)
        frame=first_replace(frame,controller=state.table_at(u32(frame.controller.base+13+s16(low16(frame.offset_x)))))


def test_group_friendly_city_action_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x1649C)
    frame=_group_route_call_fields(state,frame,0x164D4,0x164A0)
    frame=_movement_test(state,frame,low16(frame.target_x),16)
    if frame.status&8:
        return _group_route_carry_fields(state,frame,False)
    frame=_movement_compare(state,frame,low16(frame.target_x),16,16)
    if not frame.status&1:
        return _group_route_carry_fields(state,frame,False)
    frame=_movement_compare(state,frame,low8(frame.target_x),frame.candidates.byte(0,4),8)
    # Original164B2 skips only the allied-city activity check when owners
    # differ; both that branch and an active allied city reach164C2.
    if frame.status&4:
        frame=first_replace(frame,controller=state.table_at(0xFFFFEA38))
        frame=_movement_test(state,frame,frame.controller.byte(low16(frame.distance)),8)
        if frame.status&4:
            return _group_route_carry_fields(state,frame,False)
    frame=_movement_add_word(state,frame,'distance',1)
    frame=_group_route_store_fields(state,frame,0xFFFFF392,low16(frame.distance))
    return _group_route_carry_fields(state,frame,True)


