def begin_queued_object_route_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """16678: eligible object scan, month transition, unavailable-slot message or UI packet."""
    frame=_resource_cost_frame(state,frame,0x16678)
    frame=_group_route_call_fields(state,frame,0x662E4,0x1667E)
    if frame.status&1:
        frame=_group_route_store_fields(state,frame,0xFFFFF362,3)
        frame=_movement_move(state,frame,'target_x',156,16)
        return _group_route_call_fields(state,frame,0x676F2,0x16708)
    frame=_group_route_bit_fields(state,frame,state.read(0xFFFFF3A4,1),6)
    if not frame.status&4:
        frame=_movement_move_long(state,frame,'target_x',0xC0000026)
        frame=_movement_move(state,frame,'target_y',7,16)
        frame=_movement_move(state,frame,'unit',0xCA02,16)
        frame=first_replace(frame,roster=state.table_at(0x1672C).cursor())
        frame=_group_route_call_fields(state,frame,0x26BFA,0x16724)
        return _group_route_change_memory_bit_fields(state,frame,0xFFFFF3A4,6,False)
    frame=_movement_compare(state,frame,state.read(0xFFFFCEA0,2),40,16)
    if frame.status&1:
        frame=first_replace(frame,roster=state.table_at(0xFFFFCE00).cursor())
        while True:
            frame=_movement_move(state,frame,'target_x',state.read(0xFFFFCEA0,2),16)
            frame=_movement_fixed_shift_word(state,frame,'target_x',2)
            frame=_movement_test(state,frame,frame.roster.byte(low16(frame.target_x)),8)
            if not frame.status&4:
                return _group_route_store_fields(state,frame,0xFFFFF600,124)
            frame=_group_route_memory_delta_fields(state,frame,0xFFFFCEA0,1)
            frame=_movement_compare(state,frame,state.read(0xFFFFCEA0,2),40,16)
            if not frame.status&1:
                break
    for address,value in ((0xFFFFF36C,2),(0xFFFFF612,513),(0xFFFFF376,65534)):
        frame=_group_route_store_fields(state,frame,address,value)
    frame=_group_route_date_increment_fields(state,frame)
    frame=_group_route_store_fields(state,frame,0xFFFFF600,128)
    frame=_group_route_store_fields(state,frame,0xFFFFF380,133)
    return _group_route_call_fields(state,frame,0x5C98,0x166EA)


def position_queued_object_camera_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x16748)
    frame=_group_route_call_fields(state,frame,0x1264,0x1674E)
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFCEA0,2),16)
    frame=_movement_fixed_shift_word(state,frame,'target_x',2)
    frame=first_replace(frame,roster=state.table_at(0xFFFFCE00).cursor())
    frame=_movement_move(state,frame,'target_y',0,16)
    frame=_movement_move(state,frame,'target_y',frame.roster.byte(low16(frame.target_x),1),8)
    frame=_movement_fixed_shift_word(state,frame,'target_y',4)
    frame=_group_route_store_fields(state,frame,0xFFFFCEA4,low16(frame.target_y))
    frame=_group_route_store_fields(state,frame,0xFFFFCEA8,low16(frame.target_y))
    frame=_group_route_register_delta_fields(state,frame,'target_y',-112)
    if frame.status&1:
        frame=_movement_move(state,frame,'target_y',0,16)
    frame=_movement_move(state,frame,'unit',0,16)
    frame=_movement_move(state,frame,'unit',frame.roster.byte(low16(frame.target_x),2),8)
    frame=_movement_fixed_shift_word(state,frame,'unit',4)
    frame=_group_route_store_fields(state,frame,0xFFFFCEA6,low16(frame.unit))
    frame=_group_route_store_fields(state,frame,0xFFFFCEAA,low16(frame.unit))
    frame=_group_route_register_delta_fields(state,frame,'unit',-160)
    if frame.status&1:
        frame=_movement_move(state,frame,'unit',0,16)
    frame=_group_route_call_fields(state,frame,0x14D64,0x1678E)
    frame=_movement_test(state,frame,low16(frame.distance),16)
    if frame.status&4:
        frame=_group_route_memory_delta_fields(state,frame,0xFFFFF362,1)
    return frame


def step_queued_object_route_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """16798: actual record flags, arrival gates, sound, axis motion and camera."""
    frame=_resource_cost_frame(state,frame,0x16798)
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFCEA0,2),16)
    frame=_movement_fixed_shift_word(state,frame,'target_x',2)
    frame=first_replace(frame,auxiliary=state.table_at(u32(0xFFFFCE00+s16(low16(frame.target_x)))))
    address=frame.auxiliary.address()
    frame=_group_route_store_fields(state,frame,address,state.read(address,1)&131,1)
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFCEA4,2),16)
    frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&15,16)
    aligned=bool(frame.status&4)
    if aligned:
        frame=_movement_move(state,frame,'target_x',state.read(0xFFFFCEA6,2),16)
        frame=_movement_move(state,frame,'target_x',low16(frame.target_x)&15,16)
        aligned=bool(frame.status&4)
    if aligned:
        frame=_movement_move(state,frame,'target_x',state.read(0xFFFFCEA4,2),16)
        frame=_movement_fixed_shift_word(state,frame,'target_x',4,True)
        frame=_group_route_store_fields(state,frame,frame.auxiliary.address(0,1),low8(frame.target_x),1)
        frame=_movement_move(state,frame,'target_x',state.read(0xFFFFCEA6,2),16)
        frame=_movement_fixed_shift_word(state,frame,'target_x',4,True)
        frame=_group_route_store_fields(state,frame,frame.auxiliary.address(0,2),low8(frame.target_x),1)
        arrived=False
        for target,token in ((0x16874,0x167D4),(0x16922,0x167DC),(0x16946,0x167E4)):
            frame=_group_route_call_fields(state,frame,target,token)
            if frame.status&1:
                arrived=True
                break
        if arrived:
            frame=_group_route_memory_delta_fields(state,frame,0xFFFFCEA0,1)
            return _group_route_store_fields(state,frame,0xFFFFF362,0,2,True)
        frame=_movement_move(state,frame,'target_x',state.read(0xFFFFCEA4,2),16)
        frame=_movement_move(state,frame,'target_y',state.read(0xFFFFCEA6,2),16)
        frame=_group_route_call_fields(state,frame,0x14294,0x167F6)
        frame=_movement_compare(state,frame,low8(frame.unit),4,8)
        if not frame.status&4:
            frame=_movement_move(state,frame,'target_x',164,16)
            frame=_group_route_call_fields(state,frame,0x808A,0x16808)
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFCEA4,2),16)
    frame=_movement_compare(state,frame,low16(frame.target_x),state.read(0xFFFFCEA8,2),16)
    if not frame.status&4:
        frame=_group_route_memory_delta_fields(state,frame,0xFFFFCEA4,1 if frame.status&1 else -1)
    else:
        frame=_movement_move(state,frame,'target_x',state.read(0xFFFFCEA6,2),16)
        frame=_movement_compare(state,frame,low16(frame.target_x),state.read(0xFFFFCEAA,2),16)
        if not frame.status&1 and not frame.status&4:
            frame=_group_route_store_fields(state,frame,address,state.read(address,1)&127,1)
            frame=_group_route_memory_delta_fields(state,frame,0xFFFFCEA6,-1)
        else:
            frame=_group_route_memory_delta_fields(state,frame,0xFFFFCEA6,1)
            frame=_group_route_store_fields(state,frame,address,state.read(address,1)|128,1)
    frame=_movement_move(state,frame,'target_y',state.read(0xFFFFCEA4,2),16)
    frame=_group_route_register_delta_fields(state,frame,'target_y',-104)
    if frame.status&1:
        frame=_movement_move(state,frame,'target_y',0,16)
    frame=_movement_move(state,frame,'unit',state.read(0xFFFFCEA6,2),16)
    frame=_group_route_register_delta_fields(state,frame,'unit',-152)
    if frame.status&1:
        frame=_movement_move(state,frame,'unit',0,16)
    return _group_route_call_fields(state,frame,0x14D64,0x16872)


def debit_queued_object_route_budget_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x16922)
    frame=_movement_move(state,frame,'target_x',state.read(0xFFFFCEA8,2),16)
    frame=_movement_move(state,frame,'target_y',state.read(0xFFFFCEAA,2),16)
    frame=_group_route_call_fields(state,frame,0x14294,0x16930)
    frame=_movement_test(state,frame,low16(frame.count),16)
    if not frame.status&8:
        frame,result=_movement_binary_flags(state,frame,state.read(0xFFFFCEA2,2),low16(frame.count),16,True)
        state.write(0xFFFFCEA2,2,result)
        if not frame.status&1:
            return _group_route_carry_fields(state,frame,False)
    else:
        return _group_route_carry_fields(state,frame,False)
    return _group_route_carry_fields(state,frame,True)


def dismiss_queued_object_confirmation_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame=_resource_cost_frame(state,frame,0x16A98)
