def _city_menu_register_arithmetic_fields(state: SceneState, frame: FirstDeploymentFrame,
        carrier: str, operand: int, subtract: bool=False) -> FirstDeploymentFrame:
    frame, value = _movement_binary_flags(state, frame, low16(frame.carrier(carrier)), operand, 16, subtract)
    return first_replace(frame, **{carrier: replace_word(frame.carrier(carrier), value)})


def _city_menu_db_word_fields(frame: FirstDeploymentFrame, carrier: str) -> FirstDeploymentFrame:
    """DBRA changes only the retained low WORD, never CCR/X."""
    return first_replace(frame, **{carrier: replace_word(frame.carrier(carrier), u16(low16(frame.carrier(carrier)) - 1))})


def select_city_battle_available_member_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """18848: locate a non-bit14 candidate and retain the original viewport clamps.

    A missing eligible candidate has the original unbounded restart, not a host
    scan cap. Unsigned comparisons and WORD underflow are not repaired.
    """
    frame = _resource_cost_frame(state, frame, 0x18848)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF636, 2), 16)
    frame = _city_menu_register_arithmetic_fields(state, frame, 'target_x', state.read(0xFFFFF684, 2), True)
    frame = _movement_add_word(state, frame, 'target_x', state.read(0xFFFFF712, 2))
    frame = _movement_compare(state, frame, low16(frame.target_x), 10, 16)
    if frame.status & 5:
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF636, 2), 16)
    else:
        frame = first_replace(frame, roster=state.table_at(0xFFFFAF56).cursor())
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF378, 2), 16)
        while True:
            frame = _movement_compare(state, frame, low16(frame.target_x), state.read(0xFFFFF636, 2), 16)
            if not frame.status & 1:
                frame = _movement_move(state, frame, 'target_x', 0, 16)
            frame = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)
            frame = _movement_fixed_shift_word(state, frame, 'unit', 1)
            frame = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.unit)), 16)
            frame = _deployment_menu_bit(state, frame, frame.target_y, 14)
            if frame.status & 4:
                break
            frame = _group_route_register_delta_fields(state, frame, 'target_x', 1)
    frame = _group_route_store_fields(state, frame, 0xFFFFF378, low16(frame.target_x))
    frame = _group_route_register_delta_fields(state, frame, 'target_x', -2)
    if frame.status & 1:
        frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF636, 2), 16)
    frame = _group_route_register_delta_fields(state, frame, 'target_y', -4)
    frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.target_y), 16)
    if not frame.status & 5:
        frame = _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)
    return _group_route_store_fields(state, frame, 0xFFFFF658, low16(frame.target_x))


def build_city_owner_selection_roster_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """18F66: reverse owner scan, real affiliation-to-leader map, sentinel WORD list."""
    frame = _resource_cost_frame(state, frame, 0x18F66)
    frame = first_replace(frame, roster=state.table_at(0xFFFFA150).cursor(), candidates=state.table_at(0xFFFFA550).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF68A, 2), 16)
    frame = _movement_move(state, frame, 'unit', 255, 16)
    while True:
        frame = first_replace(frame, roster=frame.roster.advance(-1))
        frame = _movement_move(state, frame, 'count', frame.roster.byte(), 8)
        frame = _movement_compare(state, frame, low8(frame.count), low8(frame.target_x), 8)
        if frame.status & 4:
            break
        frame = _city_menu_db_word_fields(frame, 'unit')
        if low16(frame.unit) == 65535:
            break
    frame = first_replace(frame, controller=state.table_at(0xFFFFCC00))
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'target_y', frame.controller.byte(low16(frame.unit)), 8)
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 63, 16)
    frame = _movement_compare(state, frame, low16(frame.target_y), 40, 16)
    if not frame.status & 5:
        frame = _city_menu_register_arithmetic_fields(state, frame, 'target_y', 41, True)
        frame = _movement_move(state, frame, 'distance', low16(frame.target_y), 16)
    else:
        frame = first_replace(frame, controller=state.table_at(0xFFFFF427))
        frame = _movement_move(state, frame, 'distance', 0, 16)
        frame = _movement_move(state, frame, 'distance', frame.controller.byte(low16(frame.target_y)), 8)
    frame = _group_route_store_fields(state, frame, 0xFFFFF68C, low16(frame.distance))
    frame = _movement_fixed_shift_word(state, frame, 'distance', 1)
    frame = first_replace(frame, controller=state.table_at(0xFFFFE640))
    frame = _movement_move(state, frame, 'distance', frame.controller.word(low16(frame.distance)), 16)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = first_replace(frame, controller=state.table_at(0xFFFFA050))
    frame = _movement_compare(state, frame, low8(frame.target_x), frame.controller.byte(low16(frame.distance)), 8)
    if frame.status & 4:
        frame = _city_menu_append_selection_word_fields(state, frame, low16(frame.distance))
    frame = _movement_compare(state, frame, low16(frame.unit), low16(frame.distance), 16)
    if not frame.status & 4:
        frame = _city_menu_append_selection_word_fields(state, frame, low16(frame.unit))
    frame = _group_route_register_delta_fields(state, frame, 'unit', -1)
    if not frame.status & 1:
        while True:
            frame = first_replace(frame, roster=frame.roster.advance(-1))
            frame = _movement_move(state, frame, 'count', frame.roster.byte(), 8)
            frame = _movement_compare(state, frame, low8(frame.count), low8(frame.target_x), 8)
            if frame.status & 4:
                frame = _movement_compare(state, frame, low16(frame.unit), low16(frame.distance), 16)
                if not frame.status & 4:
                    frame = _city_menu_append_selection_word_fields(state, frame, low16(frame.unit))
            frame = _city_menu_db_word_fields(frame, 'unit')
            if low16(frame.unit) == 65535:
                break
    frame = _group_route_store_fields(state, frame, frame.candidates.address(), 65535)
    return _group_route_store_fields(state, frame, 0xFFFFF6A6, low16(frame.target_y))


def _city_menu_append_selection_word_fields(state: SceneState, frame: FirstDeploymentFrame,
        member: int) -> FirstDeploymentFrame:
    frame = _group_route_store_fields(state, frame, frame.candidates.address(), member)
    frame = first_replace(frame, candidates=frame.candidates.advance(2))
    return _group_route_register_delta_fields(state, frame, 'target_y', 1)


def build_city_selection_tile_rows_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """191D0:8 counted six-tile rows and an actual terminating WORD."""
    frame = _resource_cost_frame(state, frame, 0x191D0)
    frame = first_replace(frame, roster=state.table_at(u32(0xFFFFD100 + s16(state.read(0xFFFFF31A, 2)))).cursor())
    frame = _movement_move(state, frame, 'target_x', 7, 16)
    frame = _movement_move(state, frame, 'target_y', 0xC33A, 16)
    frame = _movement_move(state, frame, 'count', 0x8005, 16)
    while True:
        frame = _city_menu_append_packet_word_fields(state, frame, 6)
        frame = _city_menu_append_packet_word_fields(state, frame, low16(frame.target_y))
        frame = _movement_add_word(state, frame, 'target_y', 128)
        frame = _movement_move(state, frame, 'unit', 5, 16)
        while True:
            frame = _city_menu_append_packet_word_fields(state, frame, low16(frame.count))
            frame = _group_route_register_delta_fields(state, frame, 'count', 1)
            frame = _city_menu_db_word_fields(frame, 'unit')
            if low16(frame.unit) == 65535:
                break
        frame = _city_menu_db_word_fields(frame, 'target_x')
        if low16(frame.target_x) == 65535:
            break
    frame = _group_route_store_fields(state, frame, frame.roster.address(), 0, 2, True)
    frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF31A, 128)
    return _group_route_change_memory_bit_fields(state, frame, 0xFFFFF3A5, 2, True)


def _city_menu_append_packet_word_fields(state: SceneState, frame: FirstDeploymentFrame,
        value: int) -> FirstDeploymentFrame:
    frame = _group_route_store_fields(state, frame, frame.roster.address(), value)
    return first_replace(frame, roster=frame.roster.advance(2))


"""City selection windows, roster phase transitions and physical display boundaries."""

def _city_menu_indexed_call_fields(state: SceneState, frame: FirstDeploymentFrame,
        table: int, base: int, continuation: int) -> FirstDeploymentFrame:
    """Four original WORD displacement tables; no invented dispatch vocabulary."""
    if (table, base, continuation) not in ((0x18D0A, 0x18D34, 0x18CE4),
            (0x18D6A, 0x18D72, 0x18D4A), (0x190C2, 0x190C6, 0x190BA),
            (0x192BA, 0x192C0, 0x192B2)):
        raise ValueError('original city phase table required')
    displacement = state.read(u32(table + s16(low16(frame.target_x))), 2)
    frame = _movement_move(state, frame, 'target_x', displacement, 16)
    return _group_route_call_fields(state, frame, u32(base + s16(displacement)), continuation)


def _city_menu_device_write_fields(state: SceneState, frame: FirstDeploymentFrame, instruction: int, port: int, width: int, value: int) -> FirstDeploymentFrame:
    """The actual VDP write is not a RAM store or a fabricated device completion."""
    if (instruction, port, width) not in ((101576, 12582916, 2), (103104, 12582916, 4), (103114, 12582912, 4), (103128, 12582912, 4), (103142, 12582912, 4), (103152, 12582912, 2), (103160, 12582916, 4), (103170, 12582912, 4), (103184, 12582912, 4), (103198, 12582912, 4)):
        raise ValueError('original city-menu VDP MOVE instruction, port and width required')
    frame = _resource_cost_frame(state, frame, instruction)
    return _group_route_store_fields(state, frame, port, value, width)


def dispatch_city_video_selection_phase_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """18CB4: real input services, VDP mode WORD, indexed city phase and map refresh."""
    frame = _resource_cost_frame(state, frame, 0x18CB4)
    frame = _group_route_call_fields(state, frame, 0x4890, 0x18CBA)
    frame = _group_route_call_fields(state, frame, 0x4998, 0x18CC0)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF606, 2), 16)
    frame = _movement_move(state, frame, 'target_x', low8(frame.target_x) | 64, 8)
    frame = _city_menu_device_write_fields(state, frame, 0x18CC8, 0xC00004, 2, low16(frame.target_x))
    frame = _group_route_call_fields(state, frame, 0x1A16E, 0x18CD2)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF612, 2), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _city_menu_indexed_call_fields(state, frame, 0x18D0A, 0x18D34, 0x18CE4)
    frame = _group_route_call_fields(state, frame, 0x1B0C2, 0x18CEA)
    frame = _movement_compare(state, frame, state.read(0xFFFFF6C4, 2), 1, 16)
    if frame.status & 4:
        frame = _movement_compare(state, frame, state.read(0xFFFFF612, 2), 0x400, 16)
        if not frame.status & 4:
            frame = _group_route_call_fields(state, frame, 0x1A2B8, 0x18D02)
        frame = _group_route_call_fields(state, frame, 0x1A200, 0x18D08)
    return frame


def dispatch_city_pending_selection_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """18D34: pending phase dispatch or the three real idle refresh children."""
    frame = _resource_cost_frame(state, frame, 0x18D34)
    frame = _group_route_call_fields(state, frame, 0x1A00E, 0x18D38)
    if not frame.status & 1:
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF362, 2), 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
        return _city_menu_indexed_call_fields(state, frame, 0x18D6A, 0x18D72, 0x18D4A)
    frame = _movement_test(state, frame, state.read(0xFFFFF6C4, 2), 16)
    if not frame.status & 4:
        return frame
    frame = _group_route_call_fields(state, frame, 0x15DE6, 0x18D5C)
    frame = _group_route_call_fields(state, frame, 0x169AA, 0x18D62)
    return _group_route_call_fields(state, frame, 0x679FC, 0x18D68)


def step_city_selection_fade_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """18D72: fade-out, middle commit, fade-in and the actual day/menu handoff.

    Palette math belongs to DEA6's one core. Timer and button bits are read
    only at their original phase, and the two day-call slots remain distinct.
    """
    frame = _resource_cost_frame(state, frame, 0x18D72)
    frame = _group_route_call_fields(state, frame, 0x1A0A2, 0x18D76)
    if frame.status & 1:
        return frame
    frame = _movement_compare(state, frame, state.read(0xFFFFF352, 2), 16, 16)
    if frame.status & 1:
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF352, 2), 16)
        frame = _movement_move(state, frame, 'target_y', 64, 16)
        frame = first_replace(frame, roster=state.table_at(0xFFFFFB80).cursor())
        frame = _group_route_call_fields(state, frame, 0xDEA6, 0x18D94)
        frame = _movement_test(state, frame, state.read(0xFFFFF77A, 2), 16)
        if not frame.status & 4:
            frame = _group_route_call_fields(state, frame, 0x23F6, 0x18DA2)
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF320, 2), 16)
        frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 1, 16)
        if not frame.status & 4:
            return frame
        frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF352, 1)
        frame = _movement_test(state, frame, state.read(0xFFFFF6C4, 2), 16)
        if not frame.status & 4:
            return frame
        frame = _group_route_call_fields(state, frame, 0x15DE6, 0x18DC0)
        frame = _group_route_call_fields(state, frame, 0x169AA, 0x18DC6)
        return _group_route_call_fields(state, frame, 0x679FC, 0x18DCC)
    if frame.status & 4:
        frame = _group_route_store_fields(state, frame, 0xFFFFF600, 0x84)
        frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF352, 1)
        return _group_route_store_fields(state, frame, 0xFFFFF77A, 0, 2, True)
    frame = _group_route_call_fields(state, frame, 0x1A2B8, 0x18DEA)
    frame = _group_route_call_fields(state, frame, 0xA3DA, 0x18DF0)
    frame = _movement_move(state, frame, 'target_x', 31, 16)
    frame = _city_menu_register_arithmetic_fields(state, frame, 'target_x', state.read(0xFFFFF352, 2), True)
    frame = _movement_move(state, frame, 'target_y', 64, 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFFB80).cursor())
    frame = _group_route_call_fields(state, frame, 0xDEA6, 0x18E06)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF320, 2), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 1, 16)
    if not frame.status & 4:
        return frame
    frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF352, 1)
    frame = _movement_compare(state, frame, state.read(0xFFFFF352, 2), 32, 16)
    if frame.status & 1:
        return frame
    frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF3A5, 1), 0)
    if not frame.status & 4:
        frame = _movement_compare(state, frame, state.read(0xFFFFF6D2, 2), 4, 16)
        if frame.status & 4:
            frame = _group_route_store_fields(state, frame, 0xFFFFF612, 0x412)
            frame = _group_route_store_fields(state, frame, 0xFFFFF362, 0, 2, True)
            frame = _group_route_change_memory_bit_fields(state, frame, 0xFFFFF3A5, 0, False)
        else:
            frame = _group_route_store_fields(state, frame, 0xFFFFF612, 0x405)
            frame = _group_route_store_fields(state, frame, 0xFFFFF362, 0, 2, True)
            frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFAF80, 2), 16)
            frame = _group_route_call_fields(state, frame, 0x676F2, 0x18E58)
            frame = _group_route_change_memory_bit_fields(state, frame, 0xFFFFF3A5, 0, False)
        return _group_route_call_fields(state, frame, 0x1A25E, 0x18E78)
    frame = _movement_test(state, frame, state.read(0xFFFFF772, 2), 16)
    if frame.status & 4:
        frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF362, 1)
        return _group_route_call_fields(state, frame, 0x1A25E, 0x18E78)
    frame = _group_route_call_fields(state, frame, 0x1A25E, 0x18E82)
    frame = _group_route_store_fields(state, frame, 0xFFFFF3A4, 0, 2, True)
    frame = _movement_compare(state, frame, state.read(0xFFFFF772, 2), 2, 16)
    selected_second_side = bool(frame.status & 4)
    frame = _group_route_store_fields(state, frame, 0xFFFFF612, 0x408 if selected_second_side else 0x410)
    frame = _group_route_store_fields(state, frame, 0xFFFFF362, 0, 2, True)
    if selected_second_side:
        frame = _group_route_call_fields(state, frame, 0x20088, 0x18EAE)
    return frame


def initialize_city_owner_selection_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """18EB0: four actual roster preparation children and side-visibility state."""
    frame = _resource_cost_frame(state, frame, 0x18EB0)
    frame = _group_route_call_fields(state, frame, 0x18F18, 0x18EB4)
    frame = _group_route_call_fields(state, frame, 0x18F66, 0x18EB8)
    frame = _group_route_call_fields(state, frame, 0x18FFC, 0x18EBC)
    frame = _group_route_call_fields(state, frame, 0x19018, 0x18EC0)
    frame = _group_route_store_fields(state, frame, 0xFFFFA5F8, 65535)
    frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF612, 1)
    frame = _group_route_store_fields(state, frame, 0xFFFFF362, 0, 2, True)
    frame = _group_route_store_fields(state, frame, 0xFFFFF38A, 0x402)
    frame = first_replace(frame, roster=state.table_at(0xAB8C4).cursor())
    frame = _group_route_store_fields(state, frame, 0xFFFFF6C0, frame.roster.address(), 4)
    frame = _group_route_store_fields(state, frame, 0xFFFFF6D6, 2)
    frame = _group_route_store_fields(state, frame, 0xFFFFF36A, 0, 2, True)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF68E, 2), 16)
    for owner_address in (0xFFFFF67A, 0xFFFFF67C, 0xFFFFF67E):
        frame = _movement_compare(state, frame, low16(frame.target_x), state.read(owner_address, 2), 16)
        if frame.status & 4:
            break
    else:
        frame = _group_route_store_fields(state, frame, 0xFFFFF600, 0xB8)
    frame = _group_route_call_fields(state, frame, 0x1A2B8, 0x18F10)
    return _group_route_call_fields(state, frame, 0xA3DA, 0x18F16)


def toggle_city_owner_selection_side_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x19034)
    frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF603, 1), 5)
    if not frame.status & 4:
        frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF362, 1)
        side = state.read(0xFFFFF6D7, 1)
        frame = _group_route_bit_fields(state, frame, side, 1)
        state.write(0xFFFFF6D7, 1, side ^ 2)
        frame = _movement_move(state, frame, 'target_x', 0xC1, 16)
        frame = _group_route_call_fields(state, frame, 0x676F2, 0x19052)
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF67C, 2), 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
        frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
        frame = _group_route_store_fields(state, frame, 0xFFFFF3D0, frame.roster.word(low16(frame.target_x)))
        frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF6D7, 1), 1)
        destination = 0xFFFFF68C if frame.status & 4 else 0xFFFFF68E
        frame = _group_route_store_fields(state, frame, destination, state.read(0xFFFFF67C, 2))
    return _group_route_call_fields(state, frame, 0x679FC, 0x19082)


def confirm_city_owner_selection_side_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x19084)
    frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF603, 1), 5)
    if not frame.status & 4:
        frame = _group_route_store_fields(state, frame, 0xFFFFF362, 0, 2, True)
        frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF352, 1)
    return _group_route_call_fields(state, frame, 0x679FC, 0x1909C)


def refresh_city_engagement_selection_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x1909E)
    frame = _group_route_call_fields(state, frame, 0x1E660, 0x190A4)
    return _group_route_call_fields(state, frame, 0xA3DA, 0x190AA)


def dispatch_city_selection_window_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x190AC)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF362, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _city_menu_indexed_call_fields(state, frame, 0x190C2, 0x190C6, 0x190BA)
    return _group_route_call_fields(state, frame, 0xA3DA, 0x190C0)


def step_city_selection_window_open_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x190C6)
    frame = _movement_compare(state, frame, state.read(0xFFFFF36A, 2), 10, 16)
    if frame.status & 1:
        frame = _group_route_call_fields(state, frame, 0x190EE, 0x190D2)
        return _group_route_memory_delta_fields(state, frame, 0xFFFFF36A, 1)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF602, 2), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 0x70, 16)
    if not frame.status & 4:
        frame = _group_route_store_fields(state, frame, 0xFFFFF36A, 0, 2, True)
        frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF362, 1)
    return frame


def append_city_selection_open_row_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x190EE)
    frame = first_replace(frame, roster=state.table_at(state.read(0xFFFFF6C0, 4)).cursor())
    frame = _movement_move_long(state, frame, 'target_x', 0xC0000019)
    frame = _movement_move(state, frame, 'target_y', 2, 16)
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF36A, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'unit', 8)
    frame = _movement_add_word(state, frame, 'unit', 0xC08E)
    frame = _group_route_store_fields(state, frame, 0xFFFFF692, 0xC386)
    frame = _group_route_store_fields(state, frame, 0xFFFFF694, 0xC401)
    frame = _group_route_call_fields(state, frame, 0x26BFA, 0x19118)
    return _group_route_store_fields(state, frame, 0xFFFFF6C0, frame.roster.address(), 4)


def step_city_selection_window_close_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x1911E)
    frame = _group_route_call_fields(state, frame, 0x1913E, 0x19122)
    frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF36A, 1)
    frame = _movement_compare(state, frame, state.read(0xFFFFF36A, 2), 10, 16)
    if not frame.status & 1:
        frame = _group_route_store_fields(state, frame, 0xFFFFF612, state.read(0xFFFFF38A, 2))
        frame = _group_route_store_fields(state, frame, 0xFFFFF362, state.read(0xFFFFF3B0, 2))
    return frame


def append_city_selection_close_row_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x1913E)
    frame = first_replace(frame, roster=state.table_at(0xABA0E).cursor())
    frame = _movement_move_long(state, frame, 'target_x', 0xC0000019)
    frame = _movement_move(state, frame, 'target_y', 2, 16)
    frame = _movement_move(state, frame, 'count', state.read(0xFFFFF36A, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'count', 8)
    frame = _movement_move(state, frame, 'unit', 0xC98E, 16)
    frame = _city_menu_register_arithmetic_fields(state, frame, 'unit', low16(frame.count), True)
    return _group_route_call_fields(state, frame, 0x26BFA, 0x19160)


def refresh_city_selection_overlay_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x19162)
    frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF3A4, 1), 6)
    if frame.status & 4:
        frame = _group_route_call_fields(state, frame, 0x674CA, 0x19170)
    else:
        frame = _movement_test(state, frame, state.read(0xFFFFF652, 2), 16)
        if not frame.status & 4:
            frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF3A5, 1), 2)
            if frame.status & 4:
                frame = _group_route_call_fields(state, frame, 0x191D0, 0x1918A)
                frame = _group_route_store_fields(state, frame, 0xFFFFF3A6, state.read(0xFFFFF3D0, 2))
                frame = _group_route_store_fields(state, frame, 0xFFFFF600, 0x64)
                return _group_route_call_fields(state, frame, 0xA3DA, 0x191CE)
        else:
            frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF3A5, 1), 2)
            if not frame.status & 4:
                frame = _group_route_call_fields(state, frame, 0x1920E, 0x191A8)
                return _group_route_call_fields(state, frame, 0xA3DA, 0x191CE)
        frame = _group_route_call_fields(state, frame, 0x671B6, 0x191B2)
        frame = _movement_compare(state, frame, state.read(0xFFFFF3C2, 2), 0x411, 16)
        if frame.status & 4:
            frame = _movement_compare(state, frame, state.read(0xFFFFF3C4, 2), 3, 16)
            if frame.status & 4:
                frame = _group_route_call_fields(state, frame, 0x194FA, 0x191C8)
    return _group_route_call_fields(state, frame, 0xA3DA, 0x191CE)


def step_city_selection_overlay_close_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x1924A)
    frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF3A5, 1), 2)
    if not frame.status & 4:
        frame = _group_route_call_fields(state, frame, 0x1920E, 0x19256)
    else:
        frame = _movement_compare(state, frame, state.read(0xFFFFF36A, 2), 4, 16)
        if not frame.status & 1:
            frame = _group_route_store_fields(state, frame, 0xFFFFF612, state.read(0xFFFFF3C2, 2))
            frame = _group_route_store_fields(state, frame, 0xFFFFF362, state.read(0xFFFFF3C4, 2))
            frame = _group_route_change_memory_bit_fields(state, frame, 0xFFFFF3A4, 6, False)
        else:
            frame = first_replace(frame, roster=state.table_at(0xABA16).cursor())
            frame = _movement_move_long(state, frame, 'target_x', 0xC0000026)
            frame = _movement_move(state, frame, 'target_y', 2, 16)
            frame = _movement_move(state, frame, 'count', state.read(0xFFFFF36A, 2), 16)
            frame = _movement_fixed_shift_word(state, frame, 'count', 8)
            frame = _movement_move(state, frame, 'unit', 0xCD02, 16)
            frame = _city_menu_register_arithmetic_fields(state, frame, 'unit', low16(frame.count), True)
            frame = _group_route_call_fields(state, frame, 0x26BFA, 0x19298)
            frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF36A, 1)
    return _group_route_call_fields(state, frame, 0xA3DA, 0x192A2)


def dispatch_city_selection_header_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x192A4)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF362, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _city_menu_indexed_call_fields(state, frame, 0x192BA, 0x192C0, 0x192B2)
    return _group_route_call_fields(state, frame, 0xA3DA, 0x192B8)


def initialize_city_selection_header_video_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """192C0: both complete four-repeat VDP header streams, then state commit.

    All later source exists despite the honest first actual VDP-write boundary.
    Neither device stream is reinterpreted as ordinary Scene RAM.
    """
    frame = _resource_cost_frame(state, frame, 0x192C0)
    frame = _city_menu_device_write_fields(state, frame, 0x192C0, 0xC00004, 4, 0x40B40003)
    frame = _city_menu_device_write_fields(state, frame, 0x192CA, 0xC00000, 4, 0xC000C380)
    frame = _movement_move(state, frame, 'target_x', 3, 16)
    while True:
        frame = _city_menu_device_write_fields(state, frame, 0x192D8, 0xC00000, 4, 0xC381C381)
        frame = _city_menu_db_word_fields(frame, 'target_x')
        if low16(frame.target_x) == 65535:
            break
    frame = _city_menu_device_write_fields(state, frame, 0x192E6, 0xC00000, 4, 0xCB80C000)
    frame = _city_menu_device_write_fields(state, frame, 0x192F0, 0xC00000, 2, 0xC000)
    frame = _city_menu_device_write_fields(state, frame, 0x192F8, 0xC00004, 4, 0x41340003)
    frame = _city_menu_device_write_fields(state, frame, 0x19302, 0xC00000, 4, 0xC000C382)
    frame = _movement_move(state, frame, 'target_x', 3, 16)
    while True:
        frame = _city_menu_device_write_fields(state, frame, 0x19310, 0xC00000, 4, 0xC001C001)
        frame = _city_menu_db_word_fields(frame, 'target_x')
        if low16(frame.target_x) == 65535:
            break
    frame = _city_menu_device_write_fields(state, frame, 0x1931E, 0xC00000, 4, 0xCB82C000)
    frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF362, 1)
    frame = _group_route_store_fields(state, frame, 0xFFFFF600, 0x40)
    frame = _group_route_store_fields(state, frame, 0xFFFFF36A, 0, 2, True)
    return _group_route_store_fields(state, frame, 0xFFFFF656, 0, 2, True)


def reset_city_selection_repeat_counter_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x1933C)
    frame = _movement_test(state, frame, state.read(0xFFFFF600, 2), 16)
    if frame.status & 4:
        frame = _group_route_call_fields(state, frame, 0x5F7C, 0x1934A)
        frame = _group_route_store_fields(state, frame, 0xFFFFCFD2, 8)
    return frame


def process_city_member_selection_buttons_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """19352: countdown and three button paths share the real secondary-button tail."""
    frame = _resource_cost_frame(state, frame, 0x19352)
    frame = _group_route_call_fields(state, frame, 0x19460, 0x19356)
    frame = _group_route_call_fields(state, frame, 0x194DA, 0x1935A)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF500).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF378, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)
    frame = _group_route_store_fields(state, frame, 0xFFFFA5F8, low16(frame.target_x))
    frame = _group_route_store_fields(state, frame, 0xFFFFA5FA, 65535)
    frame = _movement_test(state, frame, state.read(0xFFFFCFD2, 2), 16)
    if not frame.status & 4:
        frame = _group_route_memory_delta_fields(state, frame, 0xFFFFCFD2, -1)
        frame = _movement_compare(state, frame, state.read(0xFFFFCFD2, 2), 8, 16)
        if not frame.status & 5:
            frame = _group_route_store_fields(state, frame, 0xFFFFCFD2, 8)
    else:
        frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF603, 1), 5)
        if not frame.status & 4:
            frame = _movement_move(state, frame, 'target_x', 0xAC, 16)
            frame = _group_route_call_fields(state, frame, 0x808A, 0x193A8)
            frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF378, 2), 16)
            frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
            frame = first_replace(frame, roster=state.table_at(0xFFFFF500).cursor())
            frame = _movement_compare(state, frame, frame.roster.word(low16(frame.target_x)), 0x4000, 16)
            if not frame.status & 1:
                return frame
            frame = _movement_compare(state, frame, state.read(0xFFFFF6D2, 2), 3, 16)
            if frame.status & 4:
                frame = _group_route_store_fields(state, frame, 0xFFFFF3A6, frame.roster.word(low16(frame.target_x)))
                frame = _group_route_store_fields(state, frame, 0xFFFFF36A, 0, 2, True)
                return _group_route_store_fields(state, frame, 0xFFFFF612, 0x406)
            frame = _group_route_store_fields(state, frame, 0xFFFFF612, state.read(0xFFFFF38A, 2))
            return _group_route_store_fields(state, frame, 0xFFFFF362, state.read(0xFFFFF3B0, 2))
    frame = _movement_compare(state, frame, state.read(0xFFFFF6D2, 2), 2, 16)
    if frame.status & 4:
        frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF603, 1), 4)
        if not frame.status & 4:
            return _group_route_call_fields(state, frame, 0x19582, 0x19400)
    else:
        frame = _movement_compare(state, frame, state.read(0xFFFFF6D2, 2), 3, 16)
        if frame.status & 4:
            frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF603, 1), 4)
            if not frame.status & 4:
                frame = _group_route_store_fields(state, frame, 0xFFFFF36A, 0, 2, True)
                frame = _group_route_store_fields(state, frame, 0xFFFFF612, 0x406)
                return _group_route_store_fields(state, frame, 0xFFFFF6D2, 4)
    frame = _group_route_bit_fields(state, frame, state.read(0xFFFFF603, 1), 6)
    if not frame.status & 4:
        frame = _group_route_store_fields(state, frame, 0xFFFFF612, 0x207)
        frame = _group_route_store_fields(state, frame, 0xFFFFF362, 0, 2, True)
        frame = _group_route_store_fields(state, frame, 0xFFFFF352, 0, 2, True)
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF378, 2), 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
        frame = first_replace(frame, roster=state.table_at(0xFFFFF500).cursor())
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
        frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)
        frame = _group_route_store_fields(state, frame, 0xFFFFF372, low16(frame.target_x))
        frame = _group_route_memory_delta_fields(state, frame, 0xFFFFF378, 1)
    return frame


"""Packed group result notifications, surviving-member selection and aftermath."""

def begin_city_group_result_notice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _resource_cost_frame(state, frame, 0x1CCBE)
    frame = first_replace(frame, roster=state.table_at(state.read(0x00FF382C, 4)).cursor())
    return _group_route_call_fields(state, frame, 0x1CCCA, 0x1CCC8)


def append_city_group_result_notice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1CCCA: six actual notification BYTEs and the original terminator overlap."""
    frame = _resource_cost_frame(state, frame, 0x1CCCA)
    frame = first_replace(frame, candidates=state.table_at(u32(0x00FF3000 + s16(state.read(0x00FF3826, 2)))).cursor())
    frame = _city_result_append_notice_byte_fields(state, frame, 0, True)
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(13), 8)
    frame = _city_result_append_notice_byte_fields(state, frame, low8(frame.target_x))
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(3), 8)
    frame = _city_result_append_notice_byte_fields(state, frame, low8(frame.target_x))
    frame = _city_result_append_notice_byte_fields(state, frame, 0x90)
    frame = _city_result_append_notice_byte_fields(state, frame, 0x32)
    frame = _city_result_append_notice_byte_fields(state, frame, 0, True)
    frame = _group_route_store_fields(state, frame, frame.candidates.address(), 255, 1)
    frame = _group_route_memory_delta_fields(state, frame, 0x00FF3826, 6)
    return _group_route_change_memory_bit_fields(state, frame, frame.roster.address(), 4, True)


def _city_result_append_notice_byte_fields(state: SceneState, frame: FirstDeploymentFrame,
        value: int, clear: bool=False) -> FirstDeploymentFrame:
    frame = _group_route_store_fields(state, frame, frame.candidates.address(), value, 1, clear)
    return first_replace(frame, candidates=frame.candidates.advance(1))


def _city_result_owner_match_fields(state: SceneState, frame: FirstDeploymentFrame,
        owner_addresses: tuple[int, int, int]) -> tuple[FirstDeploymentFrame, bool]:
    """The odd-address BYTE / even-address WORD comparisons stop at equality."""
    if owner_addresses not in ((0xFFFFF67B, 0xFFFFF67D, 0xFFFFF67F),
            (0xFFFFF67A, 0xFFFFF67C, 0xFFFFF67E)):
        raise ValueError('original packed-result owner BYTEs required')
    width = 1 if owner_addresses[0] == 0xFFFFF67B else 2
    for address in owner_addresses:
        value = low8(frame.target_x) if width == 1 else low16(frame.target_x)
        frame = _movement_compare(state, frame, value, state.read(address, width), width * 8)
        if frame.status & 4:
            return frame, True
    return frame, False


def prepare_city_group_result_queue_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1CD00: classify the completed group, then locate the first nonnegative queue slot."""
    frame = _resource_cost_frame(state, frame, 0x1CD00)
    frame = _group_route_call_fields(state, frame, 0x1CEA0, 0x1CD04)
    frame = _movement_compare(state, frame, low16(frame.target_x), 1, 16)
    reset_window = bool(frame.status & 4)
    if not reset_window:
        frame = first_replace(frame, roster=state.table_at(state.read(0x00FF382C, 4)).cursor())
        frame = _movement_move(state, frame, 'target_x', 0, 16)
        frame = _movement_move(state, frame, 'target_x', frame.roster.byte(4), 8)
        frame = _group_route_store_fields(state, frame, 0xFFFFF376, low16(frame.target_x))
        frame, owner_visible = _city_result_owner_match_fields(state, frame,
            (0xFFFFF67B, 0xFFFFF67D, 0xFFFFF67F))
        if owner_visible:
            frame = _group_route_store_fields(state, frame, 0xFFFFF612, 0x20D)
            frame = _group_route_store_fields(state, frame, 0xFFFFF362, 0, 2, True)
            frame = _movement_move(state, frame, 'target_x', 0x75, 16)
            frame = _group_route_call_fields(state, frame, 0x676F2, 0x1CD48)
        else:
            reset_window = True
    if reset_window:
        frame = _group_route_store_fields(state, frame, 0xFFFFF388, 0, 2, True)
        frame = _group_route_store_fields(state, frame, 0xFFFFF386, 0, 2, True)
        frame = _group_route_call_fields(state, frame, 0xC0B6, 0x1CD5A)
        frame = _group_route_store_fields(state, frame, 0xFFFFF612, 0x208)
        frame = _group_route_store_fields(state, frame, 0xFFFFF362, 3)
        frame = _group_route_store_fields(state, frame, 0xFFFFF36A, 0x12)
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFEFBE).cursor())
    while True:
        value = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_test(state, frame, value, 16)
        if not frame.status & 8:
            break
        frame = _group_route_register_delta_fields(state, frame, 'target_x', 2)
    frame = _group_route_store_fields(state, frame, 0xFFFFEFC6, low16(frame.target_x))
    return _group_route_call_fields(state, frame, 0xC832, 0x1CD86)


def prepare_city_surviving_group_selection_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1CD88: selected packet; invisible owners branch directly into 1CE4A."""
    frame = _resource_cost_frame(state, frame, 0x1CD88)
    frame = first_replace(frame, roster=state.table_at(state.read(0x00FF382C, 4)).cursor())
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(4), 8)
    frame, owner_visible = _city_result_owner_match_fields(state, frame,
        (0xFFFFF67A, 0xFFFFF67C, 0xFFFFF67E))
    if owner_visible:
        frame = _group_route_store_fields(state, frame, 0xFFFFF376, low16(frame.target_x))
        return _city_result_build_survivor_roster_fields(state, frame)
    return _city_result_prepare_invisible_group_fields(state, frame)


def prepare_city_surviving_group_selection_alternate_1_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1CE06 is an internal shared-tail entry, never another whole credited owner.

    Re-entry into 1CDB0 is a structured branch, not an invented BSR or a host
    recursion. The current live packet pointer and all WORD high halves survive.
    """
    frame = _resource_cost_frame(state, frame, 0x1CE06)
    frame = _group_route_store_fields(state, frame, 0xFFFFF3F2, state.read(0xFFFFF3A6, 2))
    frame = first_replace(frame, roster=state.table_at(0xFFFF9000).cursor(), candidates=state.table_at(0xFFFFEFBE).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFEFC6, 2), 16)
    frame = _movement_move(state, frame, 'target_x', frame.candidates.word(low16(frame.target_x)), 16)
    frame = first_replace(frame, roster=state.table_at(u32(frame.roster.address() + s16(low16(frame.target_x)))).cursor())
    frame = _group_route_store_fields(state, frame, 0x00FF3ECE, frame.roster.address(), 4)
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(4), 8)
    frame = _group_route_store_fields(state, frame, 0xFFFFF376, low16(frame.target_x))
    frame, owner_visible = _city_result_owner_match_fields(state, frame,
        (0xFFFFF67A, 0xFFFFF67C, 0xFFFFF67E))
    if owner_visible:
        return _city_result_build_survivor_roster_fields(state, frame)
    return _city_result_prepare_invisible_group_fields(state, frame)


def _city_result_prepare_invisible_group_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Shared 1CE4A path; current A0 is retained from either actual entry."""
    frame = _group_route_call_fields(state, frame, 0x1CE70, 0x1CE4E)
    frame = _group_route_store_fields(state, frame, 0xFFFFF386, 0, 2, True)
    frame = _group_route_store_fields(state, frame, 0xFFFFF388, 0, 2, True)
    frame = _group_route_call_fields(state, frame, 0xC0B6, 0x1CE5C)
    frame = _group_route_store_fields(state, frame, 0xFFFFF612, 0x208)
    frame = _group_route_store_fields(state, frame, 0xFFFFF362, 3)
    return _group_route_store_fields(state, frame, 0xFFFFF36A, 0x12)


def _city_result_build_survivor_roster_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Shared 1CDB0 member expansion and window setup; no duplicated algorithm."""
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(), 8)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)
    frame = _group_route_store_fields(state, frame, 0xFFFFF636, low16(frame.target_x))
    frame = _group_route_register_delta_fields(state, frame, 'target_x', -1)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFF500).cursor())
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    while True:
        frame = _movement_move(state, frame, 'target_y', frame.roster.advance(13).byte(low16(frame.target_x)), 8)
        frame = _group_route_store_fields(state, frame, frame.candidates.address(), low16(frame.target_y))
        frame = first_replace(frame, candidates=frame.candidates.advance(2))
        frame = _city_menu_db_word_fields(frame, 'target_x')
        if low16(frame.target_x) == 65535:
            break
    frame = _group_route_store_fields(state, frame, frame.candidates.address(), 65535)
    frame = _group_route_store_fields(state, frame, 0xFFFFF612, 0x206)
    frame = _group_route_store_fields(state, frame, 0xFFFFF362, 8)
    frame = _group_route_store_fields(state, frame, 0xFFFFF36A, 0, 2, True)
    frame = _group_route_store_fields(state, frame, 0xFFFFF36E, 0, 2, True)
    frame = _group_route_store_fields(state, frame, 0xFFFFF378, 1)
    frame = _group_route_store_fields(state, frame, 0xFFFFF372, state.read(0xFFFFF500, 2))
    frame = _group_route_store_fields(state, frame, 0xFFFFF658, 0, 2, True)
    frame = _group_route_store_fields(state, frame, 0xFFFFF656, 0, 2, True)
    frame = _group_route_store_fields(state, frame, 0xFFFFF600, 0x70)
    return _group_route_call_fields(state, frame, 0x1626C, 0x1CE04)


def select_city_surviving_group_strongest_member_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1CE70: reverse member scan, strict greater score and retained D2 on no improvement."""
    frame = _resource_cost_frame(state, frame, 0x1CE70)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFB400).cursor())
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(), 8)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)
    frame = _group_route_register_delta_fields(state, frame, 'target_x', -1)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'count', 0, 16)
    while True:
        frame = _movement_move(state, frame, 'count', frame.roster.advance(13).byte(low16(frame.target_x)), 8)
        frame = _movement_move(state, frame, 'distance', low16(frame.count), 16)
        frame = _movement_fixed_shift_word(state, frame, 'distance', 1)
        frame = _movement_move(state, frame, 'offset_x', frame.candidates.word(low16(frame.distance)), 16)
        frame = _movement_compare(state, frame, low16(frame.offset_x), low16(frame.target_y), 16)
        if not frame.status & 5:
            frame = _movement_move(state, frame, 'target_y', low16(frame.offset_x), 16)
            frame = _movement_move(state, frame, 'unit', low16(frame.count), 16)
        frame = _city_menu_db_word_fields(frame, 'target_x')
        if low16(frame.target_x) == 65535:
            break
    return _group_route_store_fields(state, frame, 0xFFFFF3A6, low16(frame.unit))

def locate_arrival_city_frame_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """164D4..16588: inspect forty real city rectangles, retaining all carriers.

    The middle-column comparison of D7 to D5 at1653E is intentional original
    behavior, not a corrected coordinate test. The actual caller owns RTS.
    """
    frame = _resource_cost_frame(state, frame, 0x164D4)
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_x', frame.candidates.byte(2), 8)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 4)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'target_y', frame.candidates.byte(1), 8)
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 4)
    frame = first_replace(frame, controller=state.table_at(0xD4ACA).cursor(),
        scan=state.table_at(0xFFFFF428).cursor())
    frame = _movement_move(state, frame, 'count', 39, 16)
    frame = _movement_move(state, frame, 'distance', 0, 16)
    frame = _duel_menu_write_word_fields(state, frame, 0xFFFFF392, 1)
    found = False
    while True:
        frame = _movement_move(state, frame, 'offset_x', frame.controller.word(), 16)
        frame = first_replace(frame, controller=frame.controller.advance(2))
        frame = _movement_move(state, frame, 'offset_y', frame.controller.word(), 16)
        frame = first_replace(frame, controller=frame.controller.advance(2))
        frame = _movement_move(state, frame, 'choice', low16(frame.offset_y), 16)
        frame = _duel_commit_sub_word_fields(state, frame, 'choice', 24)
        frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.choice), 16)
        if frame.status & 4:
            frame = _movement_move(state, frame, 'choice', low16(frame.offset_x), 16)
            frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.choice), 16)
            if frame.status & 4:
                found = True
                break
            frame = _duel_commit_sub_word_fields(state, frame, 'choice', 16)
            frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.choice), 16)
            if frame.status & 4:
                found = True
                break
        frame = _movement_move(state, frame, 'choice', low16(frame.offset_y), 16)
        frame = _duel_commit_sub_word_fields(state, frame, 'choice', 8)
        frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.choice), 16)
        if frame.status & 4:
            frame = _movement_move(state, frame, 'choice', low16(frame.offset_x), 16)
            frame = _movement_add_word(state, frame, 'choice', 16)
            frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.choice), 16)
            if frame.status & 4:
                found = True
                break
            frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.offset_x), 16)
            if frame.status & 4:
                found = True
                break
            frame = _movement_move(state, frame, 'choice', low16(frame.offset_x), 16)
            frame = _duel_commit_sub_word_fields(state, frame, 'choice', 16)
            # Original1653E BE45 compares D5 to D7, not D0 to D7.
            frame = _movement_compare(state, frame, low16(frame.choice), low16(frame.offset_x), 16)
            if frame.status & 4:
                found = True
                break
            frame = _movement_move(state, frame, 'choice', low16(frame.offset_x), 16)
            frame = _duel_commit_sub_word_fields(state, frame, 'choice', 32)
            frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.choice), 16)
            if frame.status & 4:
                found = True
                break
        frame = _movement_move(state, frame, 'choice', low16(frame.offset_y), 16)
        frame = _movement_add_word(state, frame, 'choice', 8)
        frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.choice), 16)
        if frame.status & 4:
            frame = _movement_move(state, frame, 'choice', low16(frame.offset_x), 16)
            frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.choice), 16)
            if frame.status & 4:
                found = True
                break
            frame = _duel_commit_sub_word_fields(state, frame, 'choice', 16)
            frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.choice), 16)
            if frame.status & 4:
                found = True
                break
        frame = _movement_add_word(state, frame, 'distance', 1)
        frame, city = _movement_binary_flags(state, frame, state.read(0xFFFFF392, 2), 1, 16, False)
        state.write(0xFFFFF392, 2, city)
        frame = first_replace(frame, count=replace_word(frame.count, u16(low16(frame.count)-1)))
        if low16(frame.count) == 65535:
            break
    if found:
        frame = first_replace(frame, controller=state.table_at(0xFFFFF428).cursor())
        frame = _movement_move(state, frame, 'target_x', 0, 16)
        return _movement_move(state, frame, 'target_x', frame.controller.byte(low16(frame.distance)), 8)
    return _movement_move(state, frame, 'target_x', 16, 16)

def encode_live_group_coordinate_packet_frame_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """1CEA0..1CF58: collect four real neighbor offsets, then count survivors.

    D5's incoming high BYTE is intentionally part of the packed-record stride.
    Original00FF382C pointer, partial writes and final D1 DBRA are preserved.
    """
    frame = _resource_cost_frame(state, frame, 0x1CEA0)
    frame = first_replace(frame, roster=state.table_at(state.read(0x00FF382C, 4)).cursor())
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(1), 8)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 8)
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(2), 8)
    frame = _movement_move(state, frame, 'choice', frame.roster.byte(4), 8)
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
    frame = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)
    frame = _movement_move(state, frame, 'count', low16(frame.target_x), 16)
    frame = _duel_commit_sub_word_fields(state, frame, 'target_x', 256)
    frame = _movement_add_word(state, frame, 'target_y', 1)
    frame = _movement_add_word(state, frame, 'unit', 256)
    frame = _duel_commit_sub_word_fields(state, frame, 'count', 1)
    for address in (0xFFFFEFBE, 0xFFFFEFC2):
        state.write(address, 4, 0xFFFFFFFF)
        frame = _movement_test_long(state, frame, 0xFFFFFFFF)
    frame = first_replace(frame, candidates=state.table_at(0xFFFF9000).cursor())
    frame = _movement_move(state, frame, 'distance', 0, 16)
    while True:
        offset = low16(frame.distance)
        frame = _movement_move(state, frame, 'offset_x', frame.candidates.byte(offset), 8)
        frame = _movement_move(state, frame, 'offset_x', low8(frame.offset_x) & 15, 8)
        if frame.status & 4:
            break
        frame = _group_route_bit_fields(state, frame, frame.candidates.byte(offset), 5)
        if not frame.status & 4:
            frame = _movement_add_word(state, frame, 'distance', 13)
            frame = _movement_add_word(state, frame, 'distance', low16(frame.offset_x))
            continue
        frame = _movement_compare(state, frame, low8(frame.choice), frame.candidates.byte(offset, 4), 8)
        if not frame.status & 4:
            frame = _movement_move(state, frame, 'offset_y', frame.candidates.byte(offset, 1), 8)
            frame = _movement_fixed_shift_word(state, frame, 'offset_y', 8)
            frame = _movement_move(state, frame, 'offset_y', frame.candidates.byte(offset, 2), 8)
            for carrier, address in (('target_x', 0xFFFFEFBE), ('target_y', 0xFFFFEFC0),
                    ('unit', 0xFFFFEFC2), ('count', 0xFFFFEFC4)):
                frame = _movement_compare(state, frame, low16(frame.offset_y), low16(frame.carrier(carrier)), 16)
                if frame.status & 4:
                    frame = _duel_menu_write_word_fields(state, frame, address, low16(frame.distance))
                    break
        frame = _movement_add_word(state, frame, 'distance', 13)
        frame = _movement_add_word(state, frame, 'distance', low16(frame.offset_x))
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_y', 3, 16)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFEFBE).cursor())
    while True:
        frame = _movement_test(state, frame, frame.candidates.word(), 16)
        frame = first_replace(frame, candidates=frame.candidates.advance(2))
        if not frame.status & 8:
            frame = _movement_add_word(state, frame, 'target_x', 1)
        frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(low16(frame.target_y)-1)))
        if low16(frame.target_y) == 65535:
            return frame

def _append_city_decimal_tail_fields(state: SceneState, frame: FirstDeploymentFrame,
        include_hundreds: bool, include_thousands: bool=False, include_ten_thousands: bool=False) -> FirstDeploymentFrame:
    """12734/1273C/12744/1274C retain the sole12760 kernel and real RTS slots.

    Incoming D0.L, D4.W started state and all high WORDs remain real. This is
    a tail-entry adapter, not another decimal digit implementation.
    """
    if include_thousands and not include_hundreds:
        raise ValueError('actual1273C thousands tail also includes hundreds')
    if include_ten_thousands and not (include_thousands and include_hundreds):
        raise ValueError('actual12734 tail includes thousands and hundreds')
    frame = _resource_cost_frame(state, frame, 0x12734 if include_ten_thousands else 0x1273C if include_thousands else 0x12744 if include_hundreds else 0x1274C)
    from ..high_level_player_commands.business_budget import _decimal_value_place_fields
    from ..high_level_player_commands.contexts_numeric import DecimalMemory
    numeric = DecimalMemory(state, frame.stack_cursor)
    destination = state.table_at(frame.auxiliary.base).cursor()
    digit_tile = low16(frame.target_y)
    places = ((100, 0x1274C), (10, 0x12754)) if include_hundreds else ((10, 0x12754),)
    if include_thousands:
        places = ((1000, 0x12744),) + places
    if include_ten_thousands:
        places = ((10000, 0x1273C),) + places
    for divisor, continuation in places:
        frame = _movement_move(state, frame, 'count', divisor, 16)
        numeric.enter_call(continuation)
        result = _decimal_value_place_fields(numeric, frame.target_x, divisor,
            digit_tile, low16(frame.unit), low16(frame.distance), destination)
        numeric.leave_call(continuation)
        frame = first_replace(frame, target_x=result.remainder,
            distance=replace_word(frame.distance, result.started),
            offset_x=replace_word(frame.offset_x, result.glyph), stack_cursor=numeric.stack_cursor)
    frame = _movement_move(state, frame, 'offset_x', 0, 16)
    frame = _movement_move(state, frame, 'offset_x', numeric.glyph(low16(frame.target_x)), 8)
    frame = _movement_add_word(state, frame, 'offset_x', digit_tile)
    destination.append_word(low16(frame.offset_x))
    frame = first_replace(frame, auxiliary=destination, stack_cursor=numeric.stack_cursor)
    return _movement_test(state, frame, low16(frame.offset_x), 16)

def append_city_three_place_decimal_tail_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Actual12744 middle entry: hundreds, tens, then the live ones glyph."""
    return _append_city_decimal_tail_fields(state, frame, True)

def append_city_two_place_decimal_tail_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Actual1274C middle entry: tens, then the live ones glyph."""
    return _append_city_decimal_tail_fields(state, frame, False)

def append_city_four_place_decimal_tail_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Actual1273C middle entry: thousands, hundreds, tens and live ones glyph.

    The1270A leading subtraction and both CLR prefixes are not re-executed.
    The actual parent owns the outer LONG; only12760 place calls push/pop here.
    """
    return _append_city_decimal_tail_fields(state, frame, True, True)


def append_city_five_place_decimal_tail_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Actual12734 middle entry: ten-thousands, then the existing1273C tail.

    The original12760 BSR owns return1273C, not a synthetic extra facade slot.
    Incoming D4 started state, D0.L and high WORDs stay live. No CLR prefix.
    """
    return _append_city_decimal_tail_fields(state, frame, True, True, True)


def deploy_selected_group_from_object_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Exact0x1b24c shared original tail; no extra physical CALL."""
    frame = _resource_cost_frame(state, frame, 111180)
    frame = _deployment_menu_call_fields(state, frame, 111890, 111184)
    frame = _deployment_menu_call_fields(state, frame, 111202, 111188)
    frame = _deployment_menu_call_fields(state, frame, 111226, 111192)
    frame = _deployment_menu_call_fields(state, frame, 111292, 111196)
    return _deployment_menu_call_fields(state, frame, 111730, 111200)
